export function localizedAgentGuidesPartF(en: Guides): Partial<Record<LandingLocaleCode, Guides>> {
  return {
    'es': {
      'claude-code': {
        ...en['claude-code']!,
        title: "Claude Code para diseño — Open Design",
        description: "Cómo los diseñadores usan Claude Code para diseño de UI y web, y cómo Open Design lo convierte en un verdadero agente de diseño — local-first, BYOK, con una biblioteca curada de skills y sistemas de diseño.",
        breadcrumb: "Claude Code",
        label: "Agente · Claude Code",
        heading: "Claude Code para diseño.",
        lead: "Claude Code es el agente de codificación de terminal de Anthropic. La gente ya lo usa para construir interfaces, sistemas de diseño y landing pages. Open Design lo conecta a un flujo de trabajo de diseño real — usa tu clave de Anthropic o tu suscripción a Claude y mantén cada archivo en local.",
        rich: {"heroCtaLead": "Open Design convierte Claude Code en un agente de diseño open-source y local-first — tu clave de Anthropic o tu suscripción a Claude, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa Claude Code dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Claude Code es ampliamente considerado el agente de codificación con mejor gusto para el frontend — razona sobre las interfaces con una especificidad inusual, nombrando valores hex exactos, espaciados y escalas tipográficas, y refactoriza la UI a lo largo de una base de código grande sin perder el hilo. Pero, listo para usar, sigue derivando hacia un aspecto genérico a menos que le entregues un sistema de diseño, skills y referencias reales. Esta es una guía práctica y de extremo a extremo para usar Claude Code en trabajo de UI, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo estructurado con Open Design.", "Cubre qué es realmente Claude Code, por qué es fuerte en frontend, cómo configurarlo desde cero, el flujo de trabajo de CLAUDE.md y Skills, el round-trip oficial con Figma, cómo se compara con Codex y Cursor, los escollos que hacen que el resultado de la IA parezca genérico y cómo Open Design cierra esa brecha como una capa de diseño abierta y local-first."], "heroImage": {"src": "/agents/claude-code-design/claude-code-design-hero.webp", "alt": "Bucle de retroalimentación de diseño de Claude Code: un agente de terminal tomando decisiones de diseño específicas, un navegador renderizando la UI y un espacio de trabajo, con una flecha de retroalimentación que regresa en bucle", "caption": "El bucle central: Claude Code razona decisiones de UI específicas en la terminal, las renderiza y verifica en un navegador real, y converge contra tus referencias."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-claude-code", "label": "Qué es realmente Claude Code"}, {"id": "why-design", "label": "Por qué Claude Code es bueno en diseño"}, {"id": "setup", "label": "Configura Claude Code para diseño (desde cero)"}, {"id": "skills-workflow", "label": "El flujo de trabajo de CLAUDE.md y Skills"}, {"id": "figma", "label": "Round-trip de Claude Code + Figma"}, {"id": "vs", "label": "Claude Code vs Codex vs Cursor"}, {"id": "pitfalls", "label": "Escollos y el aspecto de “bazofia de IA”"}, {"id": "open-design", "label": "Diseñar con Claude Code en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-claude-code", "heading": "Qué es realmente Claude Code", "blocks": [{"kind": "p", "text": "Claude Code es la herramienta de codificación agéntica de Anthropic. Lee tu base de código, edita archivos, ejecuta comandos y se integra con tus herramientas de desarrollo — planifica, escribe y verifica el trabajo a partir de tareas en lenguaje natural, en lugar de limitarse a autocompletar líneas."}, {"kind": "p", "text": "Se distribuye en varias superficies que comparten el mismo motor: una CLI de terminal, extensiones de IDE para VS Code, Cursor y JetBrains, una aplicación de escritorio con revisión visual de diferencias, y una experiencia web para tareas de larga duración. Tus archivos CLAUDE.md, ajustes y servidores MCP se trasladan a todas ellas."}, {"kind": "steps", "items": [{"label": "Archivo de instrucciones", "body": "Claude Code lee un archivo CLAUDE.md en la raíz de tu proyecto al inicio de cada sesión — el lugar natural para codificar tus convenciones de diseño, tokens y listas de verificación de revisión."}, {"label": "Skills", "body": "Las Agent Skills empaquetan instrucciones, scripts y recursos reutilizables que Claude carga bajo demanda, incluida la skill oficial de Frontend Design de Anthropic para el gusto."}, {"label": "Planificación y subagentes", "body": "Puede planificar antes de actuar y generar subagentes que trabajan en distintas partes de una tarea en paralelo, lo que mantiene coherentes las refactorizaciones grandes de UI."}]}, {"kind": "ul", "items": ["Proveedor: Anthropic", "Credencial: clave de API de Anthropic (BYOK, a través de la Console) o una suscripción a Claude (Pro / Max)", "Superficies: CLI de terminal, extensiones de VS Code / Cursor / JetBrains, aplicación de escritorio, web"]}]}, {"id": "why-design", "heading": "Por qué Claude Code es bueno en diseño", "blocks": [{"kind": "p", "text": "Entre los agentes de codificación, Claude Code tiene reputación de buen gusto en el trabajo de frontend. Hay varias razones que lo explican."}, {"kind": "steps", "items": [{"label": "Decisiones específicas, no vagas", "body": "Claude Code tiende a comprometerse con opciones concretas — valores hex exactos, escalas de espaciado, rampas tipográficas y jerarquía de componentes — en lugar de andar con rodeos, que es lo que separa una interfaz real de un marcador de posición."}, {"label": "Razonamiento consciente de la base de código", "body": "Con un contexto de trabajo amplio, refactoriza la UI a través de muchos archivos a la vez, reutilizando tus componentes y tokens existentes en lugar de reinventar estilos puntuales."}, {"label": "Una skill de frontend oficial", "body": "Anthropic ofrece una skill de Frontend Design que hace que Claude escriba primero una dirección de diseño y se aleje deliberadamente de las fuentes de sistema genéricas y los predecibles degradados morados."}]}, {"kind": "image", "src": "/agents/claude-code-design/claude-code-design-taste-triangle.webp", "alt": "Diagrama que muestra el sistema de diseño, la skill y la imagen de referencia convergiendo en un buen resultado de diseño", "caption": "El gusto proviene de tres insumos que tú aportas: un sistema de diseño, una skill e imágenes de referencia reales."}, {"kind": "p", "text": "La lección es la misma que Anthropic plantea sobre sus propios modelos: Claude no tiene gusto por defecto — librado a su suerte, converge hacia el centro estadístico del diseño web (Inter, degradados morados, sombras suaves). Produce buen diseño cuando le das restricciones. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan (más abajo)."}]}, {"id": "setup", "heading": "Configura Claude Code para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un Claude Code capaz de construir y verificar UI."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Claude Code (native install, recommended)\ncurl -fsSL https://claude.ai/install.sh | bash\n# or: brew install --cask claude-code\n# Windows PowerShell: irm https://claude.ai/install.ps1 | iex\n\n# 2. Start it in your project and sign in on first run\ncd your-project\nclaude            # sign in with your Claude subscription or API key\n\n# 3. Generate project context\n/init             # creates a CLAUDE.md for this project\n\n# 4. Add the official Frontend Design skill\nclaude plugin install frontend-design@claude-plugins-official\n\n# 5. Wire the Figma MCP server (optional, for design handoff)\nclaude plugin install figma@claude-plugins-official"}, {"kind": "image", "src": "/agents/claude-code-design/claude-code-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticar, configurar CLAUDE.md, añadir skill, verificar", "caption": "La secuencia de configuración: instalar → autenticar → configurar CLAUDE.md → añadir la skill de Frontend Design → habilitar la verificación en el navegador."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Coloca tus tokens, primitivas y convenciones en CLAUDE.md y dirige a Claude hacia ellas, para que el resultado coincida con una marca en lugar de recaer en un aspecto genérico."}, {"label": "Añade verificación en el navegador", "body": "Conecta un MCP de Playwright o Chrome para que Claude renderice en un navegador real y compruebe su resultado en distintos breakpoints, en lugar de solo confirmar que la compilación pasa."}]}]}, {"id": "skills-workflow", "heading": "El flujo de trabajo de CLAUDE.md y Skills", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor apalancamiento con Claude Code es alimentarlo con referencias reales más tu contexto de diseño, y luego iterar hasta que la UI coincida — con CLAUDE.md y Skills llevando las restricciones, para que no las vuelvas a explicar en cada prompt."}, {"kind": "ol", "items": ["Parte de las referencias visuales más claras que tengas — e incluye varios estados (escritorio y móvil, hover, vacío, cargando), no solo una única toma principal.", "Sé específico en el prompt; los prompts vagos producen UI genérica incluso con un agente potente.", "Mantén tu sistema de diseño y tus convenciones en CLAUDE.md, e indícale a Claude dónde viven los tokens y las primitivas canónicas.", "Añade la skill de Frontend Design para que Claude se comprometa con una dirección estética real antes de escribir código.", "Conecta la verificación en el navegador para que Claude renderice, redimensione a los breakpoints y compare con las referencias — no solo confirme que compila."]}, {"kind": "p", "text": "Arrastra una imagen de referencia a la sesión y formula el prompt con restricciones concretas:"}, {"kind": "code", "lang": "bash", "code": "claude \"Implement reference-desktop.png and reference-mobile.png in\n  React + Vite + Tailwind + TypeScript.\n  Reuse the design-system components and tokens described in CLAUDE.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Render it in the browser, verify it matches the references across\n  breakpoints, and iterate until it does.\""}, {"kind": "p", "text": "Ejecuta un servidor de desarrollo en paralelo, mantén los prompts pequeños y enfocados, y confirma las buenas iteraciones / revierte las malas (diciéndole a Claude cuándo reviertes) para que cada pasada parta de una base limpia. Usa el modo de planificación para refactorizaciones más grandes, de modo que puedas revisar el enfoque antes de que se modifique cualquier archivo."}]}, {"id": "figma", "heading": "Claude Code + Figma: round-trip diseño ↔ código", "blocks": [{"kind": "p", "text": "En febrero de 2026, Anthropic y Figma lanzaron una integración bidireccional de primera clase a través del servidor MCP de Figma. Funciona en ambas direcciones."}, {"kind": "steps", "items": [{"label": "Diseño → Código", "body": "Selecciona un frame en Figma o pega un enlace en Claude Code, extrae el contexto de diseño y pídele que implemente el diseño usando tu biblioteca de componentes existente. Code Connect mantiene el resultado alineado con tus componentes reales."}, {"label": "Código → Diseño", "body": "Construye y previsualiza una funcionalidad en el navegador, y luego di “Send this to Figma” para capturar la UI en ejecución como capas editables de Figma — pantalla completa o un elemento seleccionado."}]}, {"kind": "p", "text": "Instálalo una vez con claude plugin install figma@claude-plugins-official (el MCP de Dev Mode requiere un plan de pago de Figma). El mismo MCP de Figma está disponible para Claude Code, Codex, Cursor y VS Code — exactamente el tipo de capacidad portátil y multiagente que Open Design está hecho para orquestar."}]}, {"id": "vs", "heading": "Claude Code vs Codex vs Cursor para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño — cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Mejor para"], "rows": [["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y razonamiento de UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"], ["Codex", "Fuerte pulido visual y comprensión de imágenes; compilaciones asíncronas en sandbox", "Compilaciones asíncronas delegadas y reglas portátiles de AGENTS.md"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de UI ajustado de iterar y observar dentro de un IDE"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el gusto proviene de las personas: los tres recaen en una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver — y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Escollos y cómo evitar el aspecto de “bazofia de IA”", "blocks": [{"kind": "p", "text": "Incluso con la reputación de buen gusto de Claude Code, la queja más común sobre el diseño generado por IA es que parece genérico — fuentes Inter, degradados morados sobre blanco, sombras suaves, esquinas redondeadas excesivas, una estética que “grita que esto lo hizo una IA”. La propia Anthropic lo atribuye a la convergencia distribucional: las opciones seguras dominan los datos de entrenamiento web. Otros problemas reportados incluyen diseños móviles rotos e instrucciones que se filtran en el texto de la UI."}, {"kind": "steps", "items": [{"label": "Instala la skill de Frontend Design", "body": "Obliga a Claude a comprometerse con una dirección real y evita explícitamente las fuentes y degradados sobreutilizados por la IA."}, {"label": "Habilita la verificación en el navegador", "body": "Haz que Claude renderice y se autoverifique en distintos breakpoints para que los diseños no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de referencia son la mayor palanca sobre la calidad del resultado."}, {"label": "Codifica reglas en CLAUDE.md", "body": "Pon reglas de estilo como “sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca” donde el agente las lea en cada ejecución."}]}, {"kind": "p", "text": "Observa que cada mitigación consiste en dar al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es el trabajo pesado que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con Claude Code dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño open-source que el flujo de trabajo anterior no deja de pedir. Trata a Claude Code como un adaptador de primera parte y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de render estructurada y una UI de escritorio local — para que el contexto de diseño que hace bueno a Claude Code esté ahí desde la primera ejecución, no se ensamble a mano cada vez."}, {"kind": "ol", "items": ["Instala Open Design y selecciona Claude Code como tu agente.", "Autentícate con tu clave de API de Anthropic (BYOK) o tu suscripción a Claude — las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y una skill, y luego genera presentaciones, prototipos y landing pages con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente Claude Code, la misma clave — más un flujo de trabajo de diseño real, portátil y open-source a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Es Claude Code bueno para el trabajo de diseño?", "text": "Sí — es ampliamente considerado el agente de codificación con mejor gusto para el frontend, tomando decisiones específicas y conscientes de la base de código sobre valores hex, espaciado y escalas tipográficas. Con la skill de Frontend Design, un sistema de diseño e imágenes de referencia reales en contexto, produce UI responsive de calidad de producción y puede verificarla en un navegador. Sin ese contexto tiende a recaer en un aspecto genérico, que es la brecha que Open Design cubre."}, {"name": "¿Necesito una suscripción a Claude para diseñar con Claude Code?", "text": "Puedes usar una clave de API de Anthropic (BYOK, a través de la Console) o una suscripción a Claude (Pro / Max). En cualquier caso, Open Design nunca actúa como proxy de tus credenciales — las usa directamente tu agente en tu máquina."}, {"name": "¿Claude Code o Codex para diseño de frontend?", "text": "Ambos son fuertes. Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código y por su razonamiento de frontend; Codex tiene un fuerte pulido visual y destaca en compilaciones delegadas en sandbox. Muchos equipos usan ambos — Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto Claude Code con Figma?", "text": "Instala el plugin oficial de Figma con claude plugin install figma@claude-plugins-official. Después podrás implementar frames de Figma en código usando el contexto de diseño, y enviar una UI en ejecución de vuelta a frames editables de Figma con “Send this to Figma”. El MCP de Dev Mode requiere un plan de pago de Figma."}, {"name": "¿Qué son las Skills y CLAUDE.md?", "text": "CLAUDE.md es un archivo markdown en la raíz de tu proyecto que Claude Code lee al inicio de cada sesión — el lugar para codificar tus convenciones de diseño. Las Skills empaquetan instrucciones y recursos reutilizables que Claude carga bajo demanda, incluida la skill oficial de Frontend Design de Anthropic. Open Design incluye una biblioteca curada de ambos para que te saltes la configuración por proyecto."}, {"name": "¿Cómo evito la estética genérica de “bazofia de IA”?", "text": "Instala la skill de Frontend Design, aporta tokens de diseño reales y capturas de referencia, codifica las reglas de marca en CLAUDE.md y habilita la verificación en el navegador. Open Design incluye todo esto como una biblioteca curada para que te saltes la configuración por proyecto."}, {"name": "¿Está Open Design afiliado a Anthropic?", "text": "No. Claude Code es un producto de Anthropic; Open Design es un proyecto open-source independiente que lo soporta como adaptador de primera parte. Claude y Claude Code son marcas comerciales de Anthropic."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí — Open Design es local-first y Apache-2.0. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de Anthropic las usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con Claude Code, a la manera abierta.", "ctaBody": "Usa tu propia clave de Anthropic o tu suscripción a Claude, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente que ya usas.", "ctaActions": [{"label": "Usa Claude Code dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'codex': {
        ...en['codex']!,
        title: "Codex para diseño — Open Design",
        description: "Cómo la gente usa OpenAI Codex para diseño de UI y web — el plugin de Product Design, la integración con Figma, las skills de frontend — y cómo Open Design convierte a Codex en un agente de diseño open-source y local-first.",
        breadcrumb: "Codex",
        label: "Agente · Codex",
        heading: "Codex para diseño.",
        lead: "Codex es el agente de codificación de OpenAI. Con su plugin de Product Design y su integración con Figma se ha convertido en una herramienta de diseño seria. Open Design conecta a Codex con un flujo de trabajo de diseño open-source — tu clave de OpenAI o tu suscripción a ChatGPT, tus archivos, local-first.",
        rich: {"heroCtaLead": "Open Design convierte a Codex en un agente de diseño open-source y local-first — tu clave de OpenAI, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa Codex dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["OpenAI Codex empezó como un generador de código, pero en 2026 se convirtió en una herramienta creíble para diseñar interfaces reales — una vez que le das las referencias, skills y el bucle de verificación adecuados. Esta es una guía práctica y de extremo a extremo para usar Codex en trabajo de UI, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es Codex hoy, por qué de repente es bueno en frontend, cómo configurarlo desde cero, el bucle de captura a UI, el round-trip oficial con Figma, cómo se compara con Cursor y Claude Code, los escollos que hacen que el resultado de la IA parezca genérico y cómo Open Design cierra esa brecha como una capa de diseño abierta y local-first."], "heroImage": {"src": "/agents/codex-design/codex-design-workflow-loop.webp", "alt": "Bucle de retroalimentación de diseño de Codex: un agente de terminal, un navegador renderizando la UI y un espacio de trabajo, con una flecha de retroalimentación que regresa en bucle", "caption": "El bucle central: Codex construye la UI en la terminal, la renderiza y verifica en un navegador real, e itera contra tus referencias."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-codex", "label": "Qué es realmente OpenAI Codex"}, {"id": "why-design", "label": "Por qué Codex es bueno en diseño ahora"}, {"id": "setup", "label": "Configura Codex para diseño (desde cero)"}, {"id": "screenshot-workflow", "label": "El flujo de trabajo de captura a UI"}, {"id": "figma", "label": "Round-trip de Codex + Figma"}, {"id": "vs", "label": "Codex vs Cursor vs Claude Code"}, {"id": "pitfalls", "label": "Escollos y el aspecto de “bazofia de IA”"}, {"id": "open-design", "label": "Diseñar con Codex en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-codex", "heading": "Qué es realmente OpenAI Codex (y qué no es)", "blocks": [{"kind": "p", "text": "Primero, una aclaración que confunde a casi todos los que buscan “Codex”. El Codex original de OpenAI era un modelo de autocompletado de código de 2021 que impulsaba los primeros GitHub Copilot y fue descontinuado en 2023. No es de eso de lo que trata esta página. El Codex de hoy es la herramienta de codificación agéntica de OpenAI — planifica, escribe, ejecuta y verifica código a partir de tareas en lenguaje natural."}, {"kind": "p", "text": "El Codex moderno se distribuye en cuatro superficies: una CLI de terminal (reescrita en Rust, con licencia Apache-2.0), una extensión de IDE para VS Code, Cursor y Windsurf, una experiencia cloud/web para tareas asíncronas delegadas, y una aplicación de escritorio con un navegador integrado y Computer Use."}, {"kind": "steps", "items": [{"label": "Modelo por defecto", "body": "A mediados de 2026, el modelo recomendado es gpt-5.5, siendo gpt-5.4 el modelo que OpenAI entrenó explícitamente para frontend y computer use."}, {"label": "Archivo de instrucciones", "body": "Codex lee un archivo AGENTS.md en tu proyecto (un estándar entre herramientas) para las reglas del proyecto — el lugar natural para codificar tus convenciones de diseño."}, {"label": "Sandbox", "body": "Se ejecuta en un sandbox a nivel de kernel (workspace-write por defecto), de modo que un agente que edita tu UI no puede salirse del proyecto."}]}, {"kind": "ul", "items": ["Proveedor: OpenAI", "Credencial: clave de API de OpenAI (BYOK) o suscripción a ChatGPT (Free / Go / Plus / Pro / Business / Enterprise)", "Licencia de la CLI: Apache-2.0, open source"]}]}, {"id": "why-design", "heading": "Por qué Codex es bueno en diseño ahora", "blocks": [{"kind": "p", "text": "Tres cosas convergieron a principios de 2026 para convertir a Codex en una verdadera herramienta de diseño en lugar de un generador de código genérico."}, {"kind": "steps", "items": [{"label": "Un modelo entrenado para frontend", "body": "OpenAI lanzó GPT-5.4, su primer modelo principal entrenado para frontend y computer use, con una comprensión de imágenes mucho mejor en todo el flujo de diseño y una autoverificación más sólida. Incluso puede generar mood boards y opciones visuales antes de comprometerse con los assets finales."}, {"label": "Una skill de frontend oficial", "body": "El catálogo openai/skills incluye una skill de frontend curada que impone gusto real: diseños sin tarjetas, heroes a sangre completa, jerarquía centrada en la marca, movimiento contenido, como máximo dos tipografías y un color de acento — y hace que Codex escriba una tesis visual antes de construir."}, {"label": "Verificación en el navegador", "body": "Con la skill de Playwright, Codex abre un navegador real, redimensiona a los breakpoints y compara su resultado con la referencia en lugar de solo comprobar que la compilación pasa."}]}, {"kind": "image", "src": "/agents/codex-design/codex-design-taste-triangle.webp", "alt": "Diagrama que muestra el sistema de diseño, la skill y la imagen de referencia convergiendo en un buen resultado de diseño", "caption": "El gusto proviene de tres insumos que tú aportas: un sistema de diseño, una skill e imágenes de referencia reales."}, {"kind": "p", "text": "La lección detrás de las tres: Codex no tiene gusto por defecto. Produce buen diseño cuando le das restricciones — un sistema de diseño, una skill estética y referencias concretas. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan (más abajo)."}]}, {"id": "setup", "heading": "Configura Codex para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un Codex capaz de construir y verificar UI."}, {"kind": "code", "lang": "bash", "code": "# 1. Install the Codex CLI\nnpm install -g @openai/codex\n# or: brew install --cask codex\n# or: curl -fsSL https://chatgpt.com/codex/install.sh | sh\n\n# 2. Authenticate (ChatGPT sign-in recommended for higher limits)\ncodex            # then choose “Sign in with ChatGPT”\n\n# 3. Generate project context\ncodex            # inside your project, run /init to create AGENTS.md\n\n# 4. Add the official frontend skill, then restart Codex\n# (in the Codex app) $skill-installer frontend-skill\n\n# 5. Wire the Figma MCP server (optional, for design handoff)\ncodex mcp add figma --url https://mcp.figma.com/mcp"}, {"kind": "image", "src": "/agents/codex-design/codex-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticar, configurar, instalar skill, verificar", "caption": "La secuencia de configuración: instalar → autenticar → configurar AGENTS.md → instalar la skill de frontend → habilitar la verificación en el navegador."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Coloca tus tokens, primitivas y convenciones en AGENTS.md o en un DESIGN.md y dirige a Codex hacia ellas, para que el resultado coincida con una marca en lugar de recaer en un aspecto genérico."}, {"label": "Elige el nivel de razonamiento adecuado", "body": "OpenAI señala que los niveles de razonamiento de bajo a medio suelen producir mejores resultados de frontend que el ajuste más alto."}]}]}, {"id": "screenshot-workflow", "heading": "El flujo de trabajo de captura a UI", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor apalancamiento con Codex es convertir una imagen de referencia en una UI funcional y responsive e iterar hasta que coincida. La propia guía de OpenAI se reduce a cinco pasos."}, {"kind": "ol", "items": ["Parte de las referencias visuales más claras que tengas — e incluye varios estados (escritorio y móvil, hover, vacío, cargando), no solo una única toma principal.", "Sé específico en el prompt; los prompts vagos producen UI genérica.", "Prepara un sistema de diseño e indícale a Codex dónde viven los tokens y las primitivas canónicas.", "Habilita la skill interactiva de Playwright para que Codex renderice en un navegador real y redimensione a los breakpoints.", "Itera haciendo que Codex compare su implementación con las capturas — no solo que confirme que compila."]}, {"kind": "p", "text": "Alimenta las imágenes arrastrando una captura a la terminal o con el flag de imagen, y luego formula el prompt con restricciones concretas:"}, {"kind": "code", "lang": "bash", "code": "codex -i reference-desktop.png -i reference-mobile.png \\\n  \"Implement this design in React + Vite + Tailwind + TypeScript.\n   Reuse my existing design-system components and tokens.\n   Match spacing, layout, and hierarchy; make it responsive.\n   Use the Playwright skill to verify the UI matches the\n   references and iterate until it does.\""}, {"kind": "p", "text": "Ejecuta un servidor de desarrollo en una segunda terminal, mantén los prompts pequeños y enfocados, y confirma las buenas iteraciones / revierte las malas (diciéndole a Codex cuándo reviertes) para que cada pasada parta de una base limpia."}]}, {"id": "figma", "heading": "Codex + Figma: round-trip diseño ↔ código", "blocks": [{"kind": "p", "text": "En febrero de 2026, OpenAI y Figma anunciaron una asociación oficial, convirtiendo la beta anterior del MCP de Figma en una integración bidireccional de primera clase. Funciona en ambas direcciones."}, {"kind": "steps", "items": [{"label": "Diseño → Código", "body": "Copia el “link to selection” de un frame en Figma, pégalo en Codex con get_design_context y pídele que implemente el diseño usando tu biblioteca de componentes existente."}, {"label": "Código → Diseño", "body": "La herramienta generate_figma_design (“Code to Canvas”) convierte una UI en vivo y en ejecución de vuelta en frames editables de Figma — pantalla completa, un elemento seleccionado o un archivo entero."}]}, {"kind": "p", "text": "El MCP de Figma se ejecuta como un servidor remoto y está exento de límites de tasa. Añádelo una vez y estará disponible para Codex, Claude Code, Cursor, VS Code y más — exactamente el tipo de capacidad portátil y multiagente que Open Design está hecho para orquestar."}]}, {"id": "vs", "heading": "Codex vs Cursor vs Claude Code para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño — cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Mejor para"], "rows": [["Codex", "Fuerte pulido visual tras GPT-5.4 + skill de frontend; comprensión de imágenes", "Compilaciones asíncronas delegadas, ejecuciones en sandbox, reglas portátiles de AGENTS.md"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de UI ajustado de iterar y observar dentro de un IDE"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el gusto proviene de las personas: los tres recaen en una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver — y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Escollos y cómo evitar el aspecto de “bazofia de IA”", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por Codex es que parece genérico — degradados suaves, paneles flotantes, esquinas redondeadas excesivas, sombras dramáticas, un aire de Inter-y-morado que “grita que esto lo hizo una IA”. Otros problemas reportados incluyen diseños móviles rotos, instrucciones que se filtran en el texto de la UI y alcanzar rápidamente los límites de uso."}, {"kind": "steps", "items": [{"label": "Instala una skill de frontend", "body": "Una skill estética curada obliga a Codex a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Habilita la verificación con Playwright", "body": "Haz que Codex renderice y se autoverifique en distintos breakpoints para que los diseños no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de referencia son la mayor palanca sobre la calidad del resultado."}, {"label": "Codifica reglas en AGENTS.md", "body": "Pon reglas de estilo como “sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca” donde el agente las lea en cada ejecución."}]}, {"kind": "p", "text": "Observa que cada mitigación consiste en dar al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es el trabajo pesado que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con Codex dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño open-source que el flujo de trabajo anterior no deja de pedir. Trata a Codex como un adaptador de primera parte y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de render estructurada y una UI de escritorio local — para que el contexto de diseño que hace bueno a Codex esté ahí desde la primera ejecución, no se ensamble a mano cada vez."}, {"kind": "ol", "items": ["Instala Open Design y selecciona Codex como tu agente.", "Autentícate con tu clave de API de OpenAI (BYOK) o tu suscripción a ChatGPT — las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y una skill, y luego genera presentaciones, prototipos y landing pages con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente Codex, la misma clave — más un flujo de trabajo de diseño real, portátil y open-source a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Puede OpenAI Codex realmente hacer trabajo de diseño?", "text": "Sí — con una skill de frontend, un sistema de diseño e imágenes de referencia reales en contexto, Codex (especialmente con GPT-5.4) produce UI responsive de calidad de producción y puede verificarla en un navegador. Sin ese contexto tiende a recaer en un aspecto genérico, que es la brecha que Open Design cubre."}, {"name": "¿Es este el plugin de Product Design de OpenAI Codex?", "text": "No. Open Design es un proyecto open-source independiente que integra a Codex como agente. Complementa las propias herramientas de OpenAI con una biblioteca de skills y sistemas de diseño abierta y local-first."}, {"name": "¿Necesito una suscripción a ChatGPT para diseñar con Codex?", "text": "Puedes usar una clave de API de OpenAI (BYOK) o tu suscripción a ChatGPT. El inicio de sesión con ChatGPT suele dar límites más generosos; en cualquier caso, Open Design nunca actúa como proxy de tus credenciales."}, {"name": "¿Codex o Claude Code para diseño de frontend?", "text": "Ambos son fuertes. Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código; Codex tiene un fuerte pulido visual tras GPT-5.4 y destaca en compilaciones delegadas en sandbox. Muchos equipos usan ambos — Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto Codex con Figma?", "text": "Añade el servidor MCP oficial de Figma (codex mcp add figma --url https://mcp.figma.com/mcp). Después podrás implementar frames de Figma en código con get_design_context y enviar una UI en ejecución de vuelta a frames editables de Figma con generate_figma_design."}, {"name": "¿Cómo evito la estética genérica de “bazofia de IA”?", "text": "Instala una skill de frontend, aporta tokens de diseño reales y capturas de referencia, codifica las reglas de marca en AGENTS.md y habilita la verificación con Playwright. Open Design incluye todo esto como una biblioteca curada para que te saltes la configuración por proyecto."}, {"name": "¿Está Open Design afiliado a OpenAI?", "text": "No. Codex es un producto de OpenAI; Open Design es un proyecto open-source independiente que lo soporta como adaptador de primera parte. OpenAI y Codex son marcas comerciales de OpenAI."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí — Open Design es local-first. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de OpenAI las usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con Codex, a la manera abierta.", "ctaBody": "Usa tu propia clave de OpenAI, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente que ya usas.", "ctaActions": [{"label": "Usa Codex dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'cursor': {
        ...en['cursor']!,
        title: "Cursor para diseñadores — Open Design",
        description: "Cómo los diseñadores usan Cursor para diseño de UI y web — Design Mode, Figma a código, el MCP de Figma — y cómo Open Design convierte a Cursor en un agente de diseño open-source y local-first.",
        breadcrumb: "Cursor",
        label: "Agente · Cursor",
        heading: "Cursor para diseñadores.",
        lead: "Cursor es el editor de código con IA, ahora con un Design Mode visual. Los diseñadores lo usan para editar la UI señalando y dibujando, y para convertir Figma en código. Open Design conecta a Cursor Agent con un flujo de trabajo de diseño open-source que mantiene tus archivos en local.",
        rich: {"heroCtaLead": "Open Design convierte a Cursor en un agente de diseño open-source y local-first — tu cuenta de Cursor o tus claves de modelo, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa Cursor dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Cursor es el editor de código con IA primero que convirtió el “constrúyelo y míralo renderizar” en la forma por defecto de entregar UI. Con el modo Agent, ediciones en línea, una vista previa dentro del editor y Figma sobre MCP, se ha convertido en una verdadera herramienta de diseño — una vez que le das las referencias, reglas y un bucle de verificación adecuados. Esta es una guía práctica y de extremo a extremo para usar Cursor en trabajo de UI, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es realmente Cursor, por qué su ajustado bucle de iterar y observar es bueno para el diseño, cómo configurarlo desde cero, el bucle de captura y vista previa a UI, el round-trip con Figma sobre MCP, cómo se compara con Codex y Claude Code, los escollos que hacen que el resultado de la IA parezca genérico y cómo Open Design cierra esa brecha como una capa de diseño abierta y local-first."], "heroImage": {"src": "/agents/cursor-design/cursor-design-hero.webp", "alt": "Convergencia de diseño de Cursor: el editor a la izquierda, un hub curado de skills y sistema de diseño en el centro con la marca de Cursor al medio, y una UI renderizada a la derecha", "caption": "La idea central: Cursor edita y renderiza la UI en el editor, mientras un hub de diseño curado le aporta el sistema, las skills y las referencias que hacen que el resultado parezca intencional."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-cursor", "label": "Qué es realmente Cursor"}, {"id": "why-design", "label": "Por qué Cursor es bueno en diseño"}, {"id": "setup", "label": "Configura Cursor para diseño (desde cero)"}, {"id": "preview-workflow", "label": "El flujo de trabajo de vista previa a UI"}, {"id": "figma", "label": "Cursor + Figma sobre MCP"}, {"id": "vs", "label": "Cursor vs Codex vs Claude Code"}, {"id": "pitfalls", "label": "Escollos y el aspecto de “bazofia de IA”"}, {"id": "open-design", "label": "Diseñar con Cursor en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-cursor", "heading": "Qué es realmente Cursor", "blocks": [{"kind": "p", "text": "Cursor es un editor de código con IA primero construido por Anysphere. Es un fork de VS Code, por lo que conserva el editor, las extensiones y los atajos de teclado familiares, pero reconstruye el flujo de trabajo en torno a un agente de IA que puede leer todo tu proyecto, editar varios archivos, ejecutar comandos e iterar contigo en el bucle."}, {"kind": "p", "text": "Para el trabajo de diseño, las superficies importantes son el modo Agent (describes un resultado y Cursor planifica y edita a través de los archivos), las ediciones en línea y las completaciones con Tab para ajustes rápidos, una vista previa / navegador dentro del editor para que veas la UI en ejecución sin salir de la ventana, y el soporte de MCP que le permite incorporar contexto externo como un archivo de Figma en vivo."}, {"kind": "steps", "items": [{"label": "Reglas del proyecto", "body": "Cursor lee archivos de instrucciones del proyecto — reglas `.mdc` versionadas bajo `.cursor/rules`, y un `AGENTS.md` simple — para que puedas codificar tus convenciones de diseño donde el agente las lee en cada ejecución."}, {"label": "Modelos", "body": "Cursor es flexible en cuanto a modelos: viene con modelos de frontera a través de tu suscripción y también admite traer tus propias claves de modelo, así que eliges el motor detrás del mismo flujo de trabajo del editor."}, {"label": "MCP", "body": "Habla el Model Context Protocol, así que los servidores externos — el más relevante, el servidor MCP de Figma — se convierten en contexto de primera clase para el agente."}]}, {"kind": "ul", "items": ["Proveedor: Anysphere", "Credencial: cuenta / suscripción de Cursor (Hobby / Pro / Business) o tus propias claves de modelo (BYOK)", "Forma: editor de código con IA primero (fork de VS Code) con un agente y una vista previa dentro del editor"]}]}, {"id": "why-design", "heading": "Por qué Cursor es bueno en diseño", "blocks": [{"kind": "p", "text": "La ventaja de diseño de Cursor no es una sola característica — es lo ajustado del bucle de construir y ver. Tres cosas hacen que se sienta como una herramienta de diseño en lugar de un generador de código genérico."}, {"kind": "steps", "items": [{"label": "Un bucle ajustado de iterar y observar", "body": "Tú formulas el prompt, Cursor edita a través de los archivos, y la vista previa dentro del editor renderiza el resultado de inmediato — así ajustas espaciado, jerarquía y movimiento en segundos en lugar de ir y volver entre una terminal y un navegador separados."}, {"label": "Edición visual directa", "body": "Más allá del chat, Cursor te permite seleccionar elementos en la vista previa y retocar estilos, así que las pequeñas correcciones visuales se sienten como ediciones de diseño en lugar de arqueología de código."}, {"label": "Reglas del proyecto y contexto MCP", "body": "Con `.cursor/rules` (o `AGENTS.md`) y el servidor MCP de Figma, el agente trabaja contra tus tokens, componentes y especificaciones de diseño reales en lugar de adivinar."}]}, {"kind": "image", "src": "/agents/cursor-design/cursor-design-taste-triangle.webp", "alt": "Diagrama que muestra el sistema de diseño, la skill y la imagen de referencia convergiendo en un buen resultado de diseño", "caption": "El gusto proviene de tres insumos que tú aportas: un sistema de diseño, una skill e imágenes de referencia reales."}, {"kind": "p", "text": "La lección es la misma que enseña cada agente: Cursor no tiene gusto por defecto. Produce buen diseño cuando le das restricciones — un sistema de diseño, una skill estética y referencias concretas. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan (más abajo)."}]}, {"id": "setup", "heading": "Configura Cursor para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un Cursor capaz de construir, previsualizar y verificar UI contra tu sistema de diseño."}, {"kind": "ol", "items": ["Instala Cursor desde cursor.com e inicia sesión con tu cuenta de Cursor, o configura tus propias claves de modelo (BYOK) en Settings.", "Abre tu proyecto y elige un modelo en el panel de chat / Agent.", "Añade reglas del proyecto: crea `.cursor/rules/*.mdc` para convenciones estructuradas y delimitadas por globs, o un `AGENTS.md` simple para instrucciones sencillas y legibles.", "Conecta el servidor MCP de Figma (opcional) para que el agente pueda leer el contexto de diseño en vivo.", "Ejecuta tu servidor de desarrollo y usa la vista previa dentro del editor para ver y verificar la UI a medida que iteras."]}, {"kind": "image", "src": "/agents/cursor-design/cursor-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticar, configurar reglas, añadir skill, verificar", "caption": "La secuencia de configuración: instalar → autenticar → configurar las reglas del proyecto → añadir una skill → habilitar la verificación con vista previa."}, {"kind": "p", "text": "Un archivo mínimo de reglas del proyecto hace que el agente diseñe para una marca en lugar de recaer en un aspecto genérico. Ponlo donde Cursor lo lea en cada ejecución:"}, {"kind": "code", "lang": "markdown", "code": "# .cursor/rules/design.mdc\n---\ndescription: Project design conventions\nalwaysApply: true\n---\n\n- Reuse existing design-system tokens and components; never hardcode hex or spacing.\n- At most two typefaces and one accent color.\n- Brand-first hierarchy; restrained motion. No hero cards, no oversized rounded corners.\n- Build responsive by default; verify desktop and mobile in the preview before finishing."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Coloca tus tokens, primitivas y convenciones en `.cursor/rules` o `AGENTS.md` y dirige a Cursor hacia ellas, para que el resultado coincida con una marca en lugar de recaer en un aspecto genérico."}, {"label": "Mantén los prompts pequeños", "body": "El bucle ajustado de Cursor recompensa las peticiones enfocadas — itera un componente o estado a la vez y observa la vista previa entre pasadas."}]}]}, {"id": "preview-workflow", "heading": "El flujo de trabajo de vista previa a UI", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor apalancamiento con Cursor es convertir una referencia en una UI funcional y responsive e iterar en el editor hasta que coincida — observando la vista previa en vivo todo el tiempo en lugar de adivinar."}, {"kind": "ol", "items": ["Parte de las referencias visuales más claras que tengas — e incluye varios estados (escritorio y móvil, hover, vacío, cargando), no solo una única toma principal.", "Sé específico en el prompt; los prompts vagos producen UI genérica.", "Prepara un sistema de diseño e indícale a Cursor dónde viven los tokens y las primitivas canónicas.", "Mantén abierta la vista previa dentro del editor y tu servidor de desarrollo en marcha para que cada edición renderice de inmediato en los breakpoints que te importan.", "Itera comparando la UI renderizada con las referencias — y usa la selección directa de elementos en la vista previa para pequeñas correcciones visuales."]}, {"kind": "p", "text": "Alimenta las referencias adjuntando una imagen al chat, y luego formula el prompt con restricciones concretas:"}, {"kind": "code", "lang": "text", "code": "Implement this design in React + Vite + Tailwind + TypeScript.\nReuse my existing design-system components and tokens.\nMatch spacing, layout, and hierarchy; make it responsive.\nKeep the preview open — verify desktop and mobile match the\nreferences and iterate until they do."}, {"kind": "p", "text": "Confirma las buenas iteraciones y revierte las malas (diciéndole a Cursor cuándo reviertes) para que cada pasada parta de una base limpia — la misma disciplina que evita que cualquier bucle de agente derive."}]}, {"id": "figma", "heading": "Cursor + Figma: diseño ↔ código sobre MCP", "blocks": [{"kind": "p", "text": "Cursor se conecta a Figma a través del servidor MCP oficial de Figma, que da al agente acceso estructurado a un archivo de Figma en vivo en lugar de una captura plana. Eso elimina las conjeturas del handoff."}, {"kind": "steps", "items": [{"label": "Diseño → Código", "body": "Copia el enlace de un frame en Figma, pégalo en Cursor y pídele que implemente el diseño. El servidor MCP expone contexto de diseño real — componentes, variables, datos de layout, tokens — para que el código generado coincida con la fuente en lugar de aproximarla."}, {"label": "Mantente alineado", "body": "Con los tokens de diseño, estilos y componentes usados de forma consistente en Figma (y Code Connect donde esté disponible), el resultado de Cursor permanece mapeado a tu sistema de diseño real en lugar de reinventar primitivas."}]}, {"kind": "p", "text": "Configura una vez el servidor MCP remoto de Figma y estará disponible para Cursor como contexto de primera clase. Como MCP es un estándar abierto, el mismo servidor es reutilizable en Cursor, Claude Code, Codex y VS Code — exactamente el tipo de capacidad portátil y multiagente que Open Design está hecho para orquestar."}]}, {"id": "vs", "heading": "Cursor vs Codex vs Claude Code para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño — cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Mejor para"], "rows": [["Cursor", "Bucle visual de construir y ver con vista previa en vivo dentro del editor y edición directa de elementos", "Trabajo de UI ajustado de iterar y observar dentro de un IDE"], ["Codex", "Fuerte pulido visual con una skill de frontend; comprensión de imágenes y ejecuciones en sandbox", "Compilaciones asíncronas delegadas y reglas portátiles de AGENTS.md"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el gusto proviene de las personas: los tres recaen en una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver — y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Escollos y cómo evitar el aspecto de “bazofia de IA”", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por Cursor es que parece genérico — degradados suaves, paneles flotantes, esquinas redondeadas excesivas, sombras dramáticas, un aire de Inter-y-morado que “grita que esto lo hizo una IA”. Otros problemas reportados incluyen diseños que se rompen en móvil e instrucciones que se filtran en el texto de la UI."}, {"kind": "steps", "items": [{"label": "Añade una skill de diseño", "body": "Una skill estética curada obliga a Cursor a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Usa la vista previa para verificar", "body": "Renderiza y autoverifica en distintos breakpoints en la vista previa dentro del editor para que los diseños no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de referencia son la mayor palanca sobre la calidad del resultado."}, {"label": "Codifica reglas en `.cursor/rules`", "body": "Pon reglas de estilo como “sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca” donde el agente las lea en cada ejecución."}]}, {"kind": "p", "text": "Observa que cada mitigación consiste en dar al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es el trabajo pesado que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con Cursor dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño open-source que el flujo de trabajo anterior no deja de pedir. Trata a Cursor como un adaptador de primera parte y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de render estructurada y una UI de escritorio local — para que el contexto de diseño que hace bueno a Cursor esté ahí desde la primera ejecución, no se ensamble a mano cada vez."}, {"kind": "ol", "items": ["Instala Open Design y selecciona Cursor como tu agente.", "Autentícate con tu cuenta de Cursor o tus propias claves de modelo (BYOK) — las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y una skill, y luego genera presentaciones, prototipos y landing pages con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente Cursor, la misma clave — más un flujo de trabajo de diseño real, portátil y open-source a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Puede Cursor realmente hacer trabajo de diseño?", "text": "Sí — con una skill de diseño, un sistema de diseño e imágenes de referencia reales en contexto, Cursor produce UI responsive de calidad de producción, y su vista previa dentro del editor te permite verificarla y refinarla visualmente. Sin ese contexto tiende a recaer en un aspecto genérico, que es la brecha que Open Design cubre."}, {"name": "¿Es este un producto oficial de Cursor?", "text": "No. Open Design es un proyecto open-source independiente que integra a Cursor como agente. Complementa a Cursor con una biblioteca de skills y sistemas de diseño abierta y local-first."}, {"name": "¿Necesito una suscripción a Cursor para diseñar con Cursor?", "text": "Puedes usar una cuenta / suscripción de Cursor o traer tus propias claves de modelo (BYOK). Open Design nunca actúa como proxy de tus credenciales en ningún caso — las usa directamente tu agente."}, {"name": "¿Cursor o Claude Code para diseño de frontend?", "text": "Ambos son fuertes. Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código; la ventaja de Cursor es su ajustado bucle de construir y ver con una vista previa en vivo dentro del editor. Muchos equipos usan ambos — Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto Cursor con Figma?", "text": "Añade el servidor MCP oficial de Figma en Cursor, luego pega un enlace de un frame de Figma en el chat y pídele a Cursor que lo implemente. El servidor expone componentes, variables y datos de layout reales para que el código generado coincida con el diseño fuente."}, {"name": "¿Cómo evito la estética genérica de “bazofia de IA”?", "text": "Añade una skill de diseño, aporta tokens de diseño reales y capturas de referencia, codifica las reglas de marca en `.cursor/rules` o `AGENTS.md`, y verifica en distintos breakpoints en la vista previa. Open Design incluye todo esto como una biblioteca curada para que te saltes la configuración por proyecto."}, {"name": "¿Está Open Design afiliado a Cursor o Anysphere?", "text": "No. Cursor es un producto de Anysphere; Open Design es un proyecto open-source independiente que lo soporta como adaptador de primera parte. Cursor y Anysphere son marcas comerciales de Anysphere, Inc."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí — Open Design es local-first. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de Cursor o de modelo las usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con Cursor, a la manera abierta.", "ctaBody": "Usa tu propia cuenta de Cursor o claves de modelo, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente que ya usas.", "ctaActions": [{"label": "Usa Cursor dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'opencode': {
        ...en['opencode']!,
        title: "OpenCode para diseño — Open Design",
        description: "Cómo la gente usa OpenCode para diseño de UI y web — archivos design.md, skills de UI/UX, MCP de Figma — y cómo Open Design convierte a OpenCode en un agente de diseño open-source y local-first.",
        breadcrumb: "OpenCode",
        label: "Agente · OpenCode",
        heading: "OpenCode para diseño.",
        lead: "OpenCode es el agente de codificación con IA de terminal y open-source. Los diseñadores le acoplan skills de diseño y archivos DESIGN.md para generar UI real. Open Design lo convierte en un flujo de trabajo estructurado y open-source — usa tus claves de proveedor y mantén todo en local.",
        rich: {"heroCtaLead": "Open Design convierte a OpenCode en un agente de diseño open-source y local-first — cualquier modelo que elijas con tu propia clave de proveedor, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa OpenCode dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["OpenCode es un agente de codificación con IA, open-source y orientado a la terminal, que es deliberadamente agnóstico respecto al modelo: traes tu propia clave de proveedor y ejecutas el modelo que quieras detrás del mismo flujo de trabajo. Esa apertura lo convierte en una base natural para el trabajo de diseño — pero, como todo agente, solo produce buena UI cuando le das las referencias, skills y un bucle de verificación adecuados. Esta es una guía práctica y de extremo a extremo para usar OpenCode en trabajo de UI, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es realmente OpenCode, por qué un agente abierto y agnóstico respecto al modelo encaja bien con el diseño, cómo configurarlo desde cero, el bucle de captura a UI, cómo AGENTS.md y MCP lo extienden, cómo se compara con Codex, Claude Code y Cursor, los escollos que hacen que el resultado de la IA parezca genérico y cómo Open Design cierra esa brecha como una capa de diseño abierta y local-first — un emparejamiento natural, ya que ambos proyectos son open-source y se ejecutan en tu propia máquina."], "heroImage": {"src": "/agents/opencode-design/opencode-design-hero.webp", "alt": "Bucle de retroalimentación de diseño de OpenCode: un agente TUI de terminal, un navegador renderizando la UI y un espacio de trabajo, con una flecha de retroalimentación que regresa en bucle", "caption": "El bucle central: OpenCode construye la UI en la terminal, la renderiza y verifica en un navegador real, e itera contra tus referencias — con el modelo que elijas."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-opencode", "label": "Qué es realmente OpenCode"}, {"id": "why-design", "label": "Por qué un agente abierto y de cualquier modelo encaja con el diseño"}, {"id": "setup", "label": "Configura OpenCode para diseño (desde cero)"}, {"id": "screenshot-workflow", "label": "El flujo de trabajo de captura a UI"}, {"id": "extend", "label": "AGENTS.md, MCP y sesiones compartibles"}, {"id": "vs", "label": "OpenCode vs Codex vs Claude Code vs Cursor"}, {"id": "pitfalls", "label": "Escollos y el aspecto de “bazofia de IA”"}, {"id": "open-design", "label": "Diseñar con OpenCode en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-opencode", "heading": "Qué es realmente OpenCode", "blocks": [{"kind": "p", "text": "OpenCode es un agente de codificación con IA open-source construido para la terminal, mantenido por el equipo detrás de SST (Anomaly Innovations). Lee tu repositorio, ejecuta comandos, edita archivos y se comunica con un modelo de lenguaje grande — pero, a diferencia de los agentes atados a un proveedor, no incluye su propio modelo. Lo apuntas a cualquier proveedor y modelo que quieras y traes tu propia clave."}, {"kind": "p", "text": "Se ejecuta como una UI de terminal (TUI), con una aplicación de escritorio y extensiones de IDE sobre el mismo motor. Por debajo usa una arquitectura cliente/servidor, así que el agente que hace el trabajo está desacoplado de la superficie desde la que lo controlas. Dos agentes integrados — build y plan — se alternan con la tecla Tab."}, {"kind": "steps", "items": [{"label": "Agnóstico respecto al modelo", "body": "Los modelos y proveedores provienen de models.dev, un catálogo abierto. Los configuras en opencode.json con una cadena provider/model-id y puedes deshabilitar los proveedores que no quieras cargar — así el mismo flujo de trabajo de diseño se ejecuta sobre Anthropic, OpenAI, Google, OpenRouter, modelos locales y más."}, {"label": "Archivo de instrucciones", "body": "OpenCode lee un archivo AGENTS.md en tu proyecto (el estándar entre herramientas, también compatible con CLAUDE.md) para las reglas del proyecto — el lugar natural para codificar tus convenciones de diseño. Ejecuta /init para generar uno."}, {"label": "Extensible", "body": "Admite integración con LSP, servidores MCP, temas, atajos de teclado y comandos personalizados, además de enlaces de sesión compartibles para la colaboración."}]}, {"kind": "ul", "items": ["Mantenedor: SST / Anomaly Innovations (proyecto open-source)", "Credencial: tu(s) propia(s) clave(s) de API de proveedor de modelos — BYOK, sin atadura a un proveedor", "Licencia: MIT, open source"]}]}, {"id": "why-design", "heading": "Por qué un agente abierto y de cualquier modelo encaja con el trabajo de diseño", "blocks": [{"kind": "p", "text": "OpenCode no tiene un único “modelo de diseño” como sí lo tiene un agente de proveedor — y ese es el punto. Como es agnóstico respecto al modelo y abierto, puedes ejecutar el mismo flujo de trabajo de diseño sobre el modelo que actualmente sea mejor en frontend, cambiarlo después o recurrir a un modelo local, todo sin cambiar tu configuración."}, {"kind": "p", "text": "Pero la elección del modelo por sí sola no compra gusto. Como todo agente de codificación, OpenCode produce UI genérica a menos que le des restricciones. El buen resultado de diseño proviene de tres insumos que tú aportas."}, {"kind": "steps", "items": [{"label": "Un sistema de diseño", "body": "Tokens, primitivas y convenciones reales que el agente reutiliza, para que el resultado coincida con una marca en lugar de recaer en un aspecto genérico."}, {"label": "Una skill estética", "body": "Una skill curada que impone gusto real — movimiento contenido, jerarquía centrada en la marca, como máximo dos tipografías y un color de acento — y hace que el agente se comprometa con una dirección antes de construir."}, {"label": "Referencias concretas", "body": "Imágenes de referencia reales y varios estados (escritorio y móvil, hover, vacío, cargando), no una única toma principal."}]}, {"kind": "image", "src": "/agents/opencode-design/opencode-design-taste-triangle.webp", "alt": "Diagrama que muestra el sistema de diseño, la skill y la imagen de referencia convergiendo en un buen resultado de diseño", "caption": "El gusto proviene de tres insumos que tú aportas: un sistema de diseño, una skill e imágenes de referencia reales — con independencia del modelo que ejecutes."}, {"kind": "p", "text": "La lección: OpenCode te da libertad de modelo, pero el gusto sigue proviniendo de un contexto de diseño curado. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan — los dos son open-source y local-first (más abajo)."}]}, {"id": "setup", "heading": "Configura OpenCode para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un OpenCode capaz de construir y verificar UI."}, {"kind": "code", "lang": "bash", "code": "# 1. Install OpenCode\ncurl -fsSL https://opencode.ai/install | bash\n# or: npm i -g opencode-ai@latest\n# or: brew install sst/tap/opencode\n\n# 2. Start the TUI in your project, then authenticate your provider\nopencode          # then run /login and pick your provider + paste your key\n\n# 3. Generate project context\nopencode          # inside your project, run /init to create AGENTS.md\n\n# 4. Pick your model (any provider, via models.dev)\n#    set \"provider/model-id\" in opencode.json or switch in the TUI\n\n# 5. Add an MCP server (optional, e.g. for design handoff)\n#    configure it under the \"mcp\" key in opencode.json"}, {"kind": "image", "src": "/agents/opencode-design/opencode-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticar con tu clave de proveedor, configurar AGENTS.md, añadir una skill, verificar", "caption": "La secuencia de configuración: instalar → autenticar (tu clave de proveedor) → configurar AGENTS.md → añadir una skill → verificar en un navegador real."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Coloca tus tokens, primitivas y convenciones en AGENTS.md (o en un DESIGN.md referenciado desde él) para que el resultado coincida con una marca en lugar de recaer en un aspecto genérico. La opción instructions de opencode.json puede apuntar a archivos de reglas adicionales mediante globs."}, {"label": "Elige un modelo capaz", "body": "Como OpenCode es agnóstico respecto al modelo, elige el proveedor/modelo que actualmente sea más fuerte en frontend para la pasada de diseño — y mantén el resto de tu flujo de trabajo sin cambios."}]}]}, {"id": "screenshot-workflow", "heading": "El flujo de trabajo de captura a UI", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor apalancamiento con cualquier agente es convertir una imagen de referencia en una UI funcional y responsive e iterar hasta que coincida. La misma forma de cinco pasos aplica en OpenCode."}, {"kind": "ol", "items": ["Parte de las referencias visuales más claras que tengas — e incluye varios estados (escritorio y móvil, hover, vacío, cargando), no solo una única toma principal.", "Sé específico en el prompt; los prompts vagos producen UI genérica.", "Prepara un sistema de diseño e indícale a OpenCode dónde viven los tokens y las primitivas canónicas (en AGENTS.md).", "Ejecuta un servidor de desarrollo y haz que el agente renderice en un navegador real, redimensionando a los breakpoints para comprobar el resultado.", "Itera haciendo que OpenCode compare su implementación con las capturas — no solo que confirme que compila."]}, {"kind": "p", "text": "Referencia archivos con @ en la TUI para una búsqueda difusa de tu directorio de trabajo, ejecuta comandos de shell en línea con un ! inicial, y dirige las acciones con comandos /. Luego formula el prompt con restricciones concretas:"}, {"kind": "code", "lang": "bash", "code": "opencode\n# in the TUI:\n> @reference-desktop.png @reference-mobile.png\n  Implement this design in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from AGENTS.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Run the dev server, open it in a browser, and iterate until the\n  UI matches the references across breakpoints."}, {"kind": "p", "text": "Mantén los prompts pequeños y enfocados, confirma las buenas iteraciones y revierte las malas (diciéndole a OpenCode cuándo reviertes), para que cada pasada parta de una base limpia."}]}, {"id": "extend", "heading": "AGENTS.md, MCP y sesiones compartibles", "blocks": [{"kind": "p", "text": "Tres puntos de extensión hacen a OpenCode práctico para el trabajo de diseño sostenido, y los tres se mapean limpiamente sobre un flujo de trabajo de diseño abierto."}, {"kind": "steps", "items": [{"label": "Reglas de AGENTS.md", "body": "Las reglas del proyecto viven en un AGENTS.md en la raíz del repositorio (o reglas globales en ~/.config/opencode/AGENTS.md). Es el hogar duradero de tus convenciones de diseño, leído en cada ejecución, y es compatible con los archivos CLAUDE.md que usan otros agentes."}, {"label": "Servidores MCP", "body": "OpenCode admite servidores MCP tanto locales (command) como remotos (URL), configurados bajo la clave mcp — la forma portátil de incorporar contexto de diseño y herramientas externas que funcionan en todos los agentes, no solo en OpenCode."}, {"label": "Sesiones compartibles", "body": "El comando /share crea un enlace público a una conversación para colaboración o revisión, y /unshare lo revoca — útil para obtener feedback sobre una pasada de diseño."}]}, {"kind": "p", "text": "Estas son capacidades portátiles y multiagente — exactamente el tipo de cosa que Open Design está hecho para orquestar, en lugar de recrear en cada proyecto."}]}, {"id": "vs", "heading": "OpenCode vs Codex vs Claude Code vs Cursor para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño — cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Mejor para"], "rows": [["OpenCode", "Open-source y agnóstico respecto al modelo; ejecuta cualquier proveedor detrás de un único flujo de trabajo de terminal", "Libertad BYOK, cambio de modelo, configuraciones totalmente abiertas y local-first"], ["Codex", "Fuerte pulido visual con una skill de frontend; comprensión de imágenes", "Async delegado, compilaciones en sandbox, reglas portátiles de AGENTS.md"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de UI ajustado de iterar y observar dentro de un IDE"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el gusto proviene de las personas: todos recaen en una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver — y tiene forma de herramienta de diseño, no de modelo, que es precisamente por lo que un agente abierto como OpenCode encaja tan bien con una capa de diseño abierta."}]}, {"id": "pitfalls", "heading": "Escollos y cómo evitar el aspecto de “bazofia de IA”", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por IA es que parece genérico — degradados suaves, paneles flotantes, esquinas redondeadas excesivas, sombras dramáticas, un aire de Inter-y-morado que “grita que esto lo hizo una IA”. Otros problemas reportados incluyen diseños móviles rotos e instrucciones que se filtran en el texto de la UI. Ninguno de estos es exclusivo de OpenCode; son lo que ocurre cuando cualquier agente se ejecuta sin un contexto de diseño curado."}, {"kind": "steps", "items": [{"label": "Añade una skill estética", "body": "Una skill de diseño curada obliga al agente a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Verifica en un navegador real", "body": "Renderiza y autoverifica en distintos breakpoints para que los diseños no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de referencia son la mayor palanca sobre la calidad del resultado."}, {"label": "Codifica reglas en AGENTS.md", "body": "Pon reglas de estilo como “sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca” donde el agente las lea en cada ejecución."}]}, {"kind": "p", "text": "Observa que cada mitigación consiste en dar al agente un contexto de diseño curado — sin importar qué modelo ejecutes. Mantener ese contexto a mano, proyecto a proyecto, es el trabajo pesado que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con OpenCode dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño open-source que el flujo de trabajo anterior no deja de pedir. Trata a OpenCode como un adaptador de primera parte y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de render estructurada y una UI de escritorio local — para que el contexto de diseño que hace bueno a cualquier agente esté ahí desde la primera ejecución, no se ensamble a mano cada vez. Ambos proyectos son open-source y local-first, lo que hace que el emparejamiento sea un encaje natural."}, {"kind": "ol", "items": ["Instala Open Design y selecciona OpenCode como tu agente.", "Autentícate con tu propia clave de API de proveedor de modelos (BYOK) — las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige cualquier proveedor y modelo, además de un sistema de diseño y una skill, y luego genera presentaciones, prototipos y landing pages con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente OpenCode, la misma libertad de modelo — más un flujo de trabajo de diseño real, portátil y open-source a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Puede OpenCode realmente hacer trabajo de diseño?", "text": "Sí — con una skill estética, un sistema de diseño e imágenes de referencia reales en contexto, OpenCode produce UI responsive de calidad de producción y puede verificarla en un navegador. Como es agnóstico respecto al modelo, ejecutas el modelo que actualmente sea mejor en frontend. Sin ese contexto curado tiende a recaer en un aspecto genérico, que es la brecha que Open Design cubre."}, {"name": "¿Qué modelo debería usar con OpenCode para diseño?", "text": "El que prefieras — OpenCode es agnóstico respecto al proveedor a través de models.dev, así que puedes ejecutar Anthropic, OpenAI, Google, OpenRouter o modelos locales detrás del mismo flujo de trabajo y cambiar en cualquier momento. La calidad del resultado de diseño depende mucho más de tu skill, tu sistema de diseño y tus referencias que del modelo por sí solo."}, {"name": "¿Open Design está hecho por el equipo de OpenCode (SST)?", "text": "No. Open Design es un proyecto open-source independiente que integra a OpenCode como agente. Complementa a OpenCode con una biblioteca de skills y sistemas de diseño abierta y local-first."}, {"name": "¿Necesito una suscripción especial para diseñar con OpenCode?", "text": "No — OpenCode es BYOK. Traes tu propia clave de API de proveedor de modelos, y Open Design nunca actúa como proxy de tus credenciales. No hay atadura a un proveedor."}, {"name": "¿OpenCode, Codex o Claude Code para diseño de frontend?", "text": "Todos son fuertes, y muchos equipos los combinan. La ventaja de OpenCode es ser totalmente open-source y agnóstico respecto al modelo; Codex destaca en compilaciones delegadas en sandbox; Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código. Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo extiendo OpenCode para el contexto de diseño?", "text": "Codifica reglas en AGENTS.md, añade servidores MCP bajo la clave mcp para herramientas portátiles y contexto de diseño, y usa sesiones compartibles para la revisión. Open Design incluye una biblioteca curada de skills y sistemas de diseño para que te saltes la configuración por proyecto."}, {"name": "¿Está Open Design afiliado a OpenCode o SST?", "text": "No. OpenCode es un proyecto open-source mantenido por SST (Anomaly Innovations); Open Design es un proyecto open-source independiente que lo soporta como adaptador de primera parte."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí — Open Design es local-first. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de proveedor de modelos las usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con OpenCode, a la manera abierta.", "ctaBody": "Usa tu propia clave de proveedor de modelos, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente abierto que ya usas.", "ctaActions": [{"label": "Usa OpenCode dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'gemini': {
        ...en['gemini']!,
        title: "Gemini CLI para diseño — Open Design",
        description: "Cómo la gente usa el Gemini CLI de Google para diseño de interfaces y web: su comprensión multimodal de imágenes, el contexto de 1M de tokens, GEMINI.md y MCP, y cómo Open Design convierte Gemini CLI en un agente de diseño local-first y de código abierto.",
        breadcrumb: "Gemini CLI",
        label: "Agente · Gemini CLI",
        heading: "Gemini CLI para diseño.",
        lead: "Gemini CLI es el agente de terminal de código abierto de Google. Sus modelos multimodales leen capturas de pantalla y su contexto de 1M de tokens abarca todo un sistema de diseño, lo que lo convierte en una herramienta de diseño real, una vez que le proporcionas referencias, convenciones y un bucle de verificación. Open Design lo integra en un flujo de trabajo de diseño de código abierto: tu cuenta de Google o tu clave de API, tus archivos, local-first.",
        rich: {"heroCtaLead": "Open Design convierte Gemini CLI en un agente de diseño local-first y de código abierto: tu cuenta de Google o tu clave de API de Gemini, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa Gemini CLI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Danos una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Gemini CLI es el agente de IA de código abierto de Google para la terminal. Dos cosas lo hacen interesante específicamente para el diseño: sus modelos son fuertemente multimodales, así que lee una captura de pantalla y razona sobre la disposición, el espaciado y la jerarquía; y su ventana de contexto de 1M de tokens puede abarcar a la vez todo un sistema de diseño y una base de código. Combinado con las referencias y convenciones adecuadas y un bucle de verificación, construye interfaces reales y responsivas, y se puede empezar gratis con una cuenta de Google. Esta es una guía práctica y de principio a fin para usar Gemini CLI en trabajos de interfaz, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es realmente Gemini CLI, por qué sus modelos multimodales y su enorme contexto encajan con el diseño, cómo configurarlo desde cero, el bucle de captura de pantalla a interfaz, cómo lo extienden GEMINI.md y MCP, cómo se compara con Codex, Claude Code y Cursor, los errores que hacen que el resultado de la IA parezca genérico, y cómo Open Design cierra la brecha como una capa de diseño abierta y local-first, un emparejamiento natural, ya que ambos son de código abierto y se ejecutan en tu propia máquina."], "heroImage": {"src": "/agents/gemini-design/gemini-design-hero.webp", "alt": "Bucle de retroalimentación de diseño de Gemini CLI: un agente de terminal leyendo una imagen de referencia, un navegador renderizando la interfaz y un espacio de trabajo, con una flecha de retroalimentación que vuelve atrás", "caption": "El bucle central: Gemini CLI lee tus referencias en la terminal, construye y verifica la interfaz en un navegador real, e itera frente a ellas, con todo un sistema de diseño en contexto."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-gemini-cli", "label": "Qué es realmente Gemini CLI"}, {"id": "why-design", "label": "Por qué lo multimodal + el enorme contexto encajan con el diseño"}, {"id": "setup", "label": "Configura Gemini CLI para diseño (desde cero)"}, {"id": "screenshot-workflow", "label": "El flujo de captura de pantalla a interfaz"}, {"id": "extend", "label": "GEMINI.md, MCP y extensiones"}, {"id": "vs", "label": "Gemini CLI vs Codex vs Claude Code vs Cursor"}, {"id": "pitfalls", "label": "Errores y el aspecto de «basura de IA»"}, {"id": "open-design", "label": "Diseñar con Gemini CLI en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-gemini-cli", "heading": "Qué es realmente Gemini CLI", "blocks": [{"kind": "p", "text": "Gemini CLI es un agente de IA de código abierto (Apache-2.0) que Google ofrece para la terminal. Lee tu repositorio, edita archivos, ejecuta comandos de shell, consulta la web y puede fundamentar las respuestas con Google Search, planificando y verificando el trabajo a partir de tareas en lenguaje natural en lugar de simplemente completar líneas. El mismo motor también impulsa el agente de Gemini Code Assist dentro de VS Code."}, {"kind": "p", "text": "Para el trabajo de diseño destacan dos propiedades. Sus modelos son nativamente multimodales, así que puedes entregarle una captura de pantalla y razona sobre la disposición real. Y su ventana de contexto alcanza hasta 1M de tokens, lo bastante grande para abarcar a la vez todo tu sistema de diseño, tu biblioteca de componentes y tu conjunto de referencias en lugar de resumirlos."}, {"kind": "steps", "items": [{"label": "Archivos de contexto", "body": "Gemini CLI lee un archivo GEMINI.md para obtener contexto persistente del proyecto, el lugar natural para codificar tus convenciones de diseño, tokens y listas de revisión. Las configuraciones personales y de equipo se superponen encima."}, {"label": "Herramientas integradas + MCP", "body": "Incluye de fábrica herramientas de archivos, shell, web-fetch y Google Search, y admite servidores MCP (configurados en ~/.gemini/settings.json) para añadir contexto externo, como un archivo de Figma en vivo."}, {"label": "Gratis para empezar", "body": "Iniciar sesión con una cuenta personal de Google ofrece un generoso nivel gratuito de solicitudes a Gemini; también puedes aportar una clave de API de Gemini o usar Vertex AI."}]}, {"kind": "ul", "items": ["Proveedor: Google", "Credencial: cuenta de Google (nivel gratuito) o clave de API de Gemini desde AI Studio (BYOK) o Vertex AI", "Licencia: Apache-2.0, código abierto"]}]}, {"id": "why-design", "heading": "Por qué los modelos multimodales y un enorme contexto encajan con el diseño", "blocks": [{"kind": "p", "text": "La ventaja de Gemini CLI en diseño proviene de dos propiedades del modelo, pero, como con todo agente, el buen gusto aún hay que aportarlo."}, {"kind": "steps", "items": [{"label": "Sólida comprensión multimodal", "body": "Como los modelos de Gemini son nativamente multimodales, el agente lee bien las capturas de pantalla de referencia, comparando su resultado renderizado con una imagen en lugar de adivinar a partir de una descripción en prosa."}, {"label": "Una ventana de contexto de 1M de tokens", "body": "Un contexto amplio significa que todo el sistema de diseño, los tokens y muchos estados de referencia caben a la vez, así que el agente reutiliza tus primitivas reales en lugar de inventar estilos puntuales."}, {"label": "Convenciones en GEMINI.md", "body": "Un GEMINI.md (más el servidor MCP de Figma) dirige al agente hacia tus tokens, componentes y especificaciones reales, así que trabaja sobre una marca en lugar de un aspecto por defecto."}]}, {"kind": "image", "src": "/agents/gemini-design/gemini-design-taste-triangle.webp", "alt": "Diagrama que muestra un sistema de diseño, un skill y una imagen de referencia convergiendo en un buen resultado de diseño", "caption": "El buen gusto proviene de tres entradas que tú aportas: un sistema de diseño, un skill e imágenes de referencia reales."}, {"kind": "p", "text": "La lección es la misma que enseña todo agente: Gemini CLI no tiene buen gusto por defecto. Produce buen diseño cuando le das restricciones: un sistema de diseño, un skill estético y referencias concretas. Open Design empaqueta exactamente esas entradas, y por eso ambos encajan (más abajo)."}]}, {"id": "setup", "heading": "Configura Gemini CLI para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un Gemini CLI capaz de construir y verificar interfaces."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Gemini CLI (Node 20+)\nnpm install -g @google/gemini-cli\n# or run without installing: npx https://github.com/google-gemini/gemini-cli\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\ngemini            # sign in with your Google account, or set GEMINI_API_KEY\n\n# 3. Generate project context\n/init             # scaffolds a GEMINI.md for this project\n\n# 4. Wire the Figma MCP server (optional, for design handoff)\n#    add it under \"mcpServers\" in ~/.gemini/settings.json"}, {"kind": "image", "src": "/agents/gemini-design/gemini-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticar, configurar GEMINI.md, añadir un skill, verificar", "caption": "La secuencia de configuración: instalar → autenticar → configurar GEMINI.md → añadir un skill → habilitar la verificación en el navegador."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Pon tus tokens, primitivas y convenciones en GEMINI.md y apunta a Gemini hacia ellos, para que el resultado coincida con una marca en lugar de recurrir a un aspecto genérico."}, {"label": "Añade verificación en el navegador", "body": "Integra Playwright o un MCP de navegador para que Gemini renderice en un navegador real y compruebe su resultado en distintos breakpoints, en lugar de solo confirmar que la compilación pasa."}]}]}, {"id": "screenshot-workflow", "heading": "El flujo de captura de pantalla a interfaz", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor apalancamiento con Gemini CLI es convertir una imagen de referencia en una interfaz funcional y responsiva e iterar hasta que coincida, apoyándose en el modelo multimodal para comparar el resultado con la referencia."}, {"kind": "ol", "items": ["Parte de las referencias visuales más claras que tengas, e incluye múltiples estados (escritorio y móvil, hover, vacío, cargando), no solo una sola toma principal.", "Sé específico en el prompt; los prompts vagos producen interfaces genéricas incluso con un modelo potente.", "Mantén tu sistema de diseño y tus convenciones en GEMINI.md, e indícale a Gemini dónde viven los tokens y las primitivas canónicas.", "Ejecuta un servidor de desarrollo y haz que Gemini renderice en un navegador real, redimensionando a los breakpoints para comprobar el resultado.", "Itera haciendo que Gemini compare su implementación con las capturas de pantalla, no que solo confirme que compila."]}, {"kind": "p", "text": "Referencia una imagen con @ para adjuntarla al prompt, y luego da restricciones concretas:"}, {"kind": "code", "lang": "bash", "code": "gemini\n# in the prompt:\n> @reference-desktop.png @reference-mobile.png\n  Implement this design in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from GEMINI.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Render it in the browser and iterate until it matches the references\n  across breakpoints."}, {"kind": "p", "text": "Mantén los prompts pequeños y enfocados, confirma (commit) las buenas iteraciones y revierte las malas (indicándole a Gemini cuándo reviertes), para que cada pasada se construya sobre una base limpia."}]}, {"id": "extend", "heading": "GEMINI.md, MCP y extensiones", "blocks": [{"kind": "p", "text": "Tres puntos de extensión hacen que Gemini CLI sea práctico para un trabajo de diseño sostenido, y los tres se asignan limpiamente a un flujo de trabajo de diseño abierto."}, {"kind": "steps", "items": [{"label": "Contexto en GEMINI.md", "body": "Las reglas del proyecto viven en un GEMINI.md en la raíz del repositorio (con capas global y de equipo). Es el hogar duradero de tus convenciones de diseño, leído en cada ejecución."}, {"label": "Servidores MCP", "body": "Configura servidores MCP en ~/.gemini/settings.json, la forma portátil de incorporar contexto de diseño y herramientas externas, sobre todo el servidor MCP de Figma, que funcionan en distintos agentes, no solo en Gemini."}, {"label": "Extensiones y herramientas integradas", "body": "Las extensiones de Gemini CLI y sus herramientas integradas de Google Search, archivos, shell y web-fetch le permiten reunir referencias y ejecutar el bucle de verificación sin salir de la terminal."}]}, {"kind": "p", "text": "Estas son capacidades portátiles y multiagente, exactamente el tipo de cosas que Open Design está diseñado para orquestar, en lugar de recrearlas en cada proyecto."}]}, {"id": "vs", "heading": "Gemini CLI vs Codex vs Claude Code vs Cursor para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño: cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza en diseño", "Ideal para"], "rows": [["Gemini CLI", "Sólida comprensión multimodal de imágenes y un contexto de 1M de tokens; código abierto con un nivel gratuito", "Trabajo intensivo en capturas de pantalla y mantener todo un sistema de diseño en contexto"], ["Codex", "Buen acabado visual con un skill de frontend; compilaciones asíncronas en entorno aislado", "Compilaciones asíncronas delegadas y reglas portátiles en AGENTS.md"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones con gran contexto"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de interfaz ágil de iterar y observar dentro de un IDE"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el buen gusto proviene de las personas: todos recurren a una estética genérica sin skills, referencias ni restricciones. Ese es el verdadero problema a resolver, y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Errores, y cómo evitar el aspecto de «basura de IA»", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por IA es que parece genérico: degradados suaves, paneles flotantes, esquinas redondeadas excesivas, sombras dramáticas, un rollo de Inter y morado que «grita que esto lo hizo una IA». Otros problemas reportados incluyen diseños móviles rotos e instrucciones que se filtran en los textos de la interfaz. Ninguno de estos es exclusivo de Gemini CLI; es lo que ocurre cuando cualquier agente se ejecuta sin un contexto de diseño curado."}, {"kind": "steps", "items": [{"label": "Añade un skill estético", "body": "Un skill de diseño curado obliga al agente a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Verifica en un navegador real", "body": "Usa el modelo multimodal para renderizar y autocomprobarse en distintos breakpoints, de modo que los diseños no se rompan silenciosamente en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de pantalla de referencia son la mayor palanca individual sobre la calidad del resultado."}, {"label": "Codifica reglas en GEMINI.md", "body": "Pon reglas del estilo «nada de tarjetas hero, máximo dos tipografías, jerarquía con la marca primero» donde el agente las lea en cada ejecución."}]}, {"kind": "p", "text": "Fíjate en que toda mitigación consiste en darle al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es el trabajo tedioso que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con Gemini CLI dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño de código abierto que el flujo de trabajo anterior no deja de pedir. Trata a Gemini CLI como un adaptador de primera categoría y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de renderizado estructurada y una interfaz de escritorio local, para que el contexto de diseño que hace bueno a Gemini esté ahí desde la primera ejecución, no se arme a mano cada vez. Ambos son de código abierto y local-first, lo que hace que el emparejamiento sea natural."}, {"kind": "ol", "items": ["Instala Open Design y selecciona Gemini CLI como tu agente.", "Autentícate con tu cuenta de Google o tu clave de API de Gemini (BYOK): las credenciales se quedan en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y un skill, y luego genera presentaciones, prototipos y páginas de aterrizaje con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente Gemini CLI, la misma clave, más un flujo de trabajo de diseño real, portátil y de código abierto a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Gemini CLI puede realmente hacer trabajo de diseño?", "text": "Sí; con un skill estético, un sistema de diseño e imágenes de referencia reales en contexto, Gemini CLI produce interfaces responsivas de calidad de producción, y sus sólidos modelos multimodales verifican el resultado frente a las referencias. Sin ese contexto tiende a recurrir a un aspecto genérico, que es la brecha que Open Design rellena."}, {"name": "¿Necesito pagar para diseñar con Gemini CLI?", "text": "No; iniciar sesión con una cuenta de Google ofrece un generoso nivel gratuito, y también puedes aportar una clave de API de Gemini (BYOK) o usar Vertex AI. Open Design nunca enruta tus credenciales en ningún caso."}, {"name": "¿Qué hace que Gemini CLI sea bueno para el diseño en particular?", "text": "Dos cosas: sus modelos son fuertemente multimodales, así que lee bien las capturas de pantalla de referencia, y su contexto de 1M de tokens puede abarcar a la vez todo un sistema de diseño y un conjunto de referencias. Ambas ayudan, pero el buen gusto aún proviene del sistema de diseño, el skill y las referencias que tú aportas."}, {"name": "¿Gemini CLI o Claude Code para diseño de frontend?", "text": "Ambos son potentes. Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código; la ventaja de Gemini CLI es la comprensión multimodal más un enorme contexto y un nivel gratuito. Muchos equipos usan ambos: Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto Gemini CLI con Figma?", "text": "Añade el servidor MCP de Figma en mcpServers, dentro de ~/.gemini/settings.json. Gemini puede entonces extraer contexto de diseño real (componentes, variables, datos de disposición) para que el código generado coincida con la fuente en lugar de aproximarla."}, {"name": "¿Open Design está afiliado a Google?", "text": "No. Gemini CLI es un producto de Google; Open Design es un proyecto independiente de código abierto que lo admite como adaptador de primera categoría. Gemini es una marca registrada de Google."}, {"name": "¿Están seguros mis archivos y mis credenciales?", "text": "Sí; Open Design es local-first y Apache-2.0. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de Google las usa directamente tu agente, nunca se enrutan a través de los servidores de Open Design."}], "ctaTitle": "Diseña con Gemini CLI, a la manera abierta.", "ctaBody": "Aporta tu propia cuenta de Google o clave de API de Gemini, mantén cada archivo en local y obtén una biblioteca de diseño curada en torno al agente que ya usas.", "ctaActions": [{"label": "Usa Gemini CLI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Danos una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'copilot': {
        ...en['copilot']!,
        title: "GitHub Copilot CLI para diseño — Open Design",
        description: "Cómo se usa GitHub Copilot CLI para diseño de interfaces y web — su agente de programación nativo de terminal, sus archivos de instrucciones personalizadas, su compatibilidad con MCP y su elección de varios modelos — y cómo Open Design convierte Copilot CLI en un agente de diseño local-first y de código abierto.",
        breadcrumb: "GitHub Copilot CLI",
        label: "Agente · GitHub Copilot CLI",
        heading: "GitHub Copilot CLI para diseño.",
        lead: "GitHub Copilot CLI es el agente de programación nativo de terminal de GitHub. Planifica y edita en todo tu repositorio, elige entre modelos de frontera como Claude y GPT, y lee las instrucciones de tu repositorio, lo que lo convierte en una verdadera herramienta de diseño una vez que le das referencias, convenciones y un bucle de verificación. Open Design lo integra en un flujo de trabajo de diseño de código abierto: tu suscripción a GitHub Copilot, tus archivos, local-first.",
        rich: {"heroCtaLead": "Open Design convierte GitHub Copilot CLI en un agente de diseño local-first y de código abierto: tu suscripción a GitHub Copilot, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa Copilot CLI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["GitHub Copilot CLI es el agente de programación nativo de terminal de GitHub: el mismo entorno agéntico que impulsa el agente de programación de Copilot, llevado a tu línea de comandos. Dos cosas lo hacen interesante específicamente para diseño: lee las instrucciones de tu repositorio y AGENTS.md, de modo que tus convenciones de diseño viajan con el agente en cada ejecución; y te permite elegir entre modelos de frontera de Anthropic, OpenAI y Google según la tarea, así que puedes optar por el que razona mejor sobre una interfaz dada. Combinado con las referencias, convenciones y un bucle de verificación adecuados, construye interfaces reales y adaptables, y funciona con la suscripción de Copilot que quizá ya tengas. Esta es una guía práctica y de extremo a extremo para usar Copilot CLI en trabajo de interfaces, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es realmente Copilot CLI, por qué las instrucciones de repositorio y la elección de modelo encajan con el diseño, cómo configurarlo desde cero, el bucle de captura de pantalla a interfaz, cómo lo amplían las instrucciones personalizadas y MCP, cómo se compara con Codex, Claude Code, Cursor y Gemini CLI, los obstáculos que hacen que la salida de la IA parezca genérica, y cómo Open Design cierra la brecha como una capa de diseño abierta y local-first: tu suscripción y tus credenciales permanecen en tu máquina, y tus artefactos permanecen en tu propio repositorio."], "heroImage": {"src": "/agents/copilot-design/copilot-design-hero.webp", "alt": "Bucle de retroalimentación de diseño de GitHub Copilot CLI: un agente de terminal leyendo una imagen de referencia, un navegador renderizando la interfaz y un espacio de trabajo, con una flecha de retroalimentación que vuelve al inicio", "caption": "El bucle central: Copilot CLI lee tus referencias en la terminal, construye y verifica la interfaz en un navegador real e itera frente a ellas, con tus convenciones de diseño en las instrucciones del repositorio."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-copilot", "label": "Qué es realmente GitHub Copilot CLI"}, {"id": "why-design", "label": "Por qué las instrucciones + la elección de modelo encajan con el diseño"}, {"id": "setup", "label": "Configura Copilot CLI para diseño (desde cero)"}, {"id": "screenshot-workflow", "label": "El flujo de trabajo de captura de pantalla a interfaz"}, {"id": "extend", "label": "Instrucciones personalizadas, MCP y extensiones"}, {"id": "vs", "label": "Copilot CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Obstáculos y el aspecto de «IA descuidada»"}, {"id": "open-design", "label": "Diseñar con Copilot CLI en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-copilot", "heading": "Qué es realmente GitHub Copilot CLI", "blocks": [{"kind": "p", "text": "GitHub Copilot CLI es el agente de programación nativo de terminal de GitHub. Lee tu repositorio, edita archivos, ejecuta comandos de shell y trabaja directamente con tu contexto de GitHub —issues, pull requests y repositorios— autenticado con tu cuenta de GitHub existente. Está impulsado por el mismo entorno agéntico que el agente de programación de Copilot de GitHub, de modo que planifica tareas complejas e itera en lugar de limitarse a completar líneas. Alcanzó la disponibilidad general en febrero de 2026, tras una versión preliminar pública que se abrió en septiembre de 2025."}, {"kind": "p", "text": "Para el trabajo de diseño, destacan dos propiedades. Lee archivos de instrucciones personalizadas —reglas para todo el repositorio en .github/copilot-instructions.md más AGENTS.md—, así que tus convenciones de diseño se incluyen automáticamente en cada ejecución. Y admite múltiples proveedores de modelos fundacionales, de modo que puedes cambiar de modelo según la tarea con el comando /model, optando por el que mejor razona sobre una interfaz dada."}, {"kind": "steps", "items": [{"label": "Archivos de instrucciones", "body": "Copilot CLI lee las instrucciones del repositorio en .github/copilot-instructions.md, los archivos específicos por ruta dentro de .github/instructions y AGENTS.md, el lugar natural para codificar tus convenciones de diseño, tokens y listas de comprobación de revisión."}, {"label": "Herramientas integradas + MCP", "body": "Viene con el servidor MCP de GitHub integrado y ejecuta herramientas de archivos y shell, y puedes añadir servidores MCP personalizados con /mcp add (almacenados en mcp-config.json dentro de ~/.copilot) para contexto externo, como un archivo de Figma en vivo."}, {"label": "Elección de modelo", "body": "Usa el comando /model para elegir entre modelos de frontera de Anthropic, OpenAI y Google, cambiando según la tarea, todo con tu suscripción existente de Copilot."}]}, {"kind": "ul", "items": ["Proveedor: GitHub", "Credencial: una suscripción activa a GitHub Copilot (Pro, Pro+, Business o Enterprise)", "Instalación: npm install -g @github/copilot, luego ejecuta copilot"]}]}, {"id": "why-design", "heading": "Por qué las instrucciones de repositorio y la elección de modelo encajan con el diseño", "blocks": [{"kind": "p", "text": "La ventaja de Copilot CLI para diseño proviene de dos propiedades, pero, como con todo agente, el buen gusto sigue teniendo que aportarse."}, {"kind": "steps", "items": [{"label": "Convenciones que viajan con el repositorio", "body": "Como Copilot CLI lee .github/copilot-instructions.md y AGENTS.md automáticamente, tus tokens, primitivas y reglas de revisión están en contexto en cada ejecución: el agente trabaja contra una marca en lugar de un aspecto por defecto."}, {"label": "Elige el modelo adecuado por tarea", "body": "La elección de modelo entre Anthropic, OpenAI y Google significa que puedes recurrir al modelo que mejor razona sobre una maquetación dada y luego cambiar para la siguiente tarea, sin modificar tu flujo de trabajo."}, {"label": "Especificaciones reales mediante MCP", "body": "El servidor MCP de GitHub integrado más un servidor MCP de Figma dirigen al agente a tus tokens, componentes y especificaciones reales, para que construya desde la fuente en lugar de aproximarla."}]}, {"kind": "image", "src": "/agents/copilot-design/copilot-design-taste-triangle.webp", "alt": "Diagrama que muestra cómo el sistema de diseño, el skill y la imagen de referencia convergen en una buena salida de diseño", "caption": "El buen gusto proviene de tres insumos que tú aportas: un sistema de diseño, un skill e imágenes de referencia reales."}, {"kind": "p", "text": "La lección es la misma que enseña cada agente: Copilot CLI no tiene buen gusto por defecto. Produce buen diseño cuando le das restricciones: un sistema de diseño, un skill estético y referencias concretas. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan (más abajo, con más detalle)."}]}, {"id": "setup", "heading": "Configura Copilot CLI para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un Copilot CLI capaz de construir y verificar interfaces."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Copilot CLI (Node.js required)\nnpm install -g @github/copilot\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\ncopilot           # run /login and follow the prompts to sign in\n\n# 3. Choose a model for the task\n#    inside the session:\n/model            # pick a frontier model from Anthropic, OpenAI, or Google\n\n# 4. Add custom instructions and the Figma MCP server (optional)\n#    write .github/copilot-instructions.md or AGENTS.md\n/mcp add          # add the Figma MCP server for design handoff"}, {"kind": "image", "src": "/agents/copilot-design/copilot-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticarse, elegir un modelo, configurar instrucciones, verificar", "caption": "La secuencia de configuración: instalar → autenticarse → elegir un modelo → escribir instrucciones → habilitar la verificación en el navegador."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Pon tus tokens, primitivas y convenciones en .github/copilot-instructions.md o AGENTS.md, para que la salida coincida con una marca en lugar de recurrir a un aspecto genérico."}, {"label": "Añade verificación en el navegador", "body": "Conecta un MCP de Playwright o de navegador para que Copilot renderice en un navegador real y compruebe su salida en distintos puntos de quiebre, en lugar de limitarse a confirmar que la compilación pasa."}]}]}, {"id": "screenshot-workflow", "heading": "El flujo de trabajo de captura de pantalla a interfaz", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor impacto con Copilot CLI es convertir una imagen de referencia en una interfaz funcional y adaptable e iterar hasta que coincida, apoyándose en un modelo multimodal potente para comparar la salida con la referencia."}, {"kind": "ol", "items": ["Parte de las referencias visuales más claras que tengas, e incluye varios estados (escritorio y móvil, hover, vacío, cargando), no solo una captura principal.", "Sé específico en el prompt; los prompts vagos producen interfaces genéricas incluso con un modelo potente.", "Mantén tu sistema de diseño y convenciones en .github/copilot-instructions.md o AGENTS.md, e indícale a Copilot dónde viven los tokens y las primitivas canónicas.", "Ejecuta un servidor de desarrollo y haz que Copilot renderice en un navegador real, redimensionando a los puntos de quiebre para comprobar el resultado.", "Itera haciendo que Copilot compare su implementación con las capturas, no que se limite a confirmar que compila."]}, {"kind": "p", "text": "Dirige a Copilot a tus imágenes de referencia y dale restricciones concretas; previsualiza cada edición de archivo o comando para tu aprobación antes de ejecutarlo:"}, {"kind": "code", "lang": "bash", "code": "copilot\n# in the prompt:\n> Implement the design in reference-desktop.png and reference-mobile.png\n  in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens described in\n  .github/copilot-instructions.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Render it in the browser and iterate until it matches the references\n  across breakpoints."}, {"kind": "p", "text": "Mantén los prompts pequeños y enfocados, confirma las buenas iteraciones y revierte las malas (avisándole a Copilot cuando reviertas), para que cada pasada se construya sobre una base limpia."}]}, {"id": "extend", "heading": "Instrucciones personalizadas, MCP y extensiones", "blocks": [{"kind": "p", "text": "Tres puntos de extensión hacen que Copilot CLI sea práctico para trabajo de diseño sostenido, y los tres encajan limpiamente en un flujo de trabajo de diseño abierto."}, {"kind": "steps", "items": [{"label": "Instrucciones personalizadas", "body": "Las reglas del repositorio viven en .github/copilot-instructions.md (con archivos específicos por ruta dentro de .github/instructions y AGENTS.md). Son el hogar duradero de tus convenciones de diseño, incluidas automáticamente en cada ejecución."}, {"label": "Servidores MCP", "body": "Copilot CLI viene con el servidor MCP de GitHub integrado y te permite añadir servidores personalizados mediante /mcp add (almacenados en mcp-config.json dentro de ~/.copilot): la forma portátil de incorporar contexto de diseño, sobre todo el servidor MCP de Figma, que funciona entre agentes, no solo en Copilot."}, {"label": "Agentes especializados y herramientas integradas", "body": "Los modos especializados de Copilot CLI —para explorar la base de código, ejecutar compilaciones y pruebas, revisar cambios y planificar— más sus herramientas de archivos y shell le permiten reunir referencias y ejecutar el bucle de verificación sin salir de la terminal."}]}, {"kind": "p", "text": "Estas son capacidades portátiles y multiagente, exactamente el tipo de cosas que Open Design está diseñado para orquestar, en lugar de recrearlas en cada proyecto."}]}, {"id": "vs", "heading": "Copilot CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño: cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Ideal para"], "rows": [["Copilot CLI", "Elección de varios modelos (Anthropic, OpenAI, Google) e integración profunda con GitHub en tu suscripción de Copilot", "Elegir el mejor modelo por tarea y trabajo guiado por instrucciones ligado a tu repositorio de GitHub"], ["Codex", "Gran pulido visual con un skill de frontend; compilaciones asíncronas en sandbox", "Compilaciones asíncronas delegadas y reglas portátiles de AGENTS.md"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de interfaz ajustado de iterar y observar dentro de un IDE"], ["Gemini CLI", "Sólida comprensión de imágenes multimodal y un contexto de 1M de tokens; de código abierto con un plan gratuito", "Trabajo con muchas capturas de pantalla y mantener todo un sistema de diseño en contexto"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el buen gusto proviene de las personas: todos recurren por defecto a una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver, y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Obstáculos y cómo evitar el aspecto de «IA descuidada»", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por IA es que parece genérico: degradados suaves, paneles flotantes, esquinas redondeadas demasiado grandes, sombras dramáticas, un aire de Inter y morado que «grita que esto lo hizo una IA». Otros problemas reportados incluyen maquetaciones móviles rotas e instrucciones que se filtran en el texto de la interfaz. Ninguno de ellos es exclusivo de Copilot CLI; son lo que ocurre cuando cualquier agente se ejecuta sin un contexto de diseño curado."}, {"kind": "steps", "items": [{"label": "Añade un skill estético", "body": "Un skill de diseño curado obliga al agente a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Verifica en un navegador real", "body": "Renderiza y autoverifica en distintos puntos de quiebre con un MCP de navegador para que las maquetaciones no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de referencia son la mayor palanca individual sobre la calidad de la salida."}, {"label": "Codifica reglas en instrucciones personalizadas", "body": "Pon reglas de estilo como «sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca» en .github/copilot-instructions.md o AGENTS.md, donde el agente las lee en cada ejecución."}]}, {"kind": "p", "text": "Fíjate en que toda mitigación consiste en dar al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es la tarea pesada que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con Copilot CLI dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño de código abierto que el flujo de trabajo anterior no deja de pedir. Trata a GitHub Copilot CLI como un adaptador de primera categoría y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de renderizado estructurada y una interfaz de escritorio local, de modo que el contexto de diseño que hace bueno a Copilot está ahí desde la primera ejecución, no ensamblado a mano cada vez. Open Design es independiente, de código abierto (Apache-2.0) y local-first, y por eso la combinación encaja: el agente hace el trabajo, y tus archivos y credenciales siguen siendo tuyos."}, {"kind": "ol", "items": ["Instala Open Design y selecciona GitHub Copilot CLI como tu agente.", "Autentícate con tu suscripción a GitHub Copilot: las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y un skill, y luego genera presentaciones, prototipos y páginas de aterrizaje con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente Copilot CLI, la misma suscripción, más un flujo de trabajo de diseño real, portátil y de código abierto a su alrededor. Open Design es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Puede GitHub Copilot CLI hacer realmente trabajo de diseño?", "text": "Sí: con un skill estético, un sistema de diseño e imágenes de referencia reales en contexto, Copilot CLI produce interfaces adaptables de calidad de producción, y puedes elegir el modelo que mejor verifica la salida frente a las referencias. Sin ese contexto tiende a recurrir a un aspecto genérico, que es la brecha que Open Design rellena."}, {"name": "¿Necesito una suscripción para diseñar con Copilot CLI?", "text": "Sí: Copilot CLI funciona con una suscripción activa a GitHub Copilot (Pro, Pro+, Business o Enterprise); no es de tipo trae tu propia clave. Te autenticas con tu cuenta de GitHub. Open Design nunca actúa de intermediario con tus credenciales: tu suscripción la usa directamente tu agente."}, {"name": "¿Qué hace bueno a Copilot CLI para diseño en concreto?", "text": "Dos cosas: lee las instrucciones del repositorio y AGENTS.md automáticamente, de modo que tus convenciones de diseño viajan con el repositorio; y te permite cambiar entre modelos de frontera de Anthropic, OpenAI y Google según la tarea. Ambas ayudan, pero el buen gusto sigue proviniendo del sistema de diseño, el skill y las referencias que tú aportas."}, {"name": "¿Copilot CLI o Claude Code para diseño de frontend?", "text": "Ambos son potentes. Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código; la ventaja de Copilot CLI es la elección de modelo entre proveedores y la integración profunda con GitHub en una suscripción que quizá ya tengas. Muchos equipos usan ambos: Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto Copilot CLI con Figma?", "text": "Añade el servidor MCP de Figma con el comando /mcp add; la configuración se almacena en mcp-config.json dentro de ~/.copilot. Copilot puede entonces extraer contexto de diseño real —componentes, variables, datos de maquetación— para que el código generado coincida con la fuente en lugar de aproximarla."}, {"name": "¿Open Design está afiliado a GitHub o Microsoft?", "text": "No. GitHub Copilot CLI es un producto de GitHub; Open Design es un proyecto independiente de código abierto que lo admite como adaptador de primera categoría. GitHub Copilot es una marca comercial de GitHub, Inc. y Microsoft."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí: Open Design es local-first y Apache-2.0. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de GitHub Copilot las usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con GitHub Copilot CLI, a la manera abierta.", "ctaBody": "Trae tu suscripción a GitHub Copilot, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente que ya usas.", "ctaActions": [{"label": "Usa Copilot CLI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'qwen': {
        ...en['qwen']!,
        title: "Qwen Code para diseño — Open Design",
        description: "Cómo se usa el CLI de código abierto Qwen Code de Alibaba para diseño de interfaces y web —sus modelos Qwen3-Coder, su gran ventana de contexto, QWEN.md y MCP— y cómo Open Design convierte Qwen Code en un agente de diseño local-first y de código abierto.",
        breadcrumb: "Qwen Code",
        label: "Agente · Qwen Code",
        heading: "Qwen Code para diseño.",
        lead: "Qwen Code es el agente de terminal de código abierto de Alibaba, adaptado de Gemini CLI y ajustado para los modelos Qwen3-Coder. Su gran ventana de contexto mantiene todo un sistema de diseño a la vez, lo que lo convierte en una verdadera herramienta de diseño, una vez que le das referencias, convenciones y un bucle de verificación. Open Design lo integra en un flujo de trabajo de diseño de código abierto: tu clave de API de DashScope o Qwen, tus archivos, local-first.",
        rich: {"heroCtaLead": "Open Design convierte Qwen Code en un agente de diseño local-first y de código abierto: tu clave de API de DashScope o Qwen, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa Qwen Code dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Qwen Code es el agente de IA de código abierto de Alibaba para la terminal. Está adaptado de Gemini CLI de Google, con adaptaciones a nivel de parser y de prompt que le permiten sacar el máximo partido a los modelos Qwen3-Coder. Dos cosas lo hacen interesante específicamente para diseño: es un potente modelo de programación agéntica, así que planifica, edita archivos y ejecuta el bucle de compilación y verificación a partir de una tarea en lenguaje natural; y su gran ventana de contexto puede mantener un sistema de diseño y una base de código enteros a la vez. Combinado con las referencias, convenciones y un bucle de verificación adecuados, construye interfaces reales y adaptables, y es de código abierto y BYOK, así que traes tu propia clave. Esta es una guía práctica y de extremo a extremo para usar Qwen Code en trabajo de interfaces, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es realmente Qwen Code, por qué un modelo de programación potente más un gran contexto encajan con el diseño, cómo configurarlo desde cero, el bucle de referencia a interfaz, cómo lo amplían QWEN.md y MCP, cómo se compara con Codex, Claude Code, Cursor y Gemini CLI, los obstáculos que hacen que la salida de la IA parezca genérica, y cómo Open Design cierra la brecha como una capa de diseño abierta y local-first: una combinación natural, ya que ambos son de código abierto y se ejecutan en tu propia máquina."], "heroImage": {"src": "/agents/qwen-design/qwen-design-hero.webp", "alt": "Bucle de retroalimentación de diseño de Qwen Code: un agente de terminal leyendo una imagen de referencia, un navegador renderizando la interfaz y un espacio de trabajo, con una flecha de retroalimentación que vuelve al inicio", "caption": "El bucle central: Qwen Code lee tus referencias en la terminal, construye y verifica la interfaz en un navegador real e itera frente a ellas, con todo un sistema de diseño en contexto."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-qwen", "label": "Qué es realmente Qwen Code"}, {"id": "why-design", "label": "Por qué un modelo de programación potente + un gran contexto encajan con el diseño"}, {"id": "setup", "label": "Configura Qwen Code para diseño (desde cero)"}, {"id": "screenshot-workflow", "label": "El flujo de trabajo de referencia a interfaz"}, {"id": "extend", "label": "QWEN.md, MCP y extensiones"}, {"id": "vs", "label": "Qwen Code vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Obstáculos y el aspecto de «IA descuidada»"}, {"id": "open-design", "label": "Diseñar con Qwen Code en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-qwen", "heading": "Qué es realmente Qwen Code", "blocks": [{"kind": "p", "text": "Qwen Code es un agente de IA de código abierto (Apache-2.0) que Alibaba ofrece para la terminal. Lee tu repositorio, edita archivos, ejecuta comandos de shell y trabaja en la web, planificando y verificando el trabajo a partir de tareas en lenguaje natural en lugar de limitarse a completar líneas. Está adaptado de Gemini CLI de Google, con adaptaciones a nivel de parser y de prompt ajustadas para desbloquear los modelos Qwen3-Coder en tareas de programación agéntica."}, {"kind": "p", "text": "Para el trabajo de diseño, destacan dos propiedades. Es un programador agéntico capaz, así que puede tomar una referencia y un encargo claro y construir, ejecutar y autocorregir interfaces adaptables. Y los modelos Qwen3-Coder llevan una gran ventana de contexto, lo bastante grande para mantener tu sistema de diseño, biblioteca de componentes y conjunto de referencias enteros a la vez, en lugar de resumirlos."}, {"kind": "steps", "items": [{"label": "Archivos de contexto", "body": "Qwen Code lee un archivo QWEN.md como contexto persistente del proyecto, el lugar natural para codificar tus convenciones de diseño, tokens y listas de comprobación de revisión. Los ajustes personales y de proyecto se superponen encima."}, {"label": "Herramientas integradas + MCP", "body": "Viene con herramientas de archivos, shell y web de fábrica, y admite servidores MCP (configurados bajo mcpServers en ~/.qwen/settings.json) para añadir contexto externo, como un archivo de Figma en vivo."}, {"label": "BYOK para empezar", "body": "Traes tu propia clave —una clave de API de DashScope (Alibaba Cloud Model Studio), o cualquier endpoint compatible con OpenAI o ModelScope— y la configuras en settings.json."}]}, {"kind": "ul", "items": ["Proveedor: Alibaba", "Credencial: clave de API de DashScope / Qwen (BYOK), o endpoint compatible con OpenAI / ModelScope", "Licencia: Apache-2.0, código abierto (adaptado de Gemini CLI)"]}]}, {"id": "why-design", "heading": "Por qué un modelo de programación potente y un gran contexto encajan con el diseño", "blocks": [{"kind": "p", "text": "La ventaja de Qwen Code para diseño proviene de dos propiedades, pero, como con todo agente, el buen gusto sigue teniendo que aportarse."}, {"kind": "steps", "items": [{"label": "Programación agéntica potente", "body": "Los modelos Qwen3-Coder están ajustados para tareas agénticas, así que el agente planifica, edita, ejecuta la compilación y se autocorrige, convirtiendo una referencia y un encargo claros en marcado adaptable en lugar de una conjetura de un solo intento."}, {"label": "Una gran ventana de contexto", "body": "El gran contexto de Qwen3-Coder significa que todo el sistema de diseño, los tokens y muchos estados de referencia caben a la vez, así que el agente reutiliza tus primitivas reales en lugar de inventar estilos puntuales."}, {"label": "Convenciones en QWEN.md", "body": "Un QWEN.md (más el servidor MCP de Figma) dirige al agente a tus tokens, componentes y especificaciones reales, para que trabaje contra una marca en lugar de un aspecto por defecto."}]}, {"kind": "image", "src": "/agents/qwen-design/qwen-design-taste-triangle.webp", "alt": "Diagrama que muestra cómo el sistema de diseño, el skill y la imagen de referencia convergen en una buena salida de diseño", "caption": "El buen gusto proviene de tres insumos que tú aportas: un sistema de diseño, un skill e imágenes de referencia reales."}, {"kind": "p", "text": "La lección es la misma que enseña cada agente: Qwen Code no tiene buen gusto por defecto. Produce buen diseño cuando le das restricciones: un sistema de diseño, un skill estético y referencias concretas. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan (más abajo, con más detalle)."}]}, {"id": "setup", "heading": "Configura Qwen Code para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un Qwen Code capaz de construir y verificar interfaces."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Qwen Code (Node 22+)\nnpm install -g @qwen-code/qwen-code@latest\n# or: brew install qwen-code\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\nqwen              # run /auth, or set a key in ~/.qwen/settings.json\n\n# 3. Configure a DashScope (OpenAI-compatible) key in settings.json\n#    baseUrl: https://dashscope.aliyuncs.com/compatible-mode/v1\n#    model:   qwen3-coder-plus   (set DASHSCOPE_API_KEY)\n\n# 4. Add a QWEN.md and wire the Figma MCP server (optional)\n#    add MCP under \"mcpServers\" in ~/.qwen/settings.json"}, {"kind": "image", "src": "/agents/qwen-design/qwen-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticarse, configurar QWEN.md, añadir un skill, verificar", "caption": "La secuencia de configuración: instalar → autenticarse → configurar QWEN.md → añadir un skill → habilitar la verificación en el navegador."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Pon tus tokens, primitivas y convenciones en QWEN.md y dirige a Qwen Code hacia ellos, para que la salida coincida con una marca en lugar de recurrir a un aspecto genérico."}, {"label": "Añade verificación en el navegador", "body": "Conecta un MCP de Playwright o de navegador para que Qwen Code renderice en un navegador real y compruebe su salida en distintos puntos de quiebre, en lugar de limitarse a confirmar que la compilación pasa."}]}]}, {"id": "screenshot-workflow", "heading": "El flujo de trabajo de referencia a interfaz", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor impacto con Qwen Code es convertir una referencia en una interfaz funcional y adaptable e iterar hasta que coincida, apoyándose en el agente para construir, renderizar y comparar su salida con la referencia."}, {"kind": "ol", "items": ["Parte de las referencias visuales más claras que tengas, y describe varios estados (escritorio y móvil, hover, vacío, cargando), no solo una captura principal.", "Sé específico en el prompt; los prompts vagos producen interfaces genéricas incluso con un modelo potente.", "Mantén tu sistema de diseño y convenciones en QWEN.md, e indícale a Qwen Code dónde viven los tokens y las primitivas canónicas.", "Ejecuta un servidor de desarrollo y haz que Qwen Code renderice en un navegador real, redimensionando a los puntos de quiebre para comprobar el resultado.", "Itera haciendo que Qwen Code compare su implementación con las referencias, no que se limite a confirmar que compila."]}, {"kind": "p", "text": "Referencia un archivo con @ para adjuntarlo al prompt, y luego da restricciones concretas:"}, {"kind": "code", "lang": "bash", "code": "qwen\n# in the prompt:\n> @reference-desktop.png @reference-mobile.png\n  Implement this design in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from QWEN.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Render it in the browser and iterate until it matches the references\n  across breakpoints."}, {"kind": "p", "text": "Mantén los prompts pequeños y enfocados, confirma las buenas iteraciones y revierte las malas (avisándole a Qwen Code cuando reviertas), para que cada pasada se construya sobre una base limpia."}]}, {"id": "extend", "heading": "QWEN.md, MCP y extensiones", "blocks": [{"kind": "p", "text": "Tres puntos de extensión hacen que Qwen Code sea práctico para trabajo de diseño sostenido, y los tres encajan limpiamente en un flujo de trabajo de diseño abierto."}, {"kind": "steps", "items": [{"label": "Contexto de QWEN.md", "body": "Las reglas del proyecto viven en un QWEN.md en la raíz del repositorio (con capas global y de proyecto). Es el hogar duradero de tus convenciones de diseño, leído en cada ejecución."}, {"label": "Servidores MCP", "body": "Configura servidores MCP bajo mcpServers en ~/.qwen/settings.json: la forma portátil de incorporar contexto de diseño y herramientas externas, sobre todo el servidor MCP de Figma, que funcionan entre agentes, no solo en Qwen Code."}, {"label": "Skills y herramientas integradas", "body": "Los skills de Qwen Code y sus herramientas integradas de archivos, shell y web le permiten reunir referencias y ejecutar el bucle de verificación sin salir de la terminal."}]}, {"kind": "p", "text": "Estas son capacidades portátiles y multiagente, exactamente el tipo de cosas que Open Design está diseñado para orquestar, en lugar de recrearlas en cada proyecto."}]}, {"id": "vs", "heading": "Qwen Code vs Codex vs Claude Code vs Cursor vs Gemini CLI para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño: cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Ideal para"], "rows": [["Qwen Code", "Programación agéntica potente sobre los modelos abiertos Qwen3-Coder con un gran contexto; de código abierto y BYOK", "Compilaciones de código abierto y flexibles en cuanto a clave que mantienen todo un sistema de diseño en contexto"], ["Codex", "Gran pulido visual con un skill de frontend; compilaciones asíncronas en sandbox", "Compilaciones asíncronas delegadas y reglas portátiles de AGENTS.md"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de interfaz ajustado de iterar y observar dentro de un IDE"], ["Gemini CLI", "Sólida comprensión de imágenes multimodal y un contexto de 1M de tokens; el agente del que se adapta Qwen Code", "Trabajo con muchas capturas de pantalla y contexto muy grande"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el buen gusto proviene de las personas: todos recurren por defecto a una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver, y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Obstáculos y cómo evitar el aspecto de «IA descuidada»", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por IA es que parece genérico: degradados suaves, paneles flotantes, esquinas redondeadas demasiado grandes, sombras dramáticas, un aire de Inter y morado que «grita que esto lo hizo una IA». Otros problemas reportados incluyen maquetaciones móviles rotas e instrucciones que se filtran en el texto de la interfaz. Ninguno de ellos es exclusivo de Qwen Code; son lo que ocurre cuando cualquier agente se ejecuta sin un contexto de diseño curado."}, {"kind": "steps", "items": [{"label": "Añade un skill estético", "body": "Un skill de diseño curado obliga al agente a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Verifica en un navegador real", "body": "Haz que el agente renderice y autoverifique en distintos puntos de quiebre para que las maquetaciones no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de referencia son la mayor palanca individual sobre la calidad de la salida."}, {"label": "Codifica reglas en QWEN.md", "body": "Pon reglas de estilo como «sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca» donde el agente las lee en cada ejecución."}]}, {"kind": "p", "text": "Fíjate en que toda mitigación consiste en dar al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es la tarea pesada que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con Qwen Code dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño de código abierto que el flujo de trabajo anterior no deja de pedir. Trata a Qwen Code como un adaptador de primera categoría y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de renderizado estructurada y una interfaz de escritorio local, de modo que el contexto de diseño que hace bueno a Qwen Code está ahí desde la primera ejecución, no ensamblado a mano cada vez. Ambos son de código abierto y local-first, lo que hace que la combinación encaje de forma natural."}, {"kind": "ol", "items": ["Instala Open Design y selecciona Qwen Code como tu agente.", "Autentícate con tu clave de API de DashScope o Qwen (BYOK): las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y un skill, y luego genera presentaciones, prototipos y páginas de aterrizaje con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente Qwen Code, la misma clave, más un flujo de trabajo de diseño real, portátil y de código abierto a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Puede Qwen Code hacer realmente trabajo de diseño?", "text": "Sí: con un skill estético, un sistema de diseño e imágenes de referencia reales en contexto, Qwen Code produce interfaces adaptables de calidad de producción, y su bucle agéntico construye, renderiza y verifica la salida frente a las referencias. Sin ese contexto tiende a recurrir a un aspecto genérico, que es la brecha que Open Design rellena."}, {"name": "¿Tengo que pagar para diseñar con Qwen Code?", "text": "Qwen Code es gratuito y de código abierto, pero es BYOK: traes una clave de API de DashScope (Alibaba Cloud Model Studio), un endpoint compatible con OpenAI o ModelScope. Alibaba también ofrece un plan de programación de tarifa fija. Open Design nunca actúa de intermediario con tus credenciales en ningún caso."}, {"name": "¿Qué hace bueno a Qwen Code para diseño en concreto?", "text": "Dos cosas: los modelos Qwen3-Coder están ajustados para programación agéntica, así que el agente construye y autocorrige interfaces adaptables, y su gran contexto puede mantener un sistema de diseño y un conjunto de referencias enteros a la vez. Ambas ayudan, pero el buen gusto sigue proviniendo del sistema de diseño, el skill y las referencias que tú aportas."}, {"name": "¿Qwen Code es lo mismo que Gemini CLI?", "text": "No. Qwen Code está adaptado de Gemini CLI de Google —el mismo linaje de código abierto— con adaptaciones a nivel de parser y de prompt que lo ajustan para los modelos Qwen3-Coder. Open Design admite ambos, así que puedes cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto Qwen Code con Figma?", "text": "Añade el servidor MCP de Figma bajo mcpServers en ~/.qwen/settings.json. Qwen Code puede entonces extraer contexto de diseño real —componentes, variables, datos de maquetación— para que el código generado coincida con la fuente en lugar de aproximarla."}, {"name": "¿Open Design está afiliado a Alibaba o Qwen?", "text": "No. Qwen Code es un producto de Alibaba; Open Design es un proyecto independiente de código abierto que lo admite como adaptador de primera categoría. Qwen es una marca comercial de Alibaba."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí: Open Design es local-first y Apache-2.0. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de DashScope o Qwen las usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con Qwen Code, a la manera abierta.", "ctaBody": "Trae tu propia clave de API de DashScope o Qwen, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente que ya usas.", "ctaActions": [{"label": "Usa Qwen Code dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'grok': {
        ...en['grok']!,
        title: "Grok CLI para diseño — Open Design",
        description: "Cómo se usa Grok CLI (Grok Build) de xAI para diseño de interfaces y web —su modo plan, AGENTS.md y MCP, los modelos Grok con reconocimiento de imágenes y un gran contexto— y cómo Open Design convierte Grok CLI en un agente de diseño local-first y de código abierto.",
        breadcrumb: "Grok CLI",
        label: "Agente · Grok CLI",
        heading: "Grok CLI para diseño.",
        lead: "Grok CLI es el agente de programación de terminal de xAI. Planifica el trabajo de varios pasos antes de tocar tus archivos, lee imágenes junto al código y ejecuta el bucle de construir y verificar en tu repositorio, lo que lo convierte en una verdadera herramienta de diseño una vez que le das referencias, convenciones y un paso de verificación. Open Design lo integra en un flujo de trabajo de diseño de código abierto: tu inicio de sesión de SuperGrok o tu clave de API de xAI, tus archivos, local-first.",
        rich: {"heroCtaLead": "Open Design convierte Grok CLI en un agente de diseño local-first y de código abierto: tu inicio de sesión de SuperGrok o tu clave de API de xAI, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa Grok CLI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Grok CLI —el agente de programación de terminal de xAI, distribuido como Grok Build— es una herramienta agéntica que vive en tu terminal. Dos cosas lo hacen interesante específicamente para diseño: planifica el trabajo arriesgado antes de actuar, así que puedes revisar un enfoque propuesto antes de que cambie ningún archivo; y sus modelos Grok aceptan entrada de imágenes, de modo que puede razonar sobre una captura de referencia junto al código que escribe. Combinado con las referencias, convenciones y un bucle de verificación adecuados, construye interfaces reales y adaptables, autenticado directamente a través de tu cuenta de SuperGrok o X Premium+, sin tener que hacer malabares con claves de API. Esta es una guía práctica y de extremo a extremo para usar Grok CLI en trabajo de interfaces, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es realmente Grok CLI, por qué el modo plan y los modelos con reconocimiento de imágenes encajan con el diseño, cómo configurarlo desde cero, el bucle de captura de pantalla a interfaz, cómo lo amplían AGENTS.md y MCP, cómo se compara con Codex, Claude Code, Cursor y Gemini CLI, los obstáculos que hacen que la salida de la IA parezca genérica, y cómo Open Design cierra la brecha como una capa de diseño abierta y local-first: tus credenciales y artefactos nunca salen de tu máquina."], "heroImage": {"src": "/agents/grok-design/grok-design-hero.webp", "alt": "Bucle de retroalimentación de diseño de Grok CLI: un agente de terminal planificando a partir de una imagen de referencia, un navegador renderizando la interfaz y un espacio de trabajo, con una flecha de retroalimentación que vuelve al inicio", "caption": "El bucle central: Grok CLI planifica a partir de tus referencias en la terminal, construye y verifica la interfaz en un navegador real e itera frente a ellas, con tus convenciones en AGENTS.md."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-grok", "label": "Qué es realmente Grok CLI"}, {"id": "why-design", "label": "Por qué el modo plan + la entrada de imágenes encajan con el diseño"}, {"id": "setup", "label": "Configura Grok CLI para diseño (desde cero)"}, {"id": "screenshot-workflow", "label": "El flujo de trabajo de captura de pantalla a interfaz"}, {"id": "extend", "label": "AGENTS.md, MCP y subagentes"}, {"id": "vs", "label": "Grok CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Obstáculos y el aspecto de «IA descuidada»"}, {"id": "open-design", "label": "Diseñar con Grok CLI en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-grok", "heading": "Qué es realmente Grok CLI", "blocks": [{"kind": "p", "text": "Grok CLI es el agente de programación de terminal de xAI, distribuido bajo el nombre de Grok Build. Lee tu repositorio, edita archivos, ejecuta comandos de shell y planifica trabajo de ingeniería de varios pasos a partir de tareas en lenguaje natural en lugar de limitarse a completar líneas. Está construido en torno a los modelos Grok de xAI —expuestos en la API de xAI como la familia de modelos grok-build— y se autentica a través de tu cuenta de xAI, así que el agente y los modelos provienen del mismo proveedor."}, {"kind": "p", "text": "Para el trabajo de diseño, destacan dos propiedades. Tiene un modo plan que redacta un enfoque estructurado que puedes aprobar, comentar o reescribir antes de que aterrice ningún cambio, una compuerta útil cuando estás iterando sobre la interfaz. Y sus modelos Grok aceptan entrada de imágenes, así que puedes entregarle una captura de referencia y razona sobre la maquetación real en lugar de adivinar a partir de una descripción en prosa."}, {"kind": "steps", "items": [{"label": "Archivos de contexto", "body": "Grok CLI lee un archivo AGENTS.md como contexto persistente del proyecto, el lugar natural para codificar tus convenciones de diseño, tokens y listas de comprobación de revisión. Sigue la misma convención abierta de AGENTS.md que usan Codex y otros agentes."}, {"label": "Herramientas, MCP + subagentes", "body": "Edita archivos, ejecuta comandos de shell y admite servidores MCP para añadir contexto externo, como un archivo de Figma en vivo; para tareas más grandes puede delegar en subagentes paralelos que investigan, construyen y revisan a la vez."}, {"label": "Inicia sesión con tu cuenta", "body": "Te autenticas iniciando sesión a través de tu navegador con una suscripción a SuperGrok o X Premium+; también puedes traer una clave de API de xAI para uso headless y en CI."}]}, {"kind": "ul", "items": ["Proveedor: xAI", "Credencial: OAuth de SuperGrok de xAI (`grok login`), o una clave de API de xAI (BYOK) para uso headless", "Modelos: modelos Grok de xAI (la familia grok-build en la API de xAI), con entrada de imágenes"]}]}, {"id": "why-design", "heading": "Por qué el modo plan y los modelos con reconocimiento de imágenes encajan con el diseño", "blocks": [{"kind": "p", "text": "La ventaja de Grok CLI para diseño proviene de dos propiedades, pero, como con todo agente, el buen gusto sigue teniendo que aportarse."}, {"kind": "steps", "items": [{"label": "Razonamiento con reconocimiento de imágenes", "body": "Como los modelos Grok aceptan entrada de imágenes, el agente lee capturas de referencia, comparando su salida renderizada con una imagen en lugar de adivinar a partir de una descripción en prosa."}, {"label": "Modo plan antes de que aterricen los cambios", "body": "El modo plan redacta un enfoque estructurado que apruebas antes de que cambien los archivos, así que la intención de diseño se revisa de antemano en lugar de descubrirse después del diff."}, {"label": "Convenciones en AGENTS.md", "body": "Un AGENTS.md (más el servidor MCP de Figma) dirige al agente a tus tokens, componentes y especificaciones reales, para que trabaje contra una marca en lugar de un aspecto por defecto."}]}, {"kind": "image", "src": "/agents/grok-design/grok-design-taste-triangle.webp", "alt": "Diagrama que muestra cómo el sistema de diseño, el skill y la imagen de referencia convergen en una buena salida de diseño", "caption": "El buen gusto proviene de tres insumos que tú aportas: un sistema de diseño, un skill e imágenes de referencia reales."}, {"kind": "p", "text": "La lección es la misma que enseña cada agente: Grok CLI no tiene buen gusto por defecto. Produce buen diseño cuando le das restricciones: un sistema de diseño, un skill estético y referencias concretas. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan (más abajo, con más detalle)."}]}, {"id": "setup", "heading": "Configura Grok CLI para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un Grok CLI capaz de construir y verificar interfaces."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Grok CLI (Grok Build) on macOS/Linux\ncurl -fsSL https://x.ai/cli/install.sh | bash\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\ngrok login   # opens your browser; sign in with SuperGrok / X Premium+\n#   or, for headless / CI use, set an xAI API key:\n#   export XAI_API_KEY=xai-...\n\n# 3. Add project context\n#    create an AGENTS.md at the repo root with your design conventions\n\n# 4. Wire the Figma MCP server (optional, for design handoff)\n#    add it to your MCP server configuration"}, {"kind": "image", "src": "/agents/grok-design/grok-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticarse, configurar AGENTS.md, añadir un skill, verificar", "caption": "La secuencia de configuración: instalar → autenticarse → configurar AGENTS.md → añadir un skill → habilitar la verificación en el navegador."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Pon tus tokens, primitivas y convenciones en AGENTS.md y dirige a Grok hacia ellos, para que la salida coincida con una marca en lugar de recurrir a un aspecto genérico."}, {"label": "Añade verificación en el navegador", "body": "Conecta un MCP de Playwright o de navegador para que Grok renderice en un navegador real y compruebe su salida en distintos puntos de quiebre, en lugar de limitarse a confirmar que la compilación pasa."}]}]}, {"id": "screenshot-workflow", "heading": "El flujo de trabajo de captura de pantalla a interfaz", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor impacto con Grok CLI es convertir una imagen de referencia en una interfaz funcional y adaptable e iterar hasta que coincida, apoyándose en el modo plan para acordar el enfoque y en el modelo con reconocimiento de imágenes para comparar la salida con la referencia."}, {"kind": "ol", "items": ["Parte de las referencias visuales más claras que tengas, e incluye varios estados (escritorio y móvil, hover, vacío, cargando), no solo una captura principal.", "Sé específico en el prompt; los prompts vagos producen interfaces genéricas incluso con un modelo potente.", "Mantén tu sistema de diseño y convenciones en AGENTS.md, e indícale a Grok dónde viven los tokens y las primitivas canónicas.", "Usa el modo plan para revisar el enfoque, luego ejecuta un servidor de desarrollo y haz que Grok renderice en un navegador real, redimensionando a los puntos de quiebre para comprobar el resultado.", "Itera haciendo que Grok compare su implementación con las capturas, no que se limite a confirmar que compila."]}, {"kind": "p", "text": "Adjunta tus imágenes de referencia y da restricciones concretas:"}, {"kind": "code", "lang": "bash", "code": "grok\n# in the prompt (attach reference-desktop.png and reference-mobile.png):\n> Implement this design in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from AGENTS.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Show me the plan first, then render it in the browser and iterate\n  until it matches the references across breakpoints."}, {"kind": "p", "text": "Mantén los prompts pequeños y enfocados, confirma las buenas iteraciones y revierte las malas (avisándole a Grok cuando reviertas), para que cada pasada se construya sobre una base limpia."}]}, {"id": "extend", "heading": "AGENTS.md, MCP y subagentes", "blocks": [{"kind": "p", "text": "Tres puntos de extensión hacen que Grok CLI sea práctico para trabajo de diseño sostenido, y los tres encajan limpiamente en un flujo de trabajo de diseño abierto."}, {"kind": "steps", "items": [{"label": "Contexto de AGENTS.md", "body": "Las reglas del proyecto viven en un AGENTS.md en la raíz del repositorio. Es el hogar duradero de tus convenciones de diseño, leído en cada ejecución, y es el mismo formato abierto que entienden otros agentes, así que las reglas viajan contigo."}, {"label": "Servidores MCP", "body": "Configura servidores MCP para incorporar contexto de diseño y herramientas externas, sobre todo el servidor MCP de Figma: la forma portátil de inyectar especificaciones reales en el código, que funciona entre agentes, no solo en Grok."}, {"label": "Subagentes y herramientas integradas", "body": "Grok CLI puede generar subagentes paralelos para investigar, construir y revisar a la vez, y sus herramientas de archivos, shell y búsqueda le permiten reunir referencias y ejecutar el bucle de verificación sin salir de la terminal."}]}, {"kind": "p", "text": "Estas son capacidades portátiles y multiagente, exactamente el tipo de cosas que Open Design está diseñado para orquestar, en lugar de recrearlas en cada proyecto."}]}, {"id": "vs", "heading": "Grok CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño: cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Ideal para"], "rows": [["Grok CLI", "Revisión en modo plan antes de que aterricen los cambios, modelos Grok con reconocimiento de imágenes y subagentes paralelos; inicia sesión con tu cuenta de SuperGrok", "Compilaciones de interfaz revisadas y con el plan primero, con los modelos de xAI en el bucle"], ["Codex", "Gran pulido visual con un skill de frontend; compilaciones asíncronas en sandbox", "Compilaciones asíncronas delegadas y reglas portátiles de AGENTS.md"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de interfaz ajustado de iterar y observar dentro de un IDE"], ["Gemini CLI", "Sólida comprensión de imágenes multimodal y un contexto muy grande; de código abierto con un plan gratuito", "Trabajo con muchas capturas de pantalla y mantener todo un sistema de diseño en contexto"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el buen gusto proviene de las personas: todos recurren por defecto a una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver, y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Obstáculos y cómo evitar el aspecto de «IA descuidada»", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por IA es que parece genérico: degradados suaves, paneles flotantes, esquinas redondeadas demasiado grandes, sombras dramáticas, un aire de Inter y morado que «grita que esto lo hizo una IA». Otros problemas reportados incluyen maquetaciones móviles rotas e instrucciones que se filtran en el texto de la interfaz. Ninguno de ellos es exclusivo de Grok CLI; son lo que ocurre cuando cualquier agente se ejecuta sin un contexto de diseño curado."}, {"kind": "steps", "items": [{"label": "Añade un skill estético", "body": "Un skill de diseño curado obliga al agente a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Verifica en un navegador real", "body": "Renderiza y autoverifica en distintos puntos de quiebre para que las maquetaciones no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de referencia son la mayor palanca individual sobre la calidad de la salida."}, {"label": "Codifica reglas en AGENTS.md", "body": "Pon reglas de estilo como «sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca» donde el agente las lee en cada ejecución."}]}, {"kind": "p", "text": "Fíjate en que toda mitigación consiste en dar al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es la tarea pesada que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con Grok CLI dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño de código abierto que el flujo de trabajo anterior no deja de pedir. Trata a Grok CLI como un adaptador de primera categoría y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de renderizado estructurada y una interfaz de escritorio local, de modo que el contexto de diseño que hace bueno a Grok está ahí desde la primera ejecución, no ensamblado a mano cada vez. Open Design es independiente y Apache-2.0, y se ejecuta en tu propia máquina, lo que hace que la combinación encaje de forma natural."}, {"kind": "ol", "items": ["Instala Open Design y selecciona Grok CLI como tu agente.", "Autentícate con tu cuenta de SuperGrok o una clave de API de xAI (BYOK): las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y un skill, y luego genera presentaciones, prototipos y páginas de aterrizaje con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente Grok CLI, las mismas credenciales, más un flujo de trabajo de diseño real, portátil y de código abierto a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Puede Grok CLI hacer realmente trabajo de diseño?", "text": "Sí: con un skill estético, un sistema de diseño e imágenes de referencia reales en contexto, Grok CLI produce interfaces adaptables de calidad de producción, y sus modelos Grok con reconocimiento de imágenes ayudan a verificar la salida frente a las referencias. Sin ese contexto tiende a recurrir a un aspecto genérico, que es la brecha que Open Design rellena."}, {"name": "¿Cómo me autentico en Grok CLI?", "text": "Inicias sesión a través de tu navegador con una suscripción a SuperGrok o X Premium+ (`grok login`), así que no hay ninguna clave de API que gestionar. Para uso headless o en CI puedes traer una clave de API de xAI en su lugar. Open Design nunca actúa de intermediario con tus credenciales en ningún caso."}, {"name": "¿Qué hace bueno a Grok CLI para diseño en concreto?", "text": "Dos cosas: su modo plan te permite revisar el enfoque antes de que aterrice ningún cambio, y sus modelos Grok aceptan entrada de imágenes, así que lee bien las capturas de referencia. Ambas ayudan, pero el buen gusto sigue proviniendo del sistema de diseño, el skill y las referencias que tú aportas."}, {"name": "¿Grok CLI o Claude Code para diseño de frontend?", "text": "Ambos son potentes. Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código; la ventaja de Grok CLI es la revisión en modo plan y los modelos de xAI con reconocimiento de imágenes. Muchos equipos usan ambos: Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto Grok CLI con Figma?", "text": "Añade el servidor MCP de Figma a tu configuración de MCP. Grok puede entonces extraer contexto de diseño real —componentes, variables, datos de maquetación— para que el código generado coincida con la fuente en lugar de aproximarla."}, {"name": "¿Open Design está afiliado a xAI?", "text": "No. Grok CLI es un producto de xAI; Open Design es un proyecto independiente de código abierto que lo admite como adaptador de primera categoría. Grok es una marca comercial de xAI."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí: Open Design es local-first y Apache-2.0. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de xAI las usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con Grok CLI, a la manera abierta.", "ctaBody": "Trae tu propia cuenta de SuperGrok o clave de API de xAI, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente que ya usas.", "ctaActions": [{"label": "Usa Grok CLI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'kimi': {
        ...en['kimi']!,
        title: "Kimi CLI para diseño — Open Design",
        description: "Cómo se usa Kimi CLI de Moonshot AI para diseño de interfaces y web —sus modelos agénticos de la serie Kimi K2, un gran contexto, AGENTS.md y MCP— y cómo Open Design convierte Kimi CLI en un agente de diseño local-first y de código abierto.",
        breadcrumb: "Kimi CLI",
        label: "Agente · Kimi CLI",
        heading: "Kimi CLI para diseño.",
        lead: "Kimi CLI es el agente de terminal de código abierto de Moonshot AI, impulsado por la serie de modelos Kimi K2. Su potente programación agéntica y su gran ventana de contexto le permiten mantener todo un sistema de diseño e iterar frente a referencias: una vez que le das convenciones y un bucle de verificación, se convierte en una verdadera herramienta de diseño. Open Design lo integra en un flujo de trabajo de diseño de código abierto: tu clave de API de Moonshot, tus archivos, local-first.",
        rich: {"heroCtaLead": "Open Design convierte Kimi CLI en un agente de diseño local-first y de código abierto: tu clave de API de Moonshot, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa Kimi CLI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Kimi CLI es el agente de IA de código abierto de Moonshot AI para la terminal. Dos cosas lo hacen interesante específicamente para diseño: está impulsado por la serie Kimi K2 —un modelo de mezcla de expertos de un billón de parámetros meticulosamente optimizado para programación agéntica y uso de herramientas—; y ese modelo lleva una gran ventana de contexto (256k tokens en las versiones recientes de K2), lo bastante grande para mantener un sistema de diseño y una base de código enteros a la vez. Combinado con las referencias, convenciones y un bucle de verificación adecuados, construye interfaces reales y adaptables, y puedes empezar con un inicio de sesión OAuth o tu propia clave de API de Moonshot. Esta es una guía práctica y de extremo a extremo para usar Kimi CLI en trabajo de interfaces, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es realmente Kimi CLI, por qué sus modelos agénticos Kimi K2 y su gran contexto encajan con el diseño, cómo configurarlo desde cero, el bucle de referencia a interfaz, cómo lo amplían AGENTS.md, MCP y los subagentes, cómo se compara con Codex, Claude Code, Cursor y Gemini CLI, los obstáculos que hacen que la salida de la IA parezca genérica, y cómo Open Design cierra la brecha como una capa de diseño abierta y local-first: una combinación natural, ya que ambos son de código abierto y se ejecutan en tu propia máquina."], "heroImage": {"src": "/agents/kimi-design/kimi-design-hero.webp", "alt": "Bucle de retroalimentación de diseño de Kimi CLI: un agente de terminal leyendo una imagen de referencia, un navegador renderizando la interfaz y un espacio de trabajo, con una flecha de retroalimentación que vuelve al inicio", "caption": "El bucle central: Kimi CLI lee tus referencias en la terminal, construye y verifica la interfaz en un navegador real e itera frente a ellas, con todo un sistema de diseño en contexto."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-kimi", "label": "Qué es realmente Kimi CLI"}, {"id": "why-design", "label": "Por qué el K2 agéntico + un gran contexto encajan con el diseño"}, {"id": "setup", "label": "Configura Kimi CLI para diseño (desde cero)"}, {"id": "screenshot-workflow", "label": "El flujo de trabajo de referencia a interfaz"}, {"id": "extend", "label": "AGENTS.md, MCP y subagentes"}, {"id": "vs", "label": "Kimi CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Obstáculos y el aspecto de «IA descuidada»"}, {"id": "open-design", "label": "Diseñar con Kimi CLI en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-kimi", "heading": "Qué es realmente Kimi CLI", "blocks": [{"kind": "p", "text": "Kimi CLI es un agente de IA de código abierto (Apache-2.0) que Moonshot AI ofrece para la terminal. Lee tu repositorio, edita archivos, ejecuta comandos de shell, busca archivos, obtiene páginas web y elige su siguiente paso a partir de la retroalimentación que recibe, planificando y verificando el trabajo a partir de tareas en lenguaje natural en lugar de limitarse a completar líneas. Es una herramienta de Python, instalada con uv, y por debajo impulsa la familia de modelos Kimi K2."}, {"kind": "p", "text": "Para el trabajo de diseño, destacan dos propiedades. Los modelos Kimi K2 están ajustados explícitamente para programación agéntica de largo alcance y uso de herramientas, así que el agente puede llevar una construcción de varios pasos hasta un resultado funcional. Y la ventana de contexto alcanza hasta 256k tokens en las versiones recientes de K2, lo bastante grande para mantener tu sistema de diseño, biblioteca de componentes y conjunto de referencias enteros a la vez, en lugar de resumirlos."}, {"kind": "steps", "items": [{"label": "Archivos de contexto", "body": "Kimi CLI lee un archivo AGENTS.md como contexto persistente del proyecto, el lugar natural para codificar tus convenciones de diseño, tokens y listas de comprobación de revisión. Ejecuta /init para generar uno en un proyecto que no lo tenga."}, {"label": "MCP, ACP + subagentes", "body": "Gestiona servidores MCP de forma conversacional con /mcp-config, expone una sesión a través del Agent Client Protocol (kimi acp) a Zed y JetBrains, y puede despachar subagentes integrados de coder, explore y plan en contextos aislados."}, {"label": "Inicio de sesión o BYOK", "body": "En el primer arranque, /login te permite autorizar vía OAuth (Kimi Code) o introducir tu propia clave de API de Moonshot; la plataforma de Kimi también expone endpoints compatibles con OpenAI y Anthropic."}]}, {"kind": "ul", "items": ["Proveedor: Moonshot AI", "Credencial: clave de API de Moonshot (BYOK), o inicio de sesión OAuth vía Kimi Code", "Licencia: Apache-2.0, código abierto"]}]}, {"id": "why-design", "heading": "Por qué los modelos agénticos K2 y un gran contexto encajan con el diseño", "blocks": [{"kind": "p", "text": "La ventaja de Kimi CLI para diseño proviene de dos propiedades del modelo, pero, como con todo agente, el buen gusto sigue teniendo que aportarse."}, {"kind": "steps", "items": [{"label": "Programación agéntica de largo alcance", "body": "Los modelos Kimi K2 están optimizados para el uso de herramientas y el trabajo de varios pasos, así que el agente puede tomar una referencia y un encargo y de verdad construir, ejecutar y refinar la interfaz en lugar de detenerse en un primer borrador."}, {"label": "Una gran ventana de contexto", "body": "Hasta 256k tokens en las versiones recientes de K2 significa que todo el sistema de diseño, los tokens y muchos estados de referencia caben a la vez, así que el agente reutiliza tus primitivas reales en lugar de inventar estilos puntuales."}, {"label": "Convenciones en AGENTS.md", "body": "Un AGENTS.md (más un servidor MCP como Figma) dirige al agente a tus tokens, componentes y especificaciones reales, para que trabaje contra una marca en lugar de un aspecto por defecto."}]}, {"kind": "image", "src": "/agents/kimi-design/kimi-design-taste-triangle.webp", "alt": "Diagrama que muestra cómo el sistema de diseño, el skill y la imagen de referencia convergen en una buena salida de diseño", "caption": "El buen gusto proviene de tres insumos que tú aportas: un sistema de diseño, un skill e imágenes de referencia reales."}, {"kind": "p", "text": "La lección es la misma que enseña cada agente: Kimi CLI no tiene buen gusto por defecto. Produce buen diseño cuando le das restricciones: un sistema de diseño, un skill estético y referencias concretas. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan (más abajo, con más detalle)."}]}, {"id": "setup", "heading": "Configura Kimi CLI para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta un Kimi CLI capaz de construir y verificar interfaces."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Kimi CLI (uses uv; Python 3.12–3.14, 3.13 recommended)\ncurl -LsSf https://code.kimi.com/install.sh | bash\n# or, if you already have uv:\nuv tool install --python 3.13 kimi-cli\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\nkimi              # then run /login: OAuth via Kimi Code, or paste a Moonshot API key\n\n# 3. Generate project context\n/init             # scaffolds an AGENTS.md for this project\n\n# 4. Wire an MCP server (optional, e.g. Figma for design handoff)\n/mcp-config       # add, edit, and authenticate MCP servers conversationally"}, {"kind": "image", "src": "/agents/kimi-design/kimi-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: instalar, autenticarse, configurar AGENTS.md, añadir un skill, verificar", "caption": "La secuencia de configuración: instalar → autenticarse → configurar AGENTS.md → añadir un skill → habilitar la verificación en el navegador."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Pon tus tokens, primitivas y convenciones en AGENTS.md y dirige a Kimi hacia ellos, para que la salida coincida con una marca en lugar de recurrir a un aspecto genérico."}, {"label": "Añade verificación en el navegador", "body": "Conecta un MCP de Playwright o de navegador para que Kimi renderice en un navegador real y compruebe su salida en distintos puntos de quiebre, en lugar de limitarse a confirmar que la compilación pasa."}]}]}, {"id": "screenshot-workflow", "heading": "El flujo de trabajo de referencia a interfaz", "blocks": [{"kind": "p", "text": "El bucle de diseño de mayor impacto con Kimi CLI es convertir material de referencia en una interfaz funcional y adaptable e iterar hasta que coincida, alimentando al agente con tus referencias y haciendo que compare su salida renderizada con ellas en un navegador real."}, {"kind": "ol", "items": ["Parte de las referencias más claras que tengas, e incluye varios estados (escritorio y móvil, hover, vacío, cargando), no solo una captura principal.", "Sé específico en el prompt; los prompts vagos producen interfaces genéricas incluso con un agente potente.", "Mantén tu sistema de diseño y convenciones en AGENTS.md, e indícale a Kimi dónde viven los tokens y las primitivas canónicas.", "Ejecuta un servidor de desarrollo y haz que Kimi renderice en un navegador real, redimensionando a los puntos de quiebre para comprobar el resultado.", "Itera haciendo que Kimi compare su implementación con las referencias, no que se limite a confirmar que compila."]}, {"kind": "p", "text": "Dirige a Kimi a tus referencias y al servidor de desarrollo, y luego da restricciones concretas:"}, {"kind": "code", "lang": "bash", "code": "kimi\n# in the prompt:\n> Implement the design in ./references (reference-desktop.png,\n  reference-mobile.png) using React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from AGENTS.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Run the dev server, render it in the browser, and iterate until it\n  matches the references across breakpoints."}, {"kind": "p", "text": "Mantén los prompts pequeños y enfocados, confirma las buenas iteraciones y revierte las malas (avisándole a Kimi cuando reviertas), para que cada pasada se construya sobre una base limpia. Kimi CLI también puede tomar una breve grabación de pantalla o un clip de demostración cuando un flujo es difícil de describir con palabras."}]}, {"id": "extend", "heading": "AGENTS.md, MCP y subagentes", "blocks": [{"kind": "p", "text": "Tres puntos de extensión hacen que Kimi CLI sea práctico para trabajo de diseño sostenido, y los tres encajan limpiamente en un flujo de trabajo de diseño abierto."}, {"kind": "steps", "items": [{"label": "Contexto de AGENTS.md", "body": "Las reglas del proyecto viven en un AGENTS.md en la raíz del repositorio. Es el hogar duradero de tus convenciones de diseño, leído en cada ejecución, y es el mismo formato portátil que usan otros agentes."}, {"label": "Servidores MCP", "body": "Añade servidores MCP de forma conversacional con /mcp-config: la forma portátil de incorporar contexto de diseño y herramientas externas, sobre todo el servidor MCP de Figma, que funcionan entre agentes, no solo en Kimi."}, {"label": "Subagentes y el marketplace de plugins", "body": "Despacha subagentes integrados de coder, explore y plan en contextos aislados, e instala skills, servidores MCP y fuentes de datos desde el marketplace o cualquier repositorio de GitHub para reunir referencias y ejecutar el bucle de verificación."}]}, {"kind": "p", "text": "Estas son capacidades portátiles y multiagente, exactamente el tipo de cosas que Open Design está diseñado para orquestar, en lugar de recrearlas en cada proyecto."}]}, {"id": "vs", "heading": "Kimi CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño: cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Ideal para"], "rows": [["Kimi CLI", "Modelos agénticos Kimi K2 ajustados para programación de largo alcance y uso de herramientas, con un gran contexto; de código abierto y BYOK", "Construcciones de varios pasos y mantener todo un sistema de diseño en contexto de forma asequible"], ["Codex", "Gran pulido visual con un skill de frontend; compilaciones asíncronas en sandbox", "Compilaciones asíncronas delegadas y reglas portátiles de AGENTS.md"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de interfaz ajustado de iterar y observar dentro de un IDE"], ["Gemini CLI", "Sólida comprensión de imágenes multimodal y un contexto de 1M de tokens; plan gratuito", "Trabajo con muchas capturas de pantalla y contexto muy grande"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el buen gusto proviene de las personas: todos recurren por defecto a una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver, y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Obstáculos y cómo evitar el aspecto de «IA descuidada»", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por IA es que parece genérico: degradados suaves, paneles flotantes, esquinas redondeadas demasiado grandes, sombras dramáticas, un aire de Inter y morado que «grita que esto lo hizo una IA». Otros problemas reportados incluyen maquetaciones móviles rotas e instrucciones que se filtran en el texto de la interfaz. Ninguno de ellos es exclusivo de Kimi CLI; son lo que ocurre cuando cualquier agente se ejecuta sin un contexto de diseño curado."}, {"kind": "steps", "items": [{"label": "Añade un skill estético", "body": "Un skill de diseño curado obliga al agente a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Verifica en un navegador real", "body": "Haz que Kimi renderice y autoverifique en distintos puntos de quiebre para que las maquetaciones no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las capturas de referencia son la mayor palanca individual sobre la calidad de la salida."}, {"label": "Codifica reglas en AGENTS.md", "body": "Pon reglas de estilo como «sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca» donde el agente las lee en cada ejecución."}]}, {"kind": "p", "text": "Fíjate en que toda mitigación consiste en dar al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es la tarea pesada que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con Kimi CLI dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño de código abierto que el flujo de trabajo anterior no deja de pedir. Trata a Kimi CLI como un adaptador de primera categoría y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de renderizado estructurada y una interfaz de escritorio local, de modo que el contexto de diseño que hace bueno a Kimi está ahí desde la primera ejecución, no ensamblado a mano cada vez. Ambos son de código abierto y local-first, lo que hace que la combinación encaje de forma natural."}, {"kind": "ol", "items": ["Instala Open Design y selecciona Kimi CLI como tu agente.", "Autentícate con tu clave de API de Moonshot (BYOK): las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y un skill, y luego genera presentaciones, prototipos y páginas de aterrizaje con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente Kimi CLI, la misma clave, más un flujo de trabajo de diseño real, portátil y de código abierto a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Puede Kimi CLI hacer realmente trabajo de diseño?", "text": "Sí: con un skill estético, un sistema de diseño e imágenes de referencia reales en contexto, Kimi CLI produce interfaces adaptables de calidad de producción, y sus modelos agénticos Kimi K2 pueden renderizar y verificar la salida frente a las referencias. Sin ese contexto tiende a recurrir a un aspecto genérico, que es la brecha que Open Design rellena."}, {"name": "¿Tengo que pagar para diseñar con Kimi CLI?", "text": "Traes tus propias credenciales: autoriza vía el inicio de sesión OAuth de Kimi Code o pega una clave de API de Moonshot (BYOK), facturada por la plataforma de Moonshot. Open Design nunca actúa de intermediario con tus credenciales en ningún caso."}, {"name": "¿Qué hace bueno a Kimi CLI para diseño en concreto?", "text": "Dos cosas: los modelos Kimi K2 están ajustados para programación agéntica de largo alcance y uso de herramientas, así que el agente puede construir y refinar hasta un resultado funcional, y la ventana de contexto alcanza hasta 256k tokens, suficiente para mantener un sistema de diseño y un conjunto de referencias enteros a la vez. Ambas ayudan, pero el buen gusto sigue proviniendo del sistema de diseño, el skill y las referencias que tú aportas."}, {"name": "¿Kimi CLI o Claude Code para diseño de frontend?", "text": "Ambos son potentes. Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código; la ventaja de Kimi CLI son sus modelos agénticos Kimi K2 y un gran contexto con la economía de BYOK. Muchos equipos usan ambos: Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto Kimi CLI con Figma?", "text": "Ejecuta /mcp-config dentro de Kimi CLI para añadir y autenticar el servidor MCP de Figma. Kimi puede entonces extraer contexto de diseño real —componentes, variables, datos de maquetación— para que el código generado coincida con la fuente en lugar de aproximarla."}, {"name": "¿Open Design está afiliado a Moonshot AI?", "text": "No. Kimi CLI es un producto de Moonshot AI; Open Design es un proyecto independiente de código abierto que lo admite como adaptador de primera categoría. Kimi es una marca comercial de Moonshot AI."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí: Open Design es local-first y Apache-2.0. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tus credenciales de Moonshot las usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con Kimi CLI, a la manera abierta.", "ctaBody": "Trae tu propia clave de API de Moonshot, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente que ya usas.", "ctaActions": [{"label": "Usa Kimi CLI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
      'deepseek': {
        ...en['deepseek']!,
        title: "DeepSeek TUI para diseño — Open Design",
        description: "Cómo se usa un agente de programación de terminal impulsado por DeepSeek para diseño de interfaces y web —sus potentes modelos de programación, un contexto de 1M de tokens, su eficiencia de costes, los archivos de contexto y MCP— y cómo Open Design convierte la DeepSeek TUI en un agente de diseño local-first y de código abierto.",
        breadcrumb: "DeepSeek TUI",
        label: "Agente · DeepSeek TUI",
        heading: "DeepSeek TUI para diseño.",
        lead: "DeepSeek TUI es un agente de programación de terminal impulsado por los modelos de DeepSeek. Sus potentes modelos de programación con buena eficiencia de costes y su contexto de 1M de tokens pueden mantener un sistema de diseño y una base de código enteros a la vez, lo que lo convierte en una verdadera herramienta de diseño, una vez que le das referencias, convenciones y un bucle de verificación. Open Design lo integra en un flujo de trabajo de diseño de código abierto: tu clave de API de DeepSeek, tus archivos, local-first.",
        rich: {"heroCtaLead": "Open Design convierte la DeepSeek TUI en un agente de diseño local-first y de código abierto: tu clave de API de DeepSeek, tus archivos y una biblioteca curada de skills y sistemas de diseño a su alrededor.", "heroCtaActions": [{"label": "Usa DeepSeek TUI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["DeepSeek TUI es un agente de programación de IA basado en terminal impulsado por los modelos de DeepSeek. Dos cosas lo hacen interesante específicamente para diseño: sus modelos de programación son potentes e inusualmente eficientes en costes, así que puedes iterar de forma agresiva sin estar mirando el contador; y su ventana de contexto alcanza hasta 1M de tokens, lo bastante grande para mantener un sistema de diseño y una base de código enteros a la vez, en lugar de resumirlos. Combinado con las referencias, convenciones y un bucle de verificación adecuados, construye interfaces reales y adaptables. Esta es una guía práctica y de extremo a extremo para usar un agente de terminal impulsado por DeepSeek en trabajo de interfaces, frontend y sistemas de diseño, y para integrarlo en un flujo de trabajo de diseño estructurado con Open Design.", "Cubre qué es realmente la DeepSeek TUI, por qué los potentes modelos de programación, un enorme contexto y el bajo coste encajan con el diseño, cómo configurarlo desde cero, el bucle de referencia a interfaz, cómo lo amplían los archivos de contexto y MCP, cómo se compara con Codex, Claude Code, Cursor y Gemini CLI, los obstáculos que hacen que la salida de la IA parezca genérica, y cómo Open Design cierra la brecha como una capa de diseño abierta y local-first: una combinación natural, ya que ambos son abiertos y se ejecutan en tu propia máquina."], "heroImage": {"src": "/agents/deepseek-design/deepseek-design-hero.webp", "alt": "Bucle de retroalimentación de diseño de DeepSeek TUI: un agente de terminal leyendo referencias y convenciones, un navegador renderizando la interfaz y un espacio de trabajo, con una flecha de retroalimentación que vuelve al inicio", "caption": "El bucle central: DeepSeek TUI lee tus referencias y convenciones en la terminal, construye y verifica la interfaz en un navegador real e itera frente a ellas, con todo un sistema de diseño en contexto."}, "tocLabel": "En esta página", "toc": [{"id": "what-is-deepseek", "label": "Qué es realmente DeepSeek TUI"}, {"id": "why-design", "label": "Por qué los potentes modelos de programación + un enorme contexto encajan con el diseño"}, {"id": "setup", "label": "Configura DeepSeek TUI para diseño (desde cero)"}, {"id": "screenshot-workflow", "label": "El flujo de trabajo de referencia a interfaz"}, {"id": "extend", "label": "Archivos de contexto, MCP y herramientas"}, {"id": "vs", "label": "DeepSeek TUI vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Obstáculos y el aspecto de «IA descuidada»"}, {"id": "open-design", "label": "Diseñar con DeepSeek TUI en Open Design"}, {"id": "faq", "label": "Preguntas frecuentes"}], "sections": [{"id": "what-is-deepseek", "heading": "Qué es realmente DeepSeek TUI", "blocks": [{"kind": "p", "text": "Una DeepSeek TUI es un agente de IA de terminal controlado por teclado que ejecuta los modelos de DeepSeek. Lee tu repositorio, edita archivos, ejecuta comandos de shell, gestiona git y puede buscar en la web, planificando y verificando el trabajo a partir de tareas en lenguaje natural en lugar de limitarse a completar líneas. DeepSeek en sí es el proveedor de modelos: una API compatible con OpenAI (también expone un endpoint en formato Anthropic), así que una amplia gama de agentes de terminal de la comunidad puede apuntar a DeepSeek estableciendo una URL base y una clave. Varias TUI de código abierto incluyen DeepSeek como proveedor de primera categoría."}, {"kind": "p", "text": "Para el trabajo de diseño, destacan tres propiedades. Los modelos de programación de DeepSeek son potentes, así que el agente razona sobre la maquetación, la estructura y la jerarquía de componentes a partir de una descripción clara. Su ventana de contexto alcanza hasta 1M de tokens, lo bastante grande para mantener tu sistema de diseño y biblioteca de componentes enteros a la vez. Y su precio por token es muy bajo, con caché de contexto por prefijo encima, así que iterar sobre un diseño cuesta poco."}, {"kind": "steps", "items": [{"label": "Archivos de contexto", "body": "Los agentes de terminal leen un archivo de contexto del proyecto (un archivo al estilo AGENTS.md, o la propia convención del agente) en busca de reglas persistentes, el lugar natural para codificar tus convenciones de diseño, tokens y listas de comprobación de revisión."}, {"label": "Herramientas + MCP", "body": "La mayoría de las DeepSeek TUI incluyen herramientas de archivos, shell, git y web, y admiten servidores MCP para añadir contexto externo, como un archivo de Figma en vivo: la API de DeepSeek admite la llamada a herramientas, de la que dependen estos agentes."}, {"label": "Trae tu propia clave", "body": "Te autenticas con una clave de API de DeepSeek de la plataforma de DeepSeek. Como la API es compatible con OpenAI, apuntar un agente a DeepSeek suele ser cuestión de dos líneas: la URL base y la clave."}]}, {"kind": "ul", "items": ["Proveedor: DeepSeek (proveedor de modelo y API)", "Credencial: clave de API de DeepSeek (BYOK) de la plataforma de DeepSeek", "Modelos: deepseek-v4-flash y deepseek-v4-pro (solo texto; sin entrada de imágenes nativa)"]}]}, {"id": "why-design", "heading": "Por qué los potentes modelos de programación y un enorme contexto encajan con el diseño", "blocks": [{"kind": "p", "text": "La ventaja de DeepSeek TUI para diseño proviene del modelo y su economía, pero, como con todo agente, el buen gusto sigue teniendo que aportarse."}, {"kind": "steps", "items": [{"label": "Programación potente y eficiente en costes", "body": "Los modelos de programación de DeepSeek son capaces y económicos, así que el agente razona bien sobre la maquetación y la estructura, y puedes iterar muchas veces sin que el coste sea la limitación."}, {"label": "Una ventana de contexto de 1M de tokens", "body": "Un gran contexto significa que todo el sistema de diseño, los tokens y muchos estados de referencia caben a la vez, así que el agente reutiliza tus primitivas reales en lugar de inventar estilos puntuales, y la caché de contexto mantiene baratos los prompts repetidos."}, {"label": "Convenciones en un archivo de contexto", "body": "Un archivo de contexto del proyecto (más el servidor MCP de Figma) dirige al agente a tus tokens, componentes y especificaciones reales, para que trabaje contra una marca en lugar de un aspecto por defecto."}]}, {"kind": "image", "src": "/agents/deepseek-design/deepseek-design-taste-triangle.webp", "alt": "Diagrama que muestra cómo el sistema de diseño, el skill y la referencia convergen en una buena salida de diseño", "caption": "El buen gusto proviene de tres insumos que tú aportas: un sistema de diseño, un skill y referencias reales."}, {"kind": "p", "text": "La lección es la misma que enseña cada agente: DeepSeek TUI no tiene buen gusto por defecto. Produce buen diseño cuando le das restricciones: un sistema de diseño, un skill estético y referencias concretas. Open Design empaqueta exactamente esos insumos, y por eso ambos encajan (más abajo, con más detalle)."}]}, {"id": "setup", "heading": "Configura DeepSeek TUI para trabajo de diseño, desde cero", "blocks": [{"kind": "p", "text": "Este es el camino completo desde una máquina limpia hasta una DeepSeek TUI capaz de construir y verificar interfaces. Los nombres exactos de instalación y de comandos varían según el agente de terminal que elijas, así que los pasos siguientes se mantienen en el nivel que es válido para todos ellos."}, {"kind": "code", "lang": "bash", "code": "# 1. Get a DeepSeek API key from the DeepSeek platform\n#    https://platform.deepseek.com\nexport DEEPSEEK_API_KEY=sk-...\n\n# 2. Install a DeepSeek-capable terminal agent (follow its README),\n#    then point it at DeepSeek. The API is OpenAI-compatible:\n#      base URL: https://api.deepseek.com\n#      model:    deepseek-v4-flash (or deepseek-v4-pro)\n#    (an Anthropic-format endpoint also exists at /anthropic)\n\n# 3. Start it in your project and generate project context\ncd your-project\n#   create/scaffold a project context file with your design rules\n\n# 4. Wire the Figma MCP server (optional, for design handoff)\n#    add it to the agent's MCP server configuration"}, {"kind": "image", "src": "/agents/deepseek-design/deepseek-design-setup-flow.webp", "alt": "Flujo de configuración de cinco pasos: obtener la clave, instalar el agente, configurar el archivo de contexto, añadir un skill, verificar", "caption": "La secuencia de configuración: obtener una clave → apuntar el agente a DeepSeek → configurar un archivo de contexto → añadir un skill → habilitar la verificación en el navegador."}, {"kind": "steps", "items": [{"label": "Codifica tus reglas de diseño", "body": "Pon tus tokens, primitivas y convenciones en el archivo de contexto del agente y dirígelo hacia ellos, para que la salida coincida con una marca en lugar de recurrir a un aspecto genérico."}, {"label": "Añade verificación en el navegador", "body": "Conecta un MCP de Playwright o de navegador para que el agente renderice en un navegador real y compruebe su salida en distintos puntos de quiebre, en lugar de limitarse a confirmar que la compilación pasa."}]}]}, {"id": "screenshot-workflow", "heading": "El flujo de trabajo de referencia a interfaz", "blocks": [{"kind": "p", "text": "Los modelos de DeepSeek son solo de texto —no leen imágenes de forma nativa—, así que el bucle de diseño de mayor impacto es convertir referencias claras y maquetaciones descritas en una interfaz funcional y adaptable, y luego verificar el resultado en un navegador real en lugar de pedirle al modelo que mire una captura."}, {"kind": "ol", "items": ["Parte de las referencias más claras que tengas, y describe varios estados (escritorio y móvil, hover, vacío, cargando), no solo una captura principal.", "Sé específico en el prompt; los prompts vagos producen interfaces genéricas incluso con un modelo potente. Detalla el espaciado, la jerarquía y los componentes a reutilizar.", "Mantén tu sistema de diseño y convenciones en el archivo de contexto, e indícale al agente dónde viven los tokens y las primitivas canónicas.", "Ejecuta un servidor de desarrollo y haz que el agente renderice en un navegador real, redimensionando a los puntos de quiebre para comprobar el resultado: aquí es donde ocurre la verificación, ya que el modelo no puede ver la imagen en sí.", "Itera haciendo que el agente compare el DOM renderizado y los estilos computados con tu especificación descrita, no que se limite a confirmar que compila."]}, {"kind": "p", "text": "Describe el objetivo con precisión y da restricciones concretas:"}, {"kind": "code", "lang": "bash", "code": "# in the agent's prompt:\n> Implement this design in React + Vite + Tailwind + TypeScript.\n  Layout: two-column dashboard, 240px sidebar, 24px gutters,\n  card grid at 3/2/1 columns for desktop/tablet/mobile.\n  Reuse my existing design-system components and tokens from the\n  context file. Match spacing, layout, and hierarchy; make it responsive.\n  Run the dev server, render it in the browser, and iterate against the\n  spec across breakpoints until it matches."}, {"kind": "p", "text": "Mantén los prompts pequeños y enfocados, confirma las buenas iteraciones y revierte las malas (avisándole al agente cuando reviertas), para que cada pasada se construya sobre una base limpia."}]}, {"id": "extend", "heading": "Archivos de contexto, MCP y herramientas", "blocks": [{"kind": "p", "text": "Tres puntos de extensión hacen que una DeepSeek TUI sea práctica para trabajo de diseño sostenido, y los tres encajan limpiamente en un flujo de trabajo de diseño abierto."}, {"kind": "steps", "items": [{"label": "Archivo de contexto del proyecto", "body": "Las reglas del proyecto viven en un archivo de contexto en la raíz del repositorio (con capas global y de equipo). Es el hogar duradero de tus convenciones de diseño, leído en cada ejecución."}, {"label": "Servidores MCP", "body": "Configura servidores MCP en el agente: la forma portátil de incorporar contexto de diseño y herramientas externas, sobre todo el servidor MCP de Figma, que funcionan entre agentes, no solo en uno. La API de DeepSeek admite la llamada a herramientas de la que dependen estos servidores."}, {"label": "Herramientas integradas", "body": "Las DeepSeek TUI incluyen herramientas de archivos, shell, git y web para que el agente pueda reunir referencias y ejecutar el bucle de verificación sin salir de la terminal."}]}, {"kind": "p", "text": "Estas son capacidades portátiles y multiagente, exactamente el tipo de cosas que Open Design está diseñado para orquestar, en lugar de recrearlas en cada proyecto."}]}, {"id": "vs", "heading": "DeepSeek TUI vs Codex vs Claude Code vs Cursor vs Gemini CLI para diseño", "blocks": [{"kind": "p", "text": "No hay un único ganador para el trabajo de diseño: cada agente tiene una fortaleza distinta, y los equipos con experiencia los combinan. Un resumen justo:"}, {"kind": "table", "columns": ["Agente", "Fortaleza de diseño", "Ideal para"], "rows": [["DeepSeek TUI", "Modelos de programación potentes y muy eficientes en costes con pesos abiertos y un contexto de 1M de tokens; solo texto (sin visión nativa)", "Iteración de alto volumen con presupuesto ajustado y mantener todo un sistema de diseño en contexto"], ["Codex", "Gran pulido visual con un skill de frontend; compilaciones asíncronas en sandbox", "Compilaciones asíncronas delegadas y reglas portátiles de AGENTS.md"], ["Claude Code", "Decisiones de diseño específicas (hex, espaciado, tipografía) y UX consciente de la base de código", "Razonamiento de frontend y refactorizaciones de gran contexto"], ["Cursor", "Bucle visual de construir y ver con vista previa en vivo y ediciones en línea", "Trabajo de interfaz ajustado de iterar y observar dentro de un IDE"], ["Gemini CLI", "Comprensión de imágenes multimodal nativa y un contexto de 1M de tokens; de código abierto con un plan gratuito", "Trabajo con muchas capturas de pantalla donde el agente lee las referencias directamente"]]}, {"kind": "p", "text": "El veredicto recurrente de la comunidad es que el buen gusto proviene de las personas: todos recurren por defecto a una estética genérica sin skills, referencias y restricciones. Ese es el verdadero problema a resolver, y tiene forma de herramienta de diseño, no de modelo."}]}, {"id": "pitfalls", "heading": "Obstáculos y cómo evitar el aspecto de «IA descuidada»", "blocks": [{"kind": "p", "text": "La queja más común sobre el diseño generado por IA es que parece genérico: degradados suaves, paneles flotantes, esquinas redondeadas demasiado grandes, sombras dramáticas, un aire de Inter y morado que «grita que esto lo hizo una IA». Otros problemas reportados incluyen maquetaciones móviles rotas e instrucciones que se filtran en el texto de la interfaz. Ninguno de ellos es exclusivo de DeepSeek TUI; son lo que ocurre cuando cualquier agente se ejecuta sin un contexto de diseño curado. Como DeepSeek es solo de texto, es especialmente importante verificar en un navegador real en lugar de confiar en que el modelo «mire» el resultado."}, {"kind": "steps", "items": [{"label": "Añade un skill estético", "body": "Un skill de diseño curado obliga al agente a comprometerse con una dirección real en lugar del aspecto por defecto."}, {"label": "Verifica en un navegador real", "body": "Renderiza y autoverifica en distintos puntos de quiebre con una herramienta de navegador —esencial aquí, ya que el modelo no puede leer una captura por sí mismo— para que las maquetaciones no se rompan en silencio en móvil."}, {"label": "Aporta tokens y referencias", "body": "Los tokens de diseño reales y las referencias concretas y descritas son la mayor palanca individual sobre la calidad de la salida."}, {"label": "Codifica reglas en el archivo de contexto", "body": "Pon reglas de estilo como «sin tarjetas hero, máximo dos tipografías, jerarquía centrada en la marca» donde el agente las lee en cada ejecución."}]}, {"kind": "p", "text": "Fíjate en que toda mitigación consiste en dar al agente un contexto de diseño curado. Mantener ese contexto a mano, proyecto a proyecto, es la tarea pesada que Open Design elimina."}]}, {"id": "open-design", "heading": "Diseñar con DeepSeek TUI dentro de Open Design", "blocks": [{"kind": "p", "text": "Open Design es la capa de diseño de código abierto que el flujo de trabajo anterior no deja de pedir. Trata al agente DeepSeek como un adaptador de primera categoría y lo envuelve en una biblioteca curada de skills y sistemas de diseño, una canalización de renderizado estructurada y una interfaz de escritorio local, de modo que el contexto de diseño que hace bueno a DeepSeek está ahí desde la primera ejecución, no ensamblado a mano cada vez. Ambos son abiertos y local-first, lo que hace que la combinación encaje de forma natural."}, {"kind": "ol", "items": ["Instala Open Design y selecciona la DeepSeek TUI como tu agente.", "Autentícate con tu propia clave de API de DeepSeek (BYOK): las credenciales permanecen en tu máquina y nunca pasan por nuestros servidores.", "Elige un sistema de diseño y un skill, y luego genera presentaciones, prototipos y páginas de aterrizaje con un gusto consistente.", "Cada artefacto y archivo DESIGN.md vive en tu propio repositorio, no en una nube alojada."]}, {"kind": "p", "text": "El mismo agente DeepSeek, la misma clave, más un flujo de trabajo de diseño real, portátil y de código abierto a su alrededor. Es local-first y Apache-2.0, así que nada de tu trabajo ni de tus credenciales sale de tu máquina."}]}], "faqTitle": "Preguntas frecuentes", "faq": [{"name": "¿Puede DeepSeek TUI hacer realmente trabajo de diseño?", "text": "Sí: con un skill estético, un sistema de diseño y referencias concretas en contexto, un agente de terminal impulsado por DeepSeek produce interfaces adaptables de calidad de producción, y verificas la salida en un navegador real. Los modelos de DeepSeek son solo de texto, así que el bucle de verificación sustituye a la lectura nativa de imágenes. Sin ese contexto tiende a recurrir a un aspecto genérico, que es la brecha que Open Design rellena."}, {"name": "¿Cuánto cuesta diseñar con DeepSeek TUI?", "text": "Poco: la API de DeepSeek está entre las más baratas por token, y la caché de contexto por prefijo reduce aún más el coste de los prompts repetidos, así que puedes iterar de forma agresiva. Traes tu propia clave de API de DeepSeek (BYOK); Open Design nunca actúa de intermediario con tus credenciales."}, {"name": "¿Qué hace bueno a DeepSeek para diseño en concreto?", "text": "Modelos de programación potentes y eficientes en costes, pesos abiertos y un contexto de 1M de tokens que mantiene un sistema de diseño y un conjunto de referencias enteros a la vez. DeepSeek es solo de texto —no lee imágenes de forma nativa—, así que el buen gusto sigue proviniendo del sistema de diseño, el skill y las referencias descritas que tú aportas, verificadas en un navegador."}, {"name": "¿DeepSeek TUI o Claude Code para diseño de frontend?", "text": "Ambos son potentes. Claude Code es conocido por decisiones de diseño específicas y conscientes de la base de código; la ventaja de DeepSeek TUI son los pesos abiertos, el coste muy bajo y un enorme contexto para iteración de alto volumen. Muchos equipos usan ambos: Open Design te permite cambiar de agente sin cambiar tu flujo de trabajo de diseño."}, {"name": "¿Cómo conecto DeepSeek TUI con Figma?", "text": "Añade el servidor MCP de Figma en la configuración de MCP de tu agente de terminal. El agente puede entonces extraer contexto de diseño real —componentes, variables, datos de maquetación— para que el código generado coincida con la fuente en lugar de aproximarla. La API de DeepSeek admite la llamada a herramientas de la que depende MCP."}, {"name": "¿Open Design está afiliado a DeepSeek?", "text": "No. DeepSeek es el proveedor de modelo y API; Open Design es un proyecto independiente de código abierto que admite agentes de terminal impulsados por DeepSeek como adaptador de primera categoría. DeepSeek es una marca comercial de DeepSeek."}, {"name": "¿Están seguros mis archivos y credenciales?", "text": "Sí: Open Design es local-first y Apache-2.0. Tus archivos, artefactos y DESIGN.md permanecen en tu propio repositorio, y tu clave de API de DeepSeek la usa directamente tu agente, sin enrutarse nunca a través de los servidores de Open Design."}], "ctaTitle": "Diseña con DeepSeek TUI, a la manera abierta.", "ctaBody": "Trae tu propia clave de API de DeepSeek, mantén cada archivo en local y obtén una biblioteca de diseño curada alrededor del agente que ya usas.", "ctaActions": [{"label": "Usa DeepSeek TUI dentro de Open Design", "href": "/quickstart/", "variant": "primary"}, {"label": "Dale una estrella en GitHub", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Descarga la aplicación de escritorio", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Ver todos los agentes compatibles"},
      },
    },
    'tr': {
      'claude-code': {
        ...en['claude-code']!,
        title: "Tasarım için Claude Code — Open Design",
        description: "Tasarımcılar Claude Code'u UI ve web tasarımı için nasıl kullanır ve Open Design onu nasıl gerçek bir tasarım ajanına dönüştürür — yerel öncelikli, BYOK, özenle seçilmiş skill ve tasarım sistemi kütüphanesiyle.",
        breadcrumb: "Claude Code",
        label: "Ajan · Claude Code",
        heading: "Tasarım için Claude Code.",
        lead: "Claude Code, Anthropic'in terminal kodlama ajanıdır. İnsanlar onu zaten UI'lar, tasarım sistemleri ve açılış sayfaları oluşturmak için kullanıyor. Open Design onu gerçek bir tasarım iş akışına bağlar — Anthropic anahtarınızı veya Claude aboneliğinizi getirin, her dosyayı yerel tutun.",
        rich: {"heroCtaLead": "Open Design, Claude Code'u yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — Anthropic anahtarınız veya Claude aboneliğiniz, dosyalarınız ve etrafında özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "Claude Code'u Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Claude Code, frontend konusunda en iyi zevke sahip kodlama ajanı olarak yaygın biçimde kabul edilir — arayüzler üzerinde alışılmadık bir kesinlikle akıl yürütür, tam hex değerlerini, boşlukları ve tipografi ölçeklerini adlandırır ve büyük bir kod tabanı boyunca UI'ı, bağlamı kaybetmeden yeniden düzenler. Ama kutudan çıktığı haliyle, ona bir tasarım sistemi, skill'ler ve gerçek referanslar vermediğiniz sürece yine de jenerik bir görünüme kayar. Bu, Claude Code'u UI, frontend ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir iş akışına bağlamaya dair pratik, uçtan uca bir rehberdir.", "Claude Code'un gerçekte ne olduğunu, frontend'de neden güçlü olduğunu, sıfırdan nasıl kurulacağını, CLAUDE.md ve Skills iş akışını, resmi Figma gidiş-dönüşünü, Codex ve Cursor ile nasıl karşılaştırıldığını, AI çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak bu boşluğu nasıl kapattığını ele alır."], "heroImage": {"src": "/agents/claude-code-design/claude-code-design-hero.webp", "alt": "Claude Code tasarım geri bildirim döngüsü: spesifik tasarım kararları veren terminal ajanı, UI'ı işleyen bir tarayıcı ve bir çalışma alanı, geri döngü oluşturan bir geri bildirim okuyla", "caption": "Çekirdek döngü: Claude Code terminalde spesifik UI kararlarını akıl yürüterek belirler, bunları gerçek bir tarayıcıda işler ve doğrular, referanslarınıza karşı yakınsar."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-claude-code", "label": "Claude Code gerçekte nedir"}, {"id": "why-design", "label": "Claude Code tasarımda neden iyi"}, {"id": "setup", "label": "Claude Code'u tasarım için kurun (sıfırdan)"}, {"id": "skills-workflow", "label": "CLAUDE.md ve Skills iş akışı"}, {"id": "figma", "label": "Claude Code + Figma gidiş-dönüşü"}, {"id": "vs", "label": "Claude Code, Codex ve Cursor karşılaştırması"}, {"id": "pitfalls", "label": "Tuzaklar ve “AI çöplüğü” görünümü"}, {"id": "open-design", "label": "Open Design içinde Claude Code ile tasarım"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-claude-code", "heading": "Claude Code gerçekte nedir", "blocks": [{"kind": "p", "text": "Claude Code, Anthropic'in ajansal kodlama aracıdır. Kod tabanınızı okur, dosyaları düzenler, komutları çalıştırır ve geliştirme araçlarınızla entegre olur — yalnızca satırları otomatik tamamlamak yerine doğal dildeki görevlerden işi planlar, yazar ve doğrular."}, {"kind": "p", "text": "Hepsi aynı motoru paylaşan birkaç yüzey üzerinden sunulur: bir terminal CLI'si, VS Code, Cursor ve JetBrains için IDE eklentileri, görsel diff incelemesi olan bir masaüstü uygulaması ve uzun süren görevler için bir web deneyimi. CLAUDE.md dosyalarınız, ayarlarınız ve MCP sunucularınız hepsinde geçerlidir."}, {"kind": "steps", "items": [{"label": "Talimat dosyası", "body": "Claude Code, her oturumun başında proje kökünüzdeki bir CLAUDE.md dosyasını okur — tasarım kurallarınızı, token'larınızı ve inceleme kontrol listelerinizi kodlamak için doğal yer."}, {"label": "Skills", "body": "Agent Skills, Claude'un talep üzerine yüklediği yinelenebilir talimatları, betikleri ve kaynakları paketler; buna zevk için Anthropic'in resmi Frontend Design skill'i de dahildir."}, {"label": "Plan ve alt ajanlar", "body": "Eylemden önce plan yapabilir ve bir görevin farklı parçaları üzerinde paralel çalışan alt ajanlar başlatabilir; bu da büyük UI yeniden düzenlemelerini tutarlı tutar."}]}, {"kind": "ul", "items": ["Sağlayıcı: Anthropic", "Kimlik bilgisi: Anthropic API anahtarı (BYOK, Console üzerinden) veya bir Claude aboneliği (Pro / Max)", "Yüzeyler: terminal CLI, VS Code / Cursor / JetBrains eklentileri, masaüstü uygulaması, web"]}]}, {"id": "why-design", "heading": "Claude Code tasarımda neden iyi", "blocks": [{"kind": "p", "text": "Kodlama ajanları arasında Claude Code, frontend çalışmasında zevk konusunda bir üne sahiptir. Birkaç şey bunu açıklar."}, {"kind": "steps", "items": [{"label": "Belirsiz değil, spesifik kararlar", "body": "Claude Code, el sallayarak geçiştirmek yerine somut seçimlere bağlanma eğilimindedir — tam hex değerleri, boşluk ölçekleri, tipografi rampaları ve bileşen hiyerarşisi — gerçek bir arayüzü bir yer tutucudan ayıran şey de budur."}, {"label": "Kod tabanının farkında akıl yürütme", "body": "Geniş bir çalışma bağlamıyla, UI'ı bir kerede birçok dosya boyunca yeniden düzenler; tek seferlik stiller icat etmek yerine mevcut bileşenlerinizi ve token'larınızı yeniden kullanır."}, {"label": "Resmi bir frontend skill'i", "body": "Anthropic, Claude'un önce bir tasarım yönü yazmasını sağlayan ve jenerik sistem yazı tiplerinden ve tahmin edilebilir mor degradelerden bilinçli olarak uzaklaşan bir Frontend Design skill'i sunar."}]}, {"kind": "image", "src": "/agents/claude-code-design/claude-code-design-taste-triangle.webp", "alt": "Tasarım sistemi, skill ve referans görselin iyi tasarım çıktısına yakınsadığını gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir skill ve gerçek referans görseller."}, {"kind": "p", "text": "Çıkarılan ders, Anthropic'in kendi modelleri hakkında söylediğiyle aynıdır: Claude varsayılan olarak zevke sahip değildir — kendi haline bırakılırsa web tasarımının istatistiksel merkezine yakınsar (Inter, mor degradeler, yumuşak gölgeler). Ona kısıtlar verdiğinizde iyi tasarım üretir. Open Design tam olarak bu girdileri paketler; ikisinin neden birbirine uyduğunun nedeni de budur (daha fazlası aşağıda)."}]}, {"id": "setup", "heading": "Claude Code'u tasarım çalışması için sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden, UI oluşturabilen ve doğrulayabilen bir Claude Code'a giden tam yol şudur."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Claude Code (native install, recommended)\ncurl -fsSL https://claude.ai/install.sh | bash\n# or: brew install --cask claude-code\n# Windows PowerShell: irm https://claude.ai/install.ps1 | iex\n\n# 2. Start it in your project and sign in on first run\ncd your-project\nclaude            # sign in with your Claude subscription or API key\n\n# 3. Generate project context\n/init             # creates a CLAUDE.md for this project\n\n# 4. Add the official Frontend Design skill\nclaude plugin install frontend-design@claude-plugins-official\n\n# 5. Wire the Figma MCP server (optional, for design handoff)\nclaude plugin install figma@claude-plugins-official"}, {"kind": "image", "src": "/agents/claude-code-design/claude-code-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: kur, kimlik doğrula, CLAUDE.md yapılandır, skill ekle, doğrula", "caption": "Kurulum sırası: kur → kimlik doğrula → CLAUDE.md yapılandır → Frontend Design skill'ini ekle → tarayıcı doğrulamasını etkinleştir."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı CLAUDE.md içine koyun ve Claude'u bunlara yönlendirin; böylece çıktı jenerik bir görünüme dönmek yerine bir markayla eşleşsin."}, {"label": "Tarayıcı doğrulaması ekleyin", "body": "Bir Playwright veya Chrome MCP bağlayın, böylece Claude yalnızca derlemenin geçtiğini onaylamak yerine gerçek bir tarayıcıda işlesin ve çıktısını kırılma noktaları boyunca kontrol etsin."}]}]}, {"id": "skills-workflow", "heading": "CLAUDE.md ve Skills iş akışı", "blocks": [{"kind": "p", "text": "Claude Code ile en yüksek kaldıraçlı tasarım döngüsü, ona gerçek referansları artı tasarım bağlamınızı beslemek ve ardından UI eşleşene kadar yinelemektir — CLAUDE.md ve Skills kısıtları taşır, böylece bunları her komutta yeniden açıklamazsınız."}, {"kind": "ol", "items": ["Sahip olduğunuz en net görsel referanslardan başlayın — ve yalnızca tek bir hero görseli değil, birden çok durumu (masaüstü ve mobil, hover, boş, yükleniyor) dahil edin.", "Komutta spesifik olun; belirsiz komutlar, güçlü bir ajanla bile jenerik UI üretir.", "Tasarım sisteminizi ve kurallarınızı CLAUDE.md içinde tutun ve Claude'a token'ların ve kanonik ilkellerin nerede yaşadığını söyleyin.", "Frontend Design skill'ini ekleyin, böylece Claude kod yazmadan önce gerçek bir estetik yöne bağlansın.", "Tarayıcı doğrulamasını bağlayın, böylece Claude işlesin, kırılma noktalarına yeniden boyutlandırsın ve referanslarla karşılaştırsın — yalnızca derlendiğini onaylamasın."]}, {"kind": "p", "text": "Oturuma bir referans görseli bırakın ve somut kısıtlarla komut verin:"}, {"kind": "code", "lang": "bash", "code": "claude \"Implement reference-desktop.png and reference-mobile.png in\n  React + Vite + Tailwind + TypeScript.\n  Reuse the design-system components and tokens described in CLAUDE.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Render it in the browser, verify it matches the references across\n  breakpoints, and iterate until it does.\""}, {"kind": "p", "text": "Yanında bir dev sunucusu çalıştırın, komutları küçük ve odaklı tutun, iyi yinelemeleri commit edin / kötü olanları geri alın (geri aldığınızda Claude'a söyleyin), böylece her geçiş temiz bir temel üzerine inşa edilsin. Büyük yeniden düzenlemeler için plan modunu kullanın, böylece herhangi bir dosya değişikliğinden önce yaklaşımı inceleyebilirsiniz."}]}, {"id": "figma", "heading": "Claude Code + Figma: tasarım ↔ kod gidiş-dönüşü", "blocks": [{"kind": "p", "text": "Şubat 2026'da Anthropic ve Figma, Figma MCP sunucusu aracılığıyla birinci sınıf, çift yönlü bir entegrasyon yayınladı. Her iki yönde de çalışır."}, {"kind": "steps", "items": [{"label": "Tasarım → Kod", "body": "Figma'da bir frame seçin veya Claude Code'a bir bağlantı yapıştırın, tasarım bağlamını çekin ve ondan mevcut bileşen kütüphanenizi kullanarak tasarımı uygulamasını isteyin. Code Connect, çıktıyı gerçek bileşenlerinizle hizalı tutar."}, {"label": "Kod → Tasarım", "body": "Bir özelliği tarayıcıda oluşturup önizleyin, ardından çalışan UI'ı düzenlenebilir Figma katmanları olarak yakalamak için “Send this to Figma” deyin — tüm ekran veya seçili bir öğe."}]}, {"kind": "p", "text": "Bir kez claude plugin install figma@claude-plugins-official ile kurun (Dev Mode MCP, ücretli bir Figma planı gerektirir). Aynı Figma MCP; Claude Code, Codex, Cursor ve VS Code için kullanılabilir — tam olarak Open Design'ın düzenlemek için inşa edildiği türden taşınabilir, çok ajanlı bir yetenek."}]}, {"id": "vs", "heading": "Tasarım için Claude Code, Codex ve Cursor", "blocks": [{"kind": "p", "text": "Tasarım çalışması için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler bunları üst üste yığar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["Claude Code", "Spesifik tasarım kararları (hex, boşluk, tipografi) ve kod tabanının farkında UX akıl yürütmesi", "Frontend akıl yürütmesi ve geniş bağlamlı yeniden düzenlemeler"], ["Codex", "Güçlü görsel cila ve görsel anlama; sandbox'lanmış asenkron derlemeler", "Devredilen asenkron derlemeler ve taşınabilir AGENTS.md kuralları"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"]]}, {"kind": "p", "text": "Tekrarlanan topluluk kararı, zevkin insanlardan geldiğidir: üçü de skill'ler, referanslar ve kısıtlar olmadan jenerik bir estetiğe varsayılan olarak kayar. Çözülmesi gereken asıl sorun budur — ve bu sorun, model biçimli değil, tasarım aracı biçimlidir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “AI çöplüğü” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Claude Code'un zevk konusundaki ününe rağmen, AI tarafından üretilen tasarımla ilgili en yaygın şikayet, jenerik görünmesidir — Inter yazı tipleri, beyaz üzerine mor degradeler, yumuşak gölgeler, aşırı büyük yuvarlatılmış köşeler, “bunu bir AI yaptı diye bağıran” bir estetik. Anthropic bunu dağılımsal yakınsamaya bağlar: güvenli seçimler web eğitim verilerine hakimdir. Bildirilen diğer sorunlar arasında bozuk mobil düzenler ve UI metnine sızan talimatlar yer alır."}, {"kind": "steps", "items": [{"label": "Frontend Design skill'ini kurun", "body": "Claude'u gerçek bir yöne bağlanmaya zorlar ve AI tarafından aşırı kullanılan yazı tiplerinden ve degradelerden açıkça kaçınır."}, {"label": "Tarayıcı doğrulamasını etkinleştirin", "body": "Claude'un kırılma noktaları boyunca işlemesini ve kendi kendini kontrol etmesini sağlayın, böylece düzenler mobilde sessizce bozulmasın."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki en büyük tek kaldıraçtır."}, {"label": "Kuralları CLAUDE.md içinde kodlayın", "body": "“hero kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Her hafifletmenin, ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı zahmettir."}]}, {"id": "open-design", "heading": "Open Design içinde Claude Code ile tasarım", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. Claude Code'u birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi, yapılandırılmış bir render hattı ve yerel bir masaüstü UI'sı ile sarmalar — böylece Claude Code'u iyi yapan tasarım bağlamı, her seferinde elle bir araya getirilmek yerine ilk çalıştırmadan itibaren oradadır."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak Claude Code'u seçin.", "Anthropic API anahtarınız (BYOK) veya Claude aboneliğinizle kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy'lenmez.", "Bir tasarım sistemi ve bir skill seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları üretin.", "Her artefakt ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi reponuzda yaşar."]}, {"kind": "p", "text": "Aynı Claude Code ajanı, aynı anahtar — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0'dır, bu yüzden çalışmanız veya kimlik bilgileriniz hakkında hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "Claude Code tasarım çalışması için iyi mi?", "text": "Evet — frontend konusunda en iyi zevke sahip kodlama ajanı olarak yaygın biçimde kabul edilir; hex değerleri, boşluk ve tipografi ölçekleri hakkında spesifik, kod tabanının farkında kararlar verir. Frontend Design skill'i, bir tasarım sistemi ve bağlamdaki gerçek referans görsellerle, üretim kalitesinde, duyarlı UI üretir ve bunu bir tarayıcıda doğrulayabilir. Bu bağlam olmadan jenerik bir görünüme dönme eğilimindedir; Open Design'ın doldurduğu boşluk da budur."}, {"name": "Claude Code ile tasarım yapmak için bir Claude aboneliğine ihtiyacım var mı?", "text": "Bir Anthropic API anahtarı (BYOK, Console üzerinden) veya bir Claude aboneliği (Pro / Max) kullanabilirsiniz. Her iki durumda da Open Design kimlik bilgilerinizi asla proxy'lemez — bunlar doğrudan makinenizdeki ajanınız tarafından kullanılır."}, {"name": "Frontend tasarımı için Claude Code mı yoksa Codex mı?", "text": "İkisi de güçlüdür. Claude Code, spesifik, kod tabanının farkında tasarım kararları ve frontend akıl yürütmesiyle bilinir; Codex'in güçlü bir görsel cilası vardır ve devredilen, sandbox'lanmış derlemelerde öne çıkar. Birçok ekip ikisini de kullanır — Open Design, tasarım iş akışınızı değiştirmeden ajanlar arasında geçiş yapmanızı sağlar."}, {"name": "Claude Code'u Figma'ya nasıl bağlarım?", "text": "Resmi Figma eklentisini claude plugin install figma@claude-plugins-official ile kurun. Ardından tasarım bağlamını kullanarak Figma frame'lerini kod olarak uygulayabilir ve çalışan bir UI'ı “Send this to Figma” ile düzenlenebilir Figma frame'lerine geri gönderebilirsiniz. Dev Mode MCP, ücretli bir Figma planı gerektirir."}, {"name": "Skills ve CLAUDE.md nedir?", "text": "CLAUDE.md, Claude Code'un her oturumun başında okuduğu, proje kökünüzdeki bir markdown dosyasıdır — tasarım kurallarınızı kodlama yeri. Skills, Claude'un talep üzerine yüklediği yinelenebilir talimatları ve kaynakları paketler; buna Anthropic'in resmi Frontend Design skill'i de dahildir. Open Design her ikisinden de özenle seçilmiş bir kütüphane sunar, böylece proje başına kurulumu atlarsınız."}, {"name": "Jenerik “AI çöplüğü” estetiğinden nasıl kaçınırım?", "text": "Frontend Design skill'ini kurun, gerçek tasarım token'ları ve referans ekran görüntüleri sağlayın, marka kurallarını CLAUDE.md içinde kodlayın ve tarayıcı doğrulamasını etkinleştirin. Open Design bunları özenle seçilmiş bir kütüphane olarak sunar, böylece proje başına kurulumu atlarsınız."}, {"name": "Open Design, Anthropic ile bağlantılı mı?", "text": "Hayır. Claude Code, Anthropic'in bir ürünüdür; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynaklı projedir. Claude ve Claude Code, Anthropic'in ticari markalarıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel öncelikli ve Apache-2.0'dır. Dosyalarınız, artefaktlarınız ve DESIGN.md'niz kendi reponuzda kalır ve Anthropic kimlik bilgileriniz doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "Claude Code ile açık yolla tasarlayın.", "ctaBody": "Kendi Anthropic anahtarınızı veya Claude aboneliğinizi getirin, her dosyayı yerel tutun ve zaten kullandığınız ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "Claude Code'u Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'codex': {
        ...en['codex']!,
        title: "Tasarım için Codex — Open Design",
        description: "İnsanlar OpenAI Codex'i UI ve web tasarımı için nasıl kullanır — Product Design eklentisi, Figma entegrasyonu, frontend skill'leri — ve Open Design Codex'i nasıl yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür.",
        breadcrumb: "Codex",
        label: "Ajan · Codex",
        heading: "Tasarım için Codex.",
        lead: "Codex, OpenAI'nin kodlama ajanıdır. Product Design eklentisi ve Figma entegrasyonu ile ciddi bir tasarım aracı haline geldi. Open Design, Codex'i açık kaynaklı bir tasarım iş akışına bağlar — OpenAI anahtarınız veya ChatGPT aboneliğiniz, dosyalarınız, yerel öncelikli.",
        rich: {"heroCtaLead": "Open Design, Codex'i yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — OpenAI anahtarınız, dosyalarınız ve etrafında özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "Codex'i Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["OpenAI Codex bir kod üreticisi olarak başladı, ancak 2026'da — ona doğru referansları, skill'leri ve doğrulama döngüsünü verdiğinizde — gerçek arayüzler tasarlamak için inandırıcı bir araç haline geldi. Bu, Codex'i UI, frontend ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya dair pratik, uçtan uca bir rehberdir.", "Codex'in bugün ne olduğunu, frontend'de neden birden iyi olduğunu, sıfırdan nasıl kurulacağını, ekran görüntüsünden UI'a döngüyü, resmi Figma gidiş-dönüşünü, Cursor ve Claude Code ile nasıl karşılaştırıldığını, AI çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak bu boşluğu nasıl kapattığını ele alır."], "heroImage": {"src": "/agents/codex-design/codex-design-workflow-loop.webp", "alt": "Codex tasarım geri bildirim döngüsü: terminal ajanı, UI'ı işleyen tarayıcı ve bir çalışma alanı, geri döngü oluşturan bir geri bildirim okuyla", "caption": "Çekirdek döngü: Codex terminalde UI oluşturur, bunu gerçek bir tarayıcıda işler ve doğrular, referanslarınıza karşı yineler."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-codex", "label": "OpenAI Codex gerçekte nedir"}, {"id": "why-design", "label": "Codex artık tasarımda neden iyi"}, {"id": "setup", "label": "Codex'i tasarım için kurun (sıfırdan)"}, {"id": "screenshot-workflow", "label": "Ekran görüntüsünden UI'a iş akışı"}, {"id": "figma", "label": "Codex + Figma gidiş-dönüşü"}, {"id": "vs", "label": "Codex, Cursor ve Claude Code karşılaştırması"}, {"id": "pitfalls", "label": "Tuzaklar ve “AI çöplüğü” görünümü"}, {"id": "open-design", "label": "Open Design içinde Codex ile tasarım"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-codex", "heading": "OpenAI Codex gerçekte nedir (ve ne değildir)", "blocks": [{"kind": "p", "text": "Önce, “Codex” arayan hemen herkesi tökezleten bir kavram karmaşasını giderelim. Orijinal OpenAI Codex, erken GitHub Copilot'a güç veren ve 2023'te kullanımdan kaldırılan 2021 tarihli bir kod tamamlama modeliydi. Bu sayfanın konusu o değil. Bugünün Codex'i, OpenAI'nin ajansal kodlama aracıdır — doğal dildeki görevlerden kodu planlar, yazar, çalıştırır ve doğrular."}, {"kind": "p", "text": "Modern Codex dört yüzey üzerinden sunulur: bir terminal CLI'si (Rust ile yeniden yazılmış, Apache-2.0 lisanslı), VS Code, Cursor ve Windsurf için bir IDE eklentisi, devredilen asenkron görevler için bir bulut/web deneyimi ve uygulama içi bir tarayıcı ve Computer Use'a sahip bir masaüstü uygulaması."}, {"kind": "steps", "items": [{"label": "Varsayılan model", "body": "2026 ortası itibarıyla önerilen model gpt-5.5'tir; gpt-5.4 ise OpenAI'nin frontend ve bilgisayar kullanımı için açıkça eğittiği modeldir."}, {"label": "Talimat dosyası", "body": "Codex, proje kuralları için projenizdeki bir AGENTS.md dosyasını (araçlar arası bir standart) okur — tasarım kurallarınızı kodlamak için doğal yer."}, {"label": "Sandbox", "body": "Çekirdek düzeyinde bir sandbox'ta çalışır (varsayılan olarak workspace-write), böylece UI'ınızı düzenleyen bir ajan projenin dışına çıkamaz."}]}, {"kind": "ul", "items": ["Sağlayıcı: OpenAI", "Kimlik bilgisi: OpenAI API anahtarı (BYOK) veya ChatGPT aboneliği (Free / Go / Plus / Pro / Business / Enterprise)", "CLI'nin lisansı: Apache-2.0, açık kaynak"]}]}, {"id": "why-design", "heading": "Codex artık tasarımda neden iyi", "blocks": [{"kind": "p", "text": "2026'nın başlarında üç şey bir araya gelerek Codex'i jenerik bir kod üreticisi yerine gerçek bir tasarım aracı haline getirdi."}, {"kind": "steps", "items": [{"label": "Frontend için eğitilmiş bir model", "body": "OpenAI, frontend ve bilgisayar kullanımı için eğitilmiş ilk ana hat modeli olan GPT-5.4'ü, tasarım iş akışı boyunca çok daha iyi görsel anlama ve daha güçlü kendi kendini doğrulama ile yayınladı. Hatta son varlıklara bağlanmadan önce mood board'lar ve görsel seçenekler bile üretebilir."}, {"label": "Resmi bir frontend skill'i", "body": "openai/skills kataloğu, gerçek bir zevki dayatan özenle seçilmiş bir frontend-skill sunar: kartsız düzenler, tam genişlikte hero'lar, marka öncelikli hiyerarşi, ölçülü hareket, en fazla iki yazı tipi ve bir vurgu rengi — ve Codex'in oluşturmadan önce bir görsel tez yazmasını sağlar."}, {"label": "Tarayıcı doğrulaması", "body": "Playwright skill'i ile Codex, yalnızca derlemenin geçtiğini kontrol etmek yerine gerçek bir tarayıcı açar, kırılma noktalarına yeniden boyutlandırır ve çıktısını referansla karşılaştırır."}]}, {"kind": "image", "src": "/agents/codex-design/codex-design-taste-triangle.webp", "alt": "Tasarım sistemi, skill ve referans görselin iyi tasarım çıktısına yakınsadığını gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir skill ve gerçek referans görseller."}, {"kind": "p", "text": "Üçünün de ardındaki ders: Codex varsayılan olarak zevke sahip değildir. Ona kısıtlar verdiğinizde iyi tasarım üretir — bir tasarım sistemi, estetik bir skill ve somut referanslar. Open Design tam olarak bu girdileri paketler; ikisinin neden birbirine uyduğunun nedeni de budur (daha fazlası aşağıda)."}]}, {"id": "setup", "heading": "Codex'i tasarım çalışması için sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden, UI oluşturabilen ve doğrulayabilen bir Codex'e giden tam yol şudur."}, {"kind": "code", "lang": "bash", "code": "# 1. Install the Codex CLI\nnpm install -g @openai/codex\n# or: brew install --cask codex\n# or: curl -fsSL https://chatgpt.com/codex/install.sh | sh\n\n# 2. Authenticate (ChatGPT sign-in recommended for higher limits)\ncodex            # then choose “Sign in with ChatGPT”\n\n# 3. Generate project context\ncodex            # inside your project, run /init to create AGENTS.md\n\n# 4. Add the official frontend skill, then restart Codex\n# (in the Codex app) $skill-installer frontend-skill\n\n# 5. Wire the Figma MCP server (optional, for design handoff)\ncodex mcp add figma --url https://mcp.figma.com/mcp"}, {"kind": "image", "src": "/agents/codex-design/codex-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: kur, kimlik doğrula, yapılandır, skill kur, doğrula", "caption": "Kurulum sırası: kur → kimlik doğrula → AGENTS.md yapılandır → frontend skill'ini kur → tarayıcı doğrulamasını etkinleştir."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı AGENTS.md veya bir DESIGN.md içine koyun ve Codex'i bunlara yönlendirin; böylece çıktı jenerik bir görünüme dönmek yerine bir markayla eşleşsin."}, {"label": "Doğru akıl yürütme seviyesini seçin", "body": "OpenAI, düşük-orta akıl yürütme seviyelerinin sıklıkla en yüksek ayardan daha güçlü frontend sonuçları ürettiğini belirtiyor."}]}]}, {"id": "screenshot-workflow", "heading": "Ekran görüntüsünden UI'a iş akışı", "blocks": [{"kind": "p", "text": "Codex ile en yüksek kaldıraçlı tasarım döngüsü, bir referans görseli çalışan, duyarlı bir UI'a dönüştürmek ve eşleşene kadar yinelemektir. OpenAI'nin kendi rehberliği beş adıma indirgenir."}, {"kind": "ol", "items": ["Sahip olduğunuz en net görsel referanslardan başlayın — ve yalnızca tek bir hero görseli değil, birden çok durumu (masaüstü ve mobil, hover, boş, yükleniyor) dahil edin.", "Komutta spesifik olun; belirsiz komutlar jenerik UI üretir.", "Bir tasarım sistemi hazırlayın ve Codex'e token'ların ve kanonik ilkellerin nerede yaşadığını söyleyin.", "Playwright etkileşimli skill'ini etkinleştirin, böylece Codex gerçek bir tarayıcıda işler ve kırılma noktalarına yeniden boyutlandırır.", "Codex'in uygulamasını ekran görüntüleriyle karşılaştırmasını sağlayarak yineleyin — yalnızca derlendiğini onaylamasın."]}, {"kind": "p", "text": "Bir ekran görüntüsünü terminale sürükleyerek veya image bayrağı ile görselleri besleyin, ardından somut kısıtlarla komut verin:"}, {"kind": "code", "lang": "bash", "code": "codex -i reference-desktop.png -i reference-mobile.png \\\n  \"Implement this design in React + Vite + Tailwind + TypeScript.\n   Reuse my existing design-system components and tokens.\n   Match spacing, layout, and hierarchy; make it responsive.\n   Use the Playwright skill to verify the UI matches the\n   references and iterate until it does.\""}, {"kind": "p", "text": "İkinci bir terminalde bir dev sunucusu çalıştırın, komutları küçük ve odaklı tutun ve iyi yinelemeleri commit edin / kötü olanları geri alın (geri aldığınızda Codex'e söyleyin), böylece her geçiş temiz bir temel üzerine inşa edilsin."}]}, {"id": "figma", "heading": "Codex + Figma: tasarım ↔ kod gidiş-dönüşü", "blocks": [{"kind": "p", "text": "Şubat 2026'da OpenAI ve Figma resmi bir ortaklık duyurarak önceki Figma MCP beta'sını birinci sınıf, çift yönlü bir entegrasyona dönüştürdü. Her iki yönde de çalışır."}, {"kind": "steps", "items": [{"label": "Tasarım → Kod", "body": "Figma'da bir frame'in “link to selection” bağlantısını kopyalayın, onu get_design_context ile Codex'e yapıştırın ve ondan mevcut bileşen kütüphanenizi kullanarak tasarımı uygulamasını isteyin."}, {"label": "Kod → Tasarım", "body": "generate_figma_design aracı (“Code to Canvas”), canlı, çalışan bir UI'ı düzenlenebilir Figma frame'lerine geri dönüştürür — tüm ekran, seçili bir öğe veya bütün bir dosya."}]}, {"kind": "p", "text": "Figma MCP, uzak bir sunucu olarak çalışır ve hız sınırlarından muaftır. Bir kez ekleyin ve Codex, Claude Code, Cursor, VS Code ve daha fazlası için kullanılabilir olsun — tam olarak Open Design'ın düzenlemek için inşa edildiği türden taşınabilir, çok ajanlı bir yetenek."}]}, {"id": "vs", "heading": "Tasarım için Codex, Cursor ve Claude Code", "blocks": [{"kind": "p", "text": "Tasarım çalışması için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler bunları üst üste yığar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["Codex", "GPT-5.4 + frontend-skill sonrası güçlü görsel cila; görsel anlama", "Devredilen asenkron derlemeler, sandbox'lanmış çalıştırmalar, taşınabilir AGENTS.md kuralları"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"], ["Claude Code", "Spesifik tasarım kararları (hex, boşluk, tipografi) ve kod tabanının farkında UX", "Frontend akıl yürütmesi ve geniş bağlamlı yeniden düzenlemeler"]]}, {"kind": "p", "text": "Tekrarlanan topluluk kararı, zevkin insanlardan geldiğidir: üçü de skill'ler, referanslar ve kısıtlar olmadan jenerik bir estetiğe varsayılan olarak kayar. Çözülmesi gereken asıl sorun budur — ve bu sorun, model biçimli değil, tasarım aracı biçimlidir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “AI çöplüğü” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Codex tarafından üretilen tasarımla ilgili en yaygın şikayet, jenerik görünmesidir — yumuşak degradeler, yüzen paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir AI yaptı diye bağıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında bozuk mobil düzenler, UI metnine sızan talimatlar ve kullanım sınırlarına hızla ulaşmak yer alır."}, {"kind": "steps", "items": [{"label": "Bir frontend skill'i kurun", "body": "Özenle seçilmiş bir estetik skill, Codex'i varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Playwright doğrulamasını etkinleştirin", "body": "Codex'in kırılma noktaları boyunca işlemesini ve kendi kendini kontrol etmesini sağlayın, böylece düzenler mobilde sessizce bozulmasın."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki en büyük tek kaldıraçtır."}, {"label": "Kuralları AGENTS.md içinde kodlayın", "body": "“hero kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Her hafifletmenin, ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı zahmettir."}]}, {"id": "open-design", "heading": "Open Design içinde Codex ile tasarım", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. Codex'i birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi, yapılandırılmış bir render hattı ve yerel bir masaüstü UI'sı ile sarmalar — böylece Codex'i iyi yapan tasarım bağlamı, her seferinde elle bir araya getirilmek yerine ilk çalıştırmadan itibaren oradadır."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak Codex'i seçin.", "OpenAI API anahtarınız (BYOK) veya ChatGPT aboneliğinizle kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy'lenmez.", "Bir tasarım sistemi ve bir skill seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları üretin.", "Her artefakt ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi reponuzda yaşar."]}, {"kind": "p", "text": "Aynı Codex ajanı, aynı anahtar — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0'dır, bu yüzden çalışmanız veya kimlik bilgileriniz hakkında hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "OpenAI Codex gerçekten tasarım çalışması yapabilir mi?", "text": "Evet — bağlamda bir frontend skill'i, bir tasarım sistemi ve gerçek referans görsellerle Codex (özellikle GPT-5.4 üzerinde) üretim kalitesinde, duyarlı UI üretir ve bunu bir tarayıcıda doğrulayabilir. Bu bağlam olmadan jenerik bir görünüme dönme eğilimindedir; Open Design'ın doldurduğu boşluk da budur."}, {"name": "Bu, OpenAI Codex Product Design eklentisi mi?", "text": "Hayır. Open Design, Codex'i bir ajan olarak entegre eden bağımsız bir açık kaynaklı projedir. OpenAI'nin kendi araçlarını yerel öncelikli, açık bir skill ve tasarım sistemi kütüphanesiyle tamamlar."}, {"name": "Codex ile tasarım yapmak için bir ChatGPT aboneliğine ihtiyacım var mı?", "text": "Bir OpenAI API anahtarı (BYOK) veya ChatGPT aboneliğinizi kullanabilirsiniz. ChatGPT ile oturum açmak genellikle daha cömert sınırlar verir; Open Design her iki durumda da kimlik bilgilerinizi asla proxy'lemez."}, {"name": "Frontend tasarımı için Codex mi yoksa Claude Code mu?", "text": "İkisi de güçlüdür. Claude Code, spesifik, kod tabanının farkında tasarım kararlarıyla bilinir; Codex'in GPT-5.4 sonrası güçlü bir görsel cilası vardır ve devredilen, sandbox'lanmış derlemelerde öne çıkar. Birçok ekip ikisini de kullanır — Open Design, tasarım iş akışınızı değiştirmeden ajanlar arasında geçiş yapmanızı sağlar."}, {"name": "Codex'i Figma'ya nasıl bağlarım?", "text": "Resmi Figma MCP sunucusunu ekleyin (codex mcp add figma --url https://mcp.figma.com/mcp). Ardından get_design_context ile Figma frame'lerini kod olarak uygulayabilir ve çalışan bir UI'ı generate_figma_design ile düzenlenebilir Figma frame'lerine geri gönderebilirsiniz."}, {"name": "Jenerik “AI çöplüğü” estetiğinden nasıl kaçınırım?", "text": "Bir frontend skill'i kurun, gerçek tasarım token'ları ve referans ekran görüntüleri sağlayın, marka kurallarını AGENTS.md içinde kodlayın ve Playwright doğrulamasını etkinleştirin. Open Design bunları özenle seçilmiş bir kütüphane olarak sunar, böylece proje başına kurulumu atlarsınız."}, {"name": "Open Design, OpenAI ile bağlantılı mı?", "text": "Hayır. Codex, OpenAI'nin bir ürünüdür; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynaklı projedir. OpenAI ve Codex, OpenAI'nin ticari markalarıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel önceliklidir. Dosyalarınız, artefaktlarınız ve DESIGN.md'niz kendi reponuzda kalır ve OpenAI kimlik bilgileriniz doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "Codex ile açık yolla tasarlayın.", "ctaBody": "Kendi OpenAI anahtarınızı getirin, her dosyayı yerel tutun ve zaten kullandığınız ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "Codex'i Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'cursor': {
        ...en['cursor']!,
        title: "Tasarımcılar için Cursor — Open Design",
        description: "Tasarımcılar Cursor'ı UI ve web tasarımı için nasıl kullanır — Design Mode, Figma'dan koda, Figma MCP — ve Open Design Cursor'ı nasıl yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür.",
        breadcrumb: "Cursor",
        label: "Ajan · Cursor",
        heading: "Tasarımcılar için Cursor.",
        lead: "Cursor, artık görsel bir Design Mode'a sahip AI kod editörüdür. Tasarımcılar onu işaret ve çizim yoluyla UI düzenlemek ve Figma'yı koda dönüştürmek için kullanır. Open Design, Cursor Agent'ı dosyalarınızı yerel tutan açık kaynaklı bir tasarım iş akışına bağlar.",
        rich: {"heroCtaLead": "Open Design, Cursor'ı yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — Cursor hesabınız veya model anahtarlarınız, dosyalarınız ve etrafında özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "Cursor'ı Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Cursor, “oluştur ve işlenmesini izle” yaklaşımını UI'ı yayınlamanın varsayılan yolu haline getiren AI öncelikli kod editörüdür. Agent modu, satır içi düzenlemeler, editör içi bir önizleme ve MCP üzerinden Figma ile — ona doğru referansları, kuralları ve bir doğrulama döngüsü verdiğinizde — gerçek bir tasarım aracı haline geldi. Bu, Cursor'ı UI, frontend ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya dair pratik, uçtan uca bir rehberdir.", "Cursor'ın gerçekte ne olduğunu, sıkı yinele-ve-izle döngüsünün tasarım için neden iyi olduğunu, sıfırdan nasıl kurulacağını, ekran görüntüsünden ve önizlemeden UI'a döngüyü, MCP üzerinden Figma gidiş-dönüşünü, Codex ve Claude Code ile nasıl karşılaştırıldığını, AI çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak bu boşluğu nasıl kapattığını ele alır."], "heroImage": {"src": "/agents/cursor-design/cursor-design-hero.webp", "alt": "Cursor tasarım yakınsaması: solda editör, ortada merkezinde Cursor işaretiyle özenle seçilmiş bir skill ve tasarım sistemi merkezi ve sağda işlenmiş bir UI", "caption": "Çekirdek fikir: Cursor, editörde UI'ı düzenler ve işler, bu sırada özenle seçilmiş bir tasarım merkezi ona çıktıyı bilinçli gösteren sistemi, skill'leri ve referansları besler."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-cursor", "label": "Cursor gerçekte nedir"}, {"id": "why-design", "label": "Cursor tasarımda neden iyi"}, {"id": "setup", "label": "Cursor'ı tasarım için kurun (sıfırdan)"}, {"id": "preview-workflow", "label": "Önizlemeden UI'a iş akışı"}, {"id": "figma", "label": "MCP üzerinden Cursor + Figma"}, {"id": "vs", "label": "Cursor, Codex ve Claude Code karşılaştırması"}, {"id": "pitfalls", "label": "Tuzaklar ve “AI çöplüğü” görünümü"}, {"id": "open-design", "label": "Open Design içinde Cursor ile tasarım"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-cursor", "heading": "Cursor gerçekte nedir", "blocks": [{"kind": "p", "text": "Cursor, Anysphere tarafından geliştirilen AI öncelikli bir kod editörüdür. VS Code'un bir fork'udur, bu yüzden tanıdık editörü, eklentileri ve kısayol tuşlarını korur, ancak iş akışını; tüm projenizi okuyabilen, birden çok dosyayı düzenleyebilen, komutları çalıştırabilen ve sizinle döngü içinde yineleyebilen bir AI ajanı etrafında yeniden inşa eder."}, {"kind": "p", "text": "Tasarım çalışması için önemli yüzeyler şunlardır: Agent modu (bir sonuç tarif edersiniz ve Cursor dosyalar boyunca planlar ve düzenler), hızlı ince ayarlar için satır içi düzenlemeler ve Tab tamamlamaları, pencereyi terk etmeden çalışan UI'ı görebilmeniz için editör içi bir önizleme / tarayıcı ve canlı bir Figma dosyası gibi harici bağlamı çekmesine izin veren MCP desteği."}, {"kind": "steps", "items": [{"label": "Proje kuralları", "body": "Cursor, proje talimat dosyalarını okur — `.cursor/rules` altındaki sürümlenmiş `.mdc` kuralları ve sade bir `AGENTS.md` — böylece tasarım kurallarınızı ajanın her çalıştırmada okuduğu yere kodlayabilirsiniz."}, {"label": "Modeller", "body": "Cursor model açısından esnektir: aboneliğiniz üzerinden öncü modellerle gelir ve ayrıca kendi model anahtarlarınızı getirmeyi destekler, böylece aynı editör iş akışının arkasındaki motoru siz seçersiniz."}, {"label": "MCP", "body": "Model Context Protocol konuşur, böylece harici sunucular — en alakalısı Figma MCP sunucusu — ajan için birinci sınıf bağlam haline gelir."}]}, {"kind": "ul", "items": ["Sağlayıcı: Anysphere", "Kimlik bilgisi: Cursor hesabı / aboneliği (Hobby / Pro / Business) veya kendi model anahtarlarınız (BYOK)", "Biçim: Editör içi bir ajan ve önizlemeye sahip AI öncelikli kod editörü (VS Code fork'u)"]}]}, {"id": "why-design", "heading": "Cursor tasarımda neden iyi", "blocks": [{"kind": "p", "text": "Cursor'ın tasarım üstünlüğü tek bir özellik değildir — oluştur-ve-gör döngüsünün sıkılığıdır. Üç şey onu jenerik bir kod üreticisi yerine bir tasarım aracı gibi hissettirir."}, {"kind": "steps", "items": [{"label": "Sıkı bir yinele-ve-izle döngüsü", "body": "Komut verirsiniz, Cursor dosyalar boyunca düzenler ve editör içi önizleme sonucu hemen işler — böylece boşluğu, hiyerarşiyi ve hareketi ayrı bir terminal ve tarayıcı arasında gidip gelmek yerine saniyeler içinde ayarlarsınız."}, {"label": "Doğrudan görsel düzenleme", "body": "Sohbetin ötesinde, Cursor önizlemede öğeleri seçmenize ve stilleri ince ayar yapmanıza izin verir, böylece küçük görsel düzeltmeler kod arkeolojisi yerine tasarım düzenlemeleri gibi hissettirir."}, {"label": "Proje kuralları ve MCP bağlamı", "body": "`.cursor/rules` (veya `AGENTS.md`) ve Figma MCP sunucusu ile ajan, tahmin yürütmek yerine token'larınıza, bileşenlerinize ve gerçek tasarım spesifikasyonlarınıza karşı çalışır."}]}, {"kind": "image", "src": "/agents/cursor-design/cursor-design-taste-triangle.webp", "alt": "Tasarım sistemi, skill ve referans görselin iyi tasarım çıktısına yakınsadığını gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir skill ve gerçek referans görseller."}, {"kind": "p", "text": "Çıkarılan ders, her ajanın öğrettiğiyle aynıdır: Cursor varsayılan olarak zevke sahip değildir. Ona kısıtlar verdiğinizde iyi tasarım üretir — bir tasarım sistemi, estetik bir skill ve somut referanslar. Open Design tam olarak bu girdileri paketler; ikisinin neden birbirine uyduğunun nedeni de budur (daha fazlası aşağıda)."}]}, {"id": "setup", "heading": "Cursor'ı tasarım çalışması için sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden; tasarım sisteminize karşı UI oluşturabilen, önizleyebilen ve doğrulayabilen bir Cursor'a giden tam yol şudur."}, {"kind": "ol", "items": ["Cursor'ı cursor.com'dan kurun ve Cursor hesabınızla oturum açın veya Ayarlar'da kendi model anahtarlarınızı (BYOK) yapılandırın.", "Projenizi açın ve sohbet / Agent panelinde bir model seçin.", "Proje kuralları ekleyin: yapılandırılmış, glob kapsamlı kurallar için `.cursor/rules/*.mdc` oluşturun veya basit, okunabilir talimatlar için sade bir `AGENTS.md` oluşturun.", "Figma MCP sunucusunu bağlayın (isteğe bağlı), böylece ajan canlı tasarım bağlamını okuyabilir.", "Dev sunucunuzu çalıştırın ve yinelerken UI'ı görmek ve doğrulamak için editör içi önizlemeyi kullanın."]}, {"kind": "image", "src": "/agents/cursor-design/cursor-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: kur, kimlik doğrula, kuralları yapılandır, skill ekle, doğrula", "caption": "Kurulum sırası: kur → kimlik doğrula → proje kurallarını yapılandır → bir skill ekle → önizleme doğrulamasını etkinleştir."}, {"kind": "p", "text": "Minimal bir proje kuralları dosyası, ajanın jenerik bir görünüme dönmek yerine bir markaya göre tasarlamasını sağlar. Onu Cursor'ın her çalıştırmada okuduğu yere koyun:"}, {"kind": "code", "lang": "markdown", "code": "# .cursor/rules/design.mdc\n---\ndescription: Project design conventions\nalwaysApply: true\n---\n\n- Reuse existing design-system tokens and components; never hardcode hex or spacing.\n- At most two typefaces and one accent color.\n- Brand-first hierarchy; restrained motion. No hero cards, no oversized rounded corners.\n- Build responsive by default; verify desktop and mobile in the preview before finishing."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı `.cursor/rules` veya `AGENTS.md` içine koyun ve Cursor'ı bunlara yönlendirin; böylece çıktı jenerik bir görünüme dönmek yerine bir markayla eşleşsin."}, {"label": "Komutları küçük tutun", "body": "Cursor'ın sıkı döngüsü odaklı isteklere ödül verir — bir seferde bir bileşen veya durum üzerinde yineleyin ve geçişler arasında önizlemeyi izleyin."}]}]}, {"id": "preview-workflow", "heading": "Önizlemeden UI'a iş akışı", "blocks": [{"kind": "p", "text": "Cursor ile en yüksek kaldıraçlı tasarım döngüsü, bir referansı çalışan, duyarlı bir UI'a dönüştürmek ve eşleşene kadar editörde yinelemektir — tahmin yürütmek yerine canlı önizlemeyi sürekli izleyerek."}, {"kind": "ol", "items": ["Sahip olduğunuz en net görsel referanslardan başlayın — ve yalnızca tek bir hero görseli değil, birden çok durumu (masaüstü ve mobil, hover, boş, yükleniyor) dahil edin.", "Komutta spesifik olun; belirsiz komutlar jenerik UI üretir.", "Bir tasarım sistemi hazırlayın ve Cursor'a token'ların ve kanonik ilkellerin nerede yaşadığını söyleyin.", "Editör içi önizlemeyi açık ve dev sunucunuzu çalışır tutun, böylece her düzenleme önemsediğiniz kırılma noktalarında hemen işlensin.", "İşlenmiş UI'ı referanslarla karşılaştırarak yineleyin — ve küçük görsel düzeltmeler için önizlemede doğrudan öğe seçimini kullanın."]}, {"kind": "p", "text": "Sohbete bir görsel ekleyerek referansları besleyin, ardından somut kısıtlarla komut verin:"}, {"kind": "code", "lang": "text", "code": "Implement this design in React + Vite + Tailwind + TypeScript.\nReuse my existing design-system components and tokens.\nMatch spacing, layout, and hierarchy; make it responsive.\nKeep the preview open — verify desktop and mobile match the\nreferences and iterate until they do."}, {"kind": "p", "text": "İyi yinelemeleri commit edin ve kötü olanları geri alın (geri aldığınızda Cursor'a söyleyin), böylece her geçiş temiz bir temel üzerine inşa edilsin — herhangi bir ajan döngüsünün sapmasını önleyen aynı disiplin."}]}, {"id": "figma", "heading": "Cursor + Figma: MCP üzerinden tasarım ↔ kod", "blocks": [{"kind": "p", "text": "Cursor, resmi Figma MCP sunucusu aracılığıyla Figma'ya bağlanır; bu da ajana düz bir ekran görüntüsü yerine canlı bir Figma dosyasına yapılandırılmış erişim sağlar. Bu, devirden tahmin yürütmeyi ortadan kaldırır."}, {"kind": "steps", "items": [{"label": "Tasarım → Kod", "body": "Figma'da bir frame'in bağlantısını kopyalayın, onu Cursor'a yapıştırın ve ondan tasarımı uygulamasını isteyin. MCP sunucusu gerçek tasarım bağlamını — bileşenler, değişkenler, düzen verisi, token'lar — açığa çıkarır, böylece üretilen kod kaynağa yaklaşmak yerine onunla eşleşir."}, {"label": "Hizalı kalın", "body": "Figma'da tutarlı kullanılan tasarım token'ları, stiller ve bileşenlerle (ve mevcut olduğunda Code Connect ile), Cursor'ın çıktısı ilkelleri yeniden icat etmek yerine gerçek tasarım sisteminize eşlenmiş kalır."}]}, {"kind": "p", "text": "Uzak Figma MCP sunucusunu bir kez kurun, Cursor için birinci sınıf bağlam olarak kullanılabilir olsun. MCP açık bir standart olduğundan, aynı sunucu Cursor, Claude Code, Codex ve VS Code arasında yeniden kullanılabilir — tam olarak Open Design'ın düzenlemek için inşa edildiği türden taşınabilir, çok ajanlı bir yetenek."}]}, {"id": "vs", "heading": "Tasarım için Cursor, Codex ve Claude Code", "blocks": [{"kind": "p", "text": "Tasarım çalışması için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler bunları üst üste yığar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["Cursor", "Canlı editör içi önizleme ve doğrudan öğe düzenlemeyle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"], ["Codex", "Bir frontend skill'i ile güçlü görsel cila; görsel anlama ve sandbox'lanmış çalıştırmalar", "Devredilen asenkron derlemeler ve taşınabilir AGENTS.md kuralları"], ["Claude Code", "Spesifik tasarım kararları (hex, boşluk, tipografi) ve kod tabanının farkında UX", "Frontend akıl yürütmesi ve geniş bağlamlı yeniden düzenlemeler"]]}, {"kind": "p", "text": "Tekrarlanan topluluk kararı, zevkin insanlardan geldiğidir: üçü de skill'ler, referanslar ve kısıtlar olmadan jenerik bir estetiğe varsayılan olarak kayar. Çözülmesi gereken asıl sorun budur — ve bu sorun, model biçimli değil, tasarım aracı biçimlidir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “AI çöplüğü” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Cursor tarafından üretilen tasarımla ilgili en yaygın şikayet, jenerik görünmesidir — yumuşak degradeler, yüzen paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir AI yaptı diye bağıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında mobilde bozulan düzenler ve UI metnine sızan talimatlar yer alır."}, {"kind": "steps", "items": [{"label": "Bir tasarım skill'i ekleyin", "body": "Özenle seçilmiş bir estetik skill, Cursor'ı varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Doğrulamak için önizlemeyi kullanın", "body": "Editör içi önizlemede kırılma noktaları boyunca işleyin ve kendi kendini kontrol edin, böylece düzenler mobilde sessizce bozulmasın."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki en büyük tek kaldıraçtır."}, {"label": "Kuralları `.cursor/rules` içinde kodlayın", "body": "“hero kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Her hafifletmenin, ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı zahmettir."}]}, {"id": "open-design", "heading": "Open Design içinde Cursor ile tasarım", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. Cursor'ı birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi, yapılandırılmış bir render hattı ve yerel bir masaüstü UI'sı ile sarmalar — böylece Cursor'ı iyi yapan tasarım bağlamı, her seferinde elle bir araya getirilmek yerine ilk çalıştırmadan itibaren oradadır."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak Cursor'ı seçin.", "Cursor hesabınız veya kendi model anahtarlarınızla (BYOK) kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy'lenmez.", "Bir tasarım sistemi ve bir skill seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları üretin.", "Her artefakt ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi reponuzda yaşar."]}, {"kind": "p", "text": "Aynı Cursor ajanı, aynı anahtar — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0'dır, bu yüzden çalışmanız veya kimlik bilgileriniz hakkında hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "Cursor gerçekten tasarım çalışması yapabilir mi?", "text": "Evet — bağlamda bir tasarım skill'i, bir tasarım sistemi ve gerçek referans görsellerle Cursor üretim kalitesinde, duyarlı UI üretir ve editör içi önizlemesi onu görsel olarak doğrulamanıza ve iyileştirmenize olanak tanır. Bu bağlam olmadan jenerik bir görünüme dönme eğilimindedir; Open Design'ın doldurduğu boşluk da budur."}, {"name": "Bu resmi bir Cursor ürünü mü?", "text": "Hayır. Open Design, Cursor'ı bir ajan olarak entegre eden bağımsız bir açık kaynaklı projedir. Cursor'ı yerel öncelikli, açık bir skill ve tasarım sistemi kütüphanesiyle tamamlar."}, {"name": "Cursor ile tasarım yapmak için bir Cursor aboneliğine ihtiyacım var mı?", "text": "Bir Cursor hesabı / aboneliği kullanabilir veya kendi model anahtarlarınızı (BYOK) getirebilirsiniz. Open Design her iki durumda da kimlik bilgilerinizi asla proxy'lemez — bunlar doğrudan ajanınız tarafından kullanılır."}, {"name": "Frontend tasarımı için Cursor mı yoksa Claude Code mu?", "text": "İkisi de güçlüdür. Claude Code, spesifik, kod tabanının farkında tasarım kararlarıyla bilinir; Cursor'ın üstünlüğü, editör içinde canlı bir önizlemeyle sıkı oluştur-ve-gör döngüsüdür. Birçok ekip ikisini de kullanır — Open Design, tasarım iş akışınızı değiştirmeden ajanlar arasında geçiş yapmanızı sağlar."}, {"name": "Cursor'ı Figma'ya nasıl bağlarım?", "text": "Cursor'a resmi Figma MCP sunucusunu ekleyin, ardından bir Figma frame bağlantısını sohbete yapıştırın ve Cursor'dan onu uygulamasını isteyin. Sunucu gerçek bileşenleri, değişkenleri ve düzen verisini açığa çıkarır, böylece üretilen kod kaynak tasarımla eşleşir."}, {"name": "Jenerik “AI çöplüğü” estetiğinden nasıl kaçınırım?", "text": "Bir tasarım skill'i ekleyin, gerçek tasarım token'ları ve referans ekran görüntüleri sağlayın, marka kurallarını `.cursor/rules` veya `AGENTS.md` içinde kodlayın ve önizlemede kırılma noktaları boyunca doğrulayın. Open Design bunları özenle seçilmiş bir kütüphane olarak sunar, böylece proje başına kurulumu atlarsınız."}, {"name": "Open Design, Cursor veya Anysphere ile bağlantılı mı?", "text": "Hayır. Cursor, Anysphere'in bir ürünüdür; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynaklı projedir. Cursor ve Anysphere, Anysphere, Inc.'in ticari markalarıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel önceliklidir. Dosyalarınız, artefaktlarınız ve DESIGN.md'niz kendi reponuzda kalır ve Cursor veya model kimlik bilgileriniz doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "Cursor ile açık yolla tasarlayın.", "ctaBody": "Kendi Cursor hesabınızı veya model anahtarlarınızı getirin, her dosyayı yerel tutun ve zaten kullandığınız ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "Cursor'ı Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'opencode': {
        ...en['opencode']!,
        title: "Tasarım için OpenCode — Open Design",
        description: "İnsanlar OpenCode'u UI ve web tasarımı için nasıl kullanır — design.md dosyaları, UI/UX skill'leri, Figma MCP — ve Open Design OpenCode'u nasıl yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür.",
        breadcrumb: "OpenCode",
        label: "Ajan · OpenCode",
        heading: "Tasarım için OpenCode.",
        lead: "OpenCode, açık kaynaklı terminal AI kodlama ajanıdır. Tasarımcılar gerçek UI üretmek için ona tasarım skill'leri ve DESIGN.md dosyaları ekler. Open Design bunu yapılandırılmış, açık kaynaklı bir iş akışı haline getirir — sağlayıcı anahtarlarınızı getirin, her şeyi yerel tutun.",
        rich: {"heroCtaLead": "Open Design, OpenCode'u yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — kendi sağlayıcı anahtarınızla seçtiğiniz herhangi bir model, dosyalarınız ve etrafında özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "OpenCode'u Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["OpenCode, bilinçli olarak modelden bağımsız, açık kaynaklı, terminal öncelikli bir AI kodlama ajanıdır: kendi sağlayıcı anahtarınızı getirir ve aynı iş akışının arkasında istediğiniz herhangi bir modeli çalıştırırsınız. Bu açıklık onu tasarım çalışması için doğal bir temel haline getirir — ama her ajan gibi, yalnızca ona doğru referansları, skill'leri ve bir doğrulama döngüsü verdiğinizde iyi UI üretir. Bu, OpenCode'u UI, frontend ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya dair pratik, uçtan uca bir rehberdir.", "OpenCode'un gerçekte ne olduğunu, modelden bağımsız, açık bir ajanın tasarım için neden iyi bir uyum olduğunu, sıfırdan nasıl kurulacağını, ekran görüntüsünden UI'a döngüyü, AGENTS.md ve MCP'nin onu nasıl genişlettiğini, Codex, Claude Code ve Cursor ile nasıl karşılaştırıldığını, AI çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak bu boşluğu nasıl kapattığını ele alır — doğal bir eşleşme, çünkü her iki proje de açık kaynaklı ve kendi makinenizde çalışır."], "heroImage": {"src": "/agents/opencode-design/opencode-design-hero.webp", "alt": "OpenCode tasarım geri bildirim döngüsü: bir terminal TUI ajanı, UI'ı işleyen bir tarayıcı ve bir çalışma alanı, geri döngü oluşturan bir geri bildirim okuyla", "caption": "Çekirdek döngü: OpenCode terminalde UI oluşturur, bunu gerçek bir tarayıcıda işler ve doğrular, referanslarınıza karşı yineler — seçtiğiniz hangi model olursa olsun."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-opencode", "label": "OpenCode gerçekte nedir"}, {"id": "why-design", "label": "Açık, her-model ajanı tasarıma neden uyar"}, {"id": "setup", "label": "OpenCode'u tasarım için kurun (sıfırdan)"}, {"id": "screenshot-workflow", "label": "Ekran görüntüsünden UI'a iş akışı"}, {"id": "extend", "label": "AGENTS.md, MCP ve paylaşılabilir oturumlar"}, {"id": "vs", "label": "OpenCode, Codex, Claude Code ve Cursor karşılaştırması"}, {"id": "pitfalls", "label": "Tuzaklar ve “AI çöplüğü” görünümü"}, {"id": "open-design", "label": "Open Design içinde OpenCode ile tasarım"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-opencode", "heading": "OpenCode gerçekte nedir", "blocks": [{"kind": "p", "text": "OpenCode, SST'nin (Anomaly Innovations) arkasındaki ekip tarafından sürdürülen, terminal için inşa edilmiş açık kaynaklı bir AI kodlama ajanıdır. Reponuzu okur, komutları çalıştırır, dosyaları düzenler ve büyük bir dil modeliyle konuşur — ama sağlayıcıya bağlı ajanların aksine, kendi modelini sunmaz. Onu istediğiniz herhangi bir sağlayıcıya ve modele yönlendirir ve kendi anahtarınızı getirirsiniz."}, {"kind": "p", "text": "Aynı motorun üzerinde bir masaüstü uygulaması ve IDE eklentileriyle birlikte bir terminal UI'sı (TUI) olarak çalışır. Kaputun altında bir istemci/sunucu mimarisi kullanır, böylece işi yapan ajan, onu sürdüğünüz yüzeyden ayrıştırılmıştır. İki yerleşik ajan — build ve plan — Tab tuşuyla geçiş yapar."}, {"kind": "steps", "items": [{"label": "Modelden bağımsız", "body": "Modeller ve sağlayıcılar, açık bir katalog olan models.dev'den gelir. Bunları opencode.json içinde bir provider/model-id dizesiyle yapılandırır ve yüklenmesini istemediğiniz sağlayıcıları devre dışı bırakabilirsiniz — böylece aynı tasarım iş akışı Anthropic, OpenAI, Google, OpenRouter, yerel modeller ve daha fazlasında çalışır."}, {"label": "Talimat dosyası", "body": "OpenCode, proje kuralları için projenizdeki bir AGENTS.md dosyasını (araçlar arası standart, CLAUDE.md ile de uyumlu) okur — tasarım kurallarınızı kodlamak için doğal yer. Bir tane oluşturmak için /init çalıştırın."}, {"label": "Genişletilebilir", "body": "LSP entegrasyonunu, MCP sunucularını, temaları, kısayol tuşlarını ve özel komutları destekler, ayrıca işbirliği için paylaşılabilir oturum bağlantıları sunar."}]}, {"kind": "ul", "items": ["Sürdüren: SST / Anomaly Innovations (açık kaynaklı proje)", "Kimlik bilgisi: kendi model sağlayıcı API anahtar(lar)ınız — BYOK, sağlayıcı kilidi yok", "Lisans: MIT, açık kaynak"]}]}, {"id": "why-design", "heading": "Açık, her-model ajanı tasarım çalışmasına neden uyar", "blocks": [{"kind": "p", "text": "OpenCode'un, bir sağlayıcı ajanı gibi tek bir “tasarım modeli” yoktur — ve asıl mesele de budur. Modelden bağımsız ve açık olduğundan, aynı tasarım iş akışını şu anda frontend'de en iyi olan modelde çalıştırabilir, sonra değiştirebilir veya yerel bir modele geri dönebilirsiniz, hepsi kurulumunuzu değiştirmeden."}, {"kind": "p", "text": "Ama model seçimi tek başına zevk satın almaz. Her kodlama ajanı gibi, OpenCode da ona kısıtlar vermediğiniz sürece jenerik UI üretir. İyi tasarım çıktısı, sağladığınız üç girdiden gelir."}, {"kind": "steps", "items": [{"label": "Bir tasarım sistemi", "body": "Ajanın yeniden kullandığı gerçek token'lar, ilkeller ve kurallar, böylece çıktı jenerik bir görünüme dönmek yerine bir markayla eşleşir."}, {"label": "Estetik bir skill", "body": "Gerçek bir zevki dayatan özenle seçilmiş bir skill — ölçülü hareket, marka öncelikli hiyerarşi, en fazla iki yazı tipi ve bir vurgu rengi — ve ajanın oluşturmadan önce bir yöne bağlanmasını sağlar."}, {"label": "Somut referanslar", "body": "Gerçek referans görseller ve birden çok durum (masaüstü ve mobil, hover, boş, yükleniyor), tek bir hero görseli değil."}]}, {"kind": "image", "src": "/agents/opencode-design/opencode-design-taste-triangle.webp", "alt": "Tasarım sistemi, skill ve referans görselin iyi tasarım çıktısına yakınsadığını gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir skill ve gerçek referans görseller — hangi modeli çalıştırdığınızdan bağımsız olarak."}, {"kind": "p", "text": "Ders: OpenCode size model özgürlüğü verir, ama zevk yine de özenle seçilmiş bir tasarım bağlamından gelir. Open Design tam olarak bu girdileri paketler; ikisinin neden birbirine uyduğunun nedeni de budur — her ikisi de açık kaynaklı ve yerel önceliklidir (daha fazlası aşağıda)."}]}, {"id": "setup", "heading": "OpenCode'u tasarım çalışması için sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden, UI oluşturabilen ve doğrulayabilen bir OpenCode'a giden tam yol şudur."}, {"kind": "code", "lang": "bash", "code": "# 1. Install OpenCode\ncurl -fsSL https://opencode.ai/install | bash\n# or: npm i -g opencode-ai@latest\n# or: brew install sst/tap/opencode\n\n# 2. Start the TUI in your project, then authenticate your provider\nopencode          # then run /login and pick your provider + paste your key\n\n# 3. Generate project context\nopencode          # inside your project, run /init to create AGENTS.md\n\n# 4. Pick your model (any provider, via models.dev)\n#    set \"provider/model-id\" in opencode.json or switch in the TUI\n\n# 5. Add an MCP server (optional, e.g. for design handoff)\n#    configure it under the \"mcp\" key in opencode.json"}, {"kind": "image", "src": "/agents/opencode-design/opencode-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: kur, sağlayıcı anahtarınızla kimlik doğrula, AGENTS.md yapılandır, bir skill ekle, doğrula", "caption": "Kurulum sırası: kur → kimlik doğrula (sağlayıcı anahtarınız) → AGENTS.md yapılandır → bir skill ekle → gerçek bir tarayıcıda doğrula."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı AGENTS.md (veya ondan referans verilen bir DESIGN.md) içine koyun, böylece çıktı jenerik bir görünüme dönmek yerine bir markayla eşleşsin. opencode.json içindeki instructions seçeneği, glob'lar aracılığıyla ek kural dosyalarına işaret edebilir."}, {"label": "Yetenekli bir model seçin", "body": "OpenCode modelden bağımsız olduğundan, tasarım geçişi için şu anda frontend'de en güçlü olan sağlayıcı/modeli seçin — ve iş akışınızın geri kalanını değişmeden bırakın."}]}]}, {"id": "screenshot-workflow", "heading": "Ekran görüntüsünden UI'a iş akışı", "blocks": [{"kind": "p", "text": "Herhangi bir ajanla en yüksek kaldıraçlı tasarım döngüsü, bir referans görseli çalışan, duyarlı bir UI'a dönüştürmek ve eşleşene kadar yinelemektir. Aynı beş adımlı biçim OpenCode'da da geçerlidir."}, {"kind": "ol", "items": ["Sahip olduğunuz en net görsel referanslardan başlayın — ve yalnızca tek bir hero görseli değil, birden çok durumu (masaüstü ve mobil, hover, boş, yükleniyor) dahil edin.", "Komutta spesifik olun; belirsiz komutlar jenerik UI üretir.", "Bir tasarım sistemi hazırlayın ve OpenCode'a token'ların ve kanonik ilkellerin nerede yaşadığını söyleyin (AGENTS.md içinde).", "Bir dev sunucusu çalıştırın ve ajanın gerçek bir tarayıcıda işlemesini sağlayın, sonucu kontrol etmek için kırılma noktalarına yeniden boyutlandırarak.", "OpenCode'un uygulamasını ekran görüntüleriyle karşılaştırmasını sağlayarak yineleyin — yalnızca derlendiğini onaylamasın."]}, {"kind": "p", "text": "TUI'da çalışma dizininizin bulanık bir aramasını yapmak için dosyalara @ ile referans verin, satır içi shell komutlarını başta bir ! ile çalıştırın ve eylemleri / komutlarıyla sürün. Ardından somut kısıtlarla komut verin:"}, {"kind": "code", "lang": "bash", "code": "opencode\n# in the TUI:\n> @reference-desktop.png @reference-mobile.png\n  Implement this design in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from AGENTS.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Run the dev server, open it in a browser, and iterate until the\n  UI matches the references across breakpoints."}, {"kind": "p", "text": "Komutları küçük ve odaklı tutun, iyi yinelemeleri commit edin ve kötü olanları geri alın (geri aldığınızda OpenCode'a söyleyin), böylece her geçiş temiz bir temel üzerine inşa edilsin."}]}, {"id": "extend", "heading": "AGENTS.md, MCP ve paylaşılabilir oturumlar", "blocks": [{"kind": "p", "text": "Üç genişletme noktası, OpenCode'u sürekli tasarım çalışması için pratik kılar ve üçü de açık bir tasarım iş akışına temizce eşlenir."}, {"kind": "steps", "items": [{"label": "AGENTS.md kuralları", "body": "Proje kuralları, repo kökündeki bir AGENTS.md içinde yaşar (veya ~/.config/opencode/AGENTS.md içindeki global kurallar). Her çalıştırmada okunan, tasarım kurallarınız için kalıcı evdir ve diğer ajanların kullandığı CLAUDE.md dosyalarıyla uyumludur."}, {"label": "MCP sunucuları", "body": "OpenCode, mcp anahtarı altında yapılandırılan hem yerel (command) hem de uzak (URL) MCP sunucularını destekler — yalnızca OpenCode'da değil, ajanlar arasında çalışan tasarım bağlamı ve harici araçları getirmenin taşınabilir yolu."}, {"label": "Paylaşılabilir oturumlar", "body": "/share komutu, işbirliği veya inceleme için bir konuşmaya genel bir bağlantı oluşturur ve /unshare onu iptal eder — bir tasarım geçişi üzerine geri bildirim almak için kullanışlıdır."}]}, {"kind": "p", "text": "Bunlar taşınabilir, çok ajanlı yeteneklerdir — tam olarak Open Design'ın, her proje başına yeniden oluşturmak yerine düzenlemek için inşa edildiği türden şeyler."}]}, {"id": "vs", "heading": "Tasarım için OpenCode, Codex, Claude Code ve Cursor", "blocks": [{"kind": "p", "text": "Tasarım çalışması için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler bunları üst üste yığar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["OpenCode", "Açık kaynaklı ve modelden bağımsız; tek bir terminal iş akışının arkasında herhangi bir sağlayıcı çalıştırın", "BYOK özgürlüğü, model değiştirme, tamamen açık ve yerel öncelikli kurulumlar"], ["Codex", "Bir frontend skill'i ile güçlü görsel cila; görsel anlama", "Devredilen asenkron, sandbox'lanmış derlemeler, taşınabilir AGENTS.md kuralları"], ["Claude Code", "Spesifik tasarım kararları (hex, boşluk, tipografi) ve kod tabanının farkında UX", "Frontend akıl yürütmesi ve geniş bağlamlı yeniden düzenlemeler"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"]]}, {"kind": "p", "text": "Tekrarlanan topluluk kararı, zevkin insanlardan geldiğidir: hepsi skill'ler, referanslar ve kısıtlar olmadan jenerik bir estetiğe varsayılan olarak kayar. Çözülmesi gereken asıl sorun budur — ve bu sorun, model biçimli değil, tasarım aracı biçimlidir; OpenCode gibi açık bir ajanın açık bir tasarım katmanıyla bu kadar iyi eşleşmesinin nedeni de tam olarak budur."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “AI çöplüğü” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "AI tarafından üretilen tasarımla ilgili en yaygın şikayet, jenerik görünmesidir — yumuşak degradeler, yüzen paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir AI yaptı diye bağıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında bozuk mobil düzenler ve UI metnine sızan talimatlar yer alır. Bunların hiçbiri OpenCode'a özgü değildir; herhangi bir ajan özenle seçilmiş bir tasarım bağlamı olmadan çalıştığında olan budur."}, {"kind": "steps", "items": [{"label": "Estetik bir skill ekleyin", "body": "Özenle seçilmiş bir tasarım skill'i, ajanı varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Gerçek bir tarayıcıda doğrulayın", "body": "Kırılma noktaları boyunca işleyin ve kendi kendini kontrol edin, böylece düzenler mobilde sessizce bozulmasın."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki en büyük tek kaldıraçtır."}, {"label": "Kuralları AGENTS.md içinde kodlayın", "body": "“hero kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Her hafifletmenin, hangi modeli çalıştırdığınızdan bağımsız olarak, ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı zahmettir."}]}, {"id": "open-design", "heading": "Open Design içinde OpenCode ile tasarım", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. OpenCode'u birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi, yapılandırılmış bir render hattı ve yerel bir masaüstü UI'sı ile sarmalar — böylece herhangi bir ajanı iyi yapan tasarım bağlamı, her seferinde elle bir araya getirilmek yerine ilk çalıştırmadan itibaren oradadır. Her iki proje de açık kaynaklı ve yerel önceliklidir, bu da eşleşmeyi doğal bir uyum haline getirir."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak OpenCode'u seçin.", "Kendi model sağlayıcı API anahtarınızla (BYOK) kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy'lenmez.", "Herhangi bir sağlayıcı ve model seçin, artı bir tasarım sistemi ve bir skill, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları üretin.", "Her artefakt ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi reponuzda yaşar."]}, {"kind": "p", "text": "Aynı OpenCode ajanı, aynı model özgürlüğü — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0'dır, bu yüzden çalışmanız veya kimlik bilgileriniz hakkında hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "OpenCode gerçekten tasarım çalışması yapabilir mi?", "text": "Evet — bağlamda estetik bir skill, bir tasarım sistemi ve gerçek referans görsellerle OpenCode üretim kalitesinde, duyarlı UI üretir ve bunu bir tarayıcıda doğrulayabilir. Modelden bağımsız olduğundan, şu anda frontend'de en iyi olan hangi modelse onu çalıştırırsınız. Bu özenle seçilmiş bağlam olmadan jenerik bir görünüme dönme eğilimindedir; Open Design'ın doldurduğu boşluk da budur."}, {"name": "Tasarım için OpenCode ile hangi modeli kullanmalıyım?", "text": "Hangisini isterseniz — OpenCode, models.dev aracılığıyla sağlayıcıdan bağımsızdır, böylece Anthropic, OpenAI, Google, OpenRouter veya yerel modelleri aynı iş akışının arkasında çalıştırabilir ve istediğiniz zaman değiştirebilirsiniz. Tasarım çıktısının kalitesi, modelden çok daha fazla skill'inize, tasarım sisteminize ve referanslarınıza bağlıdır."}, {"name": "Open Design, OpenCode (SST) ekibi tarafından mı yapıldı?", "text": "Hayır. Open Design, OpenCode'u bir ajan olarak entegre eden bağımsız bir açık kaynaklı projedir. OpenCode'u yerel öncelikli, açık bir skill ve tasarım sistemi kütüphanesiyle tamamlar."}, {"name": "OpenCode ile tasarım yapmak için özel bir aboneliğe ihtiyacım var mı?", "text": "Hayır — OpenCode BYOK'tur. Kendi model sağlayıcı API anahtarınızı getirirsiniz ve Open Design kimlik bilgilerinizi asla proxy'lemez. Sağlayıcı kilidi yoktur."}, {"name": "Frontend tasarımı için OpenCode mu, Codex mi yoksa Claude Code mu?", "text": "Hepsi güçlüdür ve birçok ekip bunları üst üste yığar. OpenCode'un üstünlüğü tamamen açık kaynaklı ve modelden bağımsız olmasıdır; Codex devredilen, sandbox'lanmış derlemelerde öne çıkar; Claude Code spesifik, kod tabanının farkında tasarım kararlarıyla bilinir. Open Design, tasarım iş akışınızı değiştirmeden ajanlar arasında geçiş yapmanızı sağlar."}, {"name": "OpenCode'u tasarım bağlamı için nasıl genişletirim?", "text": "Kuralları AGENTS.md içinde kodlayın, taşınabilir araçlar ve tasarım bağlamı için mcp anahtarı altına MCP sunucuları ekleyin ve inceleme için paylaşılabilir oturumları kullanın. Open Design, özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi sunar, böylece proje başına kurulumu atlarsınız."}, {"name": "Open Design, OpenCode veya SST ile bağlantılı mı?", "text": "Hayır. OpenCode, SST (Anomaly Innovations) tarafından sürdürülen açık kaynaklı bir projedir; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynaklı projedir."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel önceliklidir. Dosyalarınız, artefaktlarınız ve DESIGN.md'niz kendi reponuzda kalır ve model sağlayıcı kimlik bilgileriniz doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "OpenCode ile açık yolla tasarlayın.", "ctaBody": "Kendi model sağlayıcı anahtarınızı getirin, her dosyayı yerel tutun ve zaten kullandığınız açık ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "OpenCode'u Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'gemini': {
        ...en['gemini']!,
        title: "Tasarım için Gemini CLI — Open Design",
        description: "İnsanlar Google’ın Gemini CLI aracını arayüz ve web tasarımı için nasıl kullanıyor — çok kipli görüntü anlama yeteneği, 1M tokenlık bağlamı, GEMINI.md ve MCP — ve Open Design, Gemini CLI’yi nasıl yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürüyor.",
        breadcrumb: "Gemini CLI",
        label: "Ajan · Gemini CLI",
        heading: "Tasarım için Gemini CLI.",
        lead: "Gemini CLI, Google’ın açık kaynaklı terminal ajanıdır. Çok kipli modelleri ekran görüntülerini okur ve 1M tokenlık bağlamı bütün bir tasarım sistemini içinde tutar; bu da onu gerçek bir tasarım aracı yapar — ona referanslar, kurallar ve bir doğrulama döngüsü verdiğinizde. Open Design onu açık kaynaklı bir tasarım iş akışına bağlar: kendi Google hesabınız ya da API anahtarınız, kendi dosyalarınız, yerel öncelikli.",
        rich: {"heroCtaLead": "Open Design, Gemini CLI’yi yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — kendi Google hesabınız ya da Gemini API anahtarınız, kendi dosyalarınız ve çevresinde özenle seçilmiş bir skill ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "Gemini CLI’yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub’da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Gemini CLI, Google’ın terminal için açık kaynaklı yapay zeka ajanıdır. Özellikle tasarım açısından onu ilginç kılan iki şey var: modelleri güçlü biçimde çok kiplidir, yani bir ekran görüntüsünü okuyup yerleşim, boşluk ve hiyerarşi üzerine akıl yürütür; ve 1M tokenlık bağlam penceresi, bütün bir tasarım sistemini ve kod tabanını aynı anda içinde tutabilir. Doğru referanslar, kurallar ve bir doğrulama döngüsüyle eşleştirildiğinde gerçek, duyarlı bir arayüz kurar — üstelik bir Google hesabıyla ücretsiz başlamak mümkündür. Bu, arayüz, ön uç ve tasarım sistemi çalışmaları için Gemini CLI kullanımına ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya yönelik pratik, uçtan uca bir kılavuzdur.", "Gemini CLI’nin gerçekte ne olduğunu, çok kipli modellerinin ve devasa bağlamının tasarıma neden uyduğunu, sıfırdan nasıl kurulacağını, ekran görüntüsünden arayüze döngüyü, GEMINI.md ile MCP’nin onu nasıl genişlettiğini, Codex, Claude Code ve Cursor ile nasıl karşılaştırıldığını, yapay zeka çıktısını sıradan gösteren tuzakları ve Open Design’ın açık, yerel öncelikli bir tasarım katmanı olarak aradaki boşluğu nasıl kapattığını kapsar — ikisi de açık kaynaklı olduğundan ve kendi makinenizde çalıştığından, doğal bir eşleşme."], "heroImage": {"src": "/agents/gemini-design/gemini-design-hero.webp", "alt": "Gemini CLI tasarım geri bildirim döngüsü: bir referans görselini okuyan terminal ajanı, arayüzü işleyen bir tarayıcı ve bir çalışma alanı, geri dönen bir geri bildirim oku ile", "caption": "Çekirdek döngü: Gemini CLI referanslarınızı terminalde okur, arayüzü gerçek bir tarayıcıda kurar ve doğrular, sonra onlara göre yineler — bütün bir tasarım sistemi bağlamda iken."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-gemini-cli", "label": "Gemini CLI gerçekte nedir"}, {"id": "why-design", "label": "Çok kiplilik + devasa bağlam tasarıma neden uyar"}, {"id": "setup", "label": "Tasarım için Gemini CLI’yi kurun (sıfırdan)"}, {"id": "screenshot-workflow", "label": "Ekran görüntüsünden arayüze iş akışı"}, {"id": "extend", "label": "GEMINI.md, MCP ve uzantılar"}, {"id": "vs", "label": "Gemini CLI vs Codex vs Claude Code vs Cursor"}, {"id": "pitfalls", "label": "Tuzaklar ve “yapay zeka döküntüsü” görünümü"}, {"id": "open-design", "label": "Open Design içinde Gemini CLI ile tasarım"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-gemini-cli", "heading": "Gemini CLI gerçekte nedir", "blocks": [{"kind": "p", "text": "Gemini CLI, Google’ın terminal için sunduğu açık kaynaklı (Apache-2.0) bir yapay zeka ajanıdır. Deponuzu okur, dosyaları düzenler, kabuk komutları çalıştırır, web’den içerik çeker ve yanıtları Google Search ile temellendirebilir — yalnızca satırları tamamlamak yerine doğal dildeki görevlerden işi planlar ve doğrular. Aynı motor, VS Code içindeki Gemini Code Assist ajanına da güç verir."}, {"kind": "p", "text": "Tasarım çalışması için iki özellik öne çıkar. Modelleri doğuştan çok kiplidir; bir ekran görüntüsü verebilirsiniz ve gerçek yerleşim üzerine akıl yürütür. Bağlam penceresi ise 1M tokene kadar ulaşır; bu, bütün tasarım sisteminizi, bileşen kütüphanenizi ve referans kümenizi özetleyip silmek yerine aynı anda içinde tutacak kadar büyüktür."}, {"kind": "steps", "items": [{"label": "Bağlam dosyaları", "body": "Gemini CLI, kalıcı proje bağlamı için bir GEMINI.md dosyasını okur — tasarım kurallarınızı, tokenlarınızı ve inceleme kontrol listelerinizi yazmak için doğal yer. Kişisel ve ekip ayarları bunun üstüne katmanlanır."}, {"label": "Yerleşik araçlar + MCP", "body": "Kutudan çıktığı haliyle dosya, kabuk, web-getirme ve Google Search araçlarıyla gelir; ayrıca canlı bir Figma dosyası gibi dış bağlam eklemek için MCP sunucularını (~/.gemini/settings.json içinde yapılandırılır) destekler."}, {"label": "Ücretsiz başlangıç", "body": "Kişisel bir Google hesabıyla oturum açmak, cömert bir ücretsiz Gemini istek katmanı sağlar; ayrıca bir Gemini API anahtarı getirebilir ya da Vertex AI kullanabilirsiniz."}]}, {"kind": "ul", "items": ["Sağlayıcı: Google", "Kimlik bilgisi: Google hesabı (ücretsiz katman) ya da AI Studio’dan Gemini API anahtarı (BYOK) ya da Vertex AI", "Lisans: Apache-2.0, açık kaynak"]}]}, {"id": "why-design", "heading": "Çok kipli modeller ve devasa bağlam tasarıma neden uyar", "blocks": [{"kind": "p", "text": "Gemini CLI’nin tasarımdaki üstünlüğü iki model özelliğinden gelir — ama her ajanda olduğu gibi, zevkin yine de sağlanması gerekir."}, {"kind": "steps", "items": [{"label": "Güçlü çok kipli anlama", "body": "Gemini modelleri doğuştan çok kipli olduğundan ajan referans ekran görüntülerini iyi okur — düzyazı bir tarifle tahmin yürütmek yerine işlenen çıktısını bir görselle karşılaştırır."}, {"label": "1M tokenlık bağlam penceresi", "body": "Büyük bir bağlam, bütün tasarım sisteminin, tokenların ve birçok referans durumunun aynı anda sığması demektir; böylece ajan tek seferlik stiller uydurmak yerine gerçek temel öğelerinizi yeniden kullanır."}, {"label": "GEMINI.md içindeki kurallar", "body": "Bir GEMINI.md (artı Figma MCP sunucusu) ajanı tokenlarınıza, bileşenlerinize ve gerçek spesifikasyonlarınıza yönlendirir; böylece varsayılan bir görünüme değil, bir markaya göre çalışır."}]}, {"kind": "image", "src": "/agents/gemini-design/gemini-design-taste-triangle.webp", "alt": "Tasarım sistemi, skill ve referans görselin iyi tasarım çıktısında birleştiğini gösteren şema", "caption": "Zevk, sizin sağladığınız üç girdiden gelir: bir tasarım sistemi, bir skill ve gerçek referans görseller."}, {"kind": "p", "text": "Çıkarılacak ders, her ajanın öğrettiğiyle aynıdır: Gemini CLI varsayılan olarak zevke sahip değildir. Ona kısıtlamalar verdiğinizde — bir tasarım sistemi, bir estetik skill ve somut referanslar — iyi tasarım üretir. Open Design tam da bu girdileri paketler; ikisinin birbirine uymasının nedeni budur (aşağıda daha fazlası)."}]}, {"id": "setup", "heading": "Tasarım çalışması için Gemini CLI’yi sıfırdan kurun", "blocks": [{"kind": "p", "text": "İşte temiz bir makineden, arayüz kurup doğrulayabilen bir Gemini CLI’ye giden tam yol."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Gemini CLI (Node 20+)\nnpm install -g @google/gemini-cli\n# or run without installing: npx https://github.com/google-gemini/gemini-cli\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\ngemini            # sign in with your Google account, or set GEMINI_API_KEY\n\n# 3. Generate project context\n/init             # scaffolds a GEMINI.md for this project\n\n# 4. Wire the Figma MCP server (optional, for design handoff)\n#    add it under \"mcpServers\" in ~/.gemini/settings.json"}, {"kind": "image", "src": "/agents/gemini-design/gemini-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: yükle, kimlik doğrula, GEMINI.md yapılandır, bir skill ekle, doğrula", "caption": "Kurulum sırası: yükle → kimlik doğrula → GEMINI.md yapılandır → bir skill ekle → tarayıcı doğrulamasını etkinleştir."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı yazın", "body": "Tokenlarınızı, temel öğelerinizi ve kurallarınızı GEMINI.md içine koyun ve Gemini’yi onlara yönlendirin; böylece çıktı sıradan bir görünüme düşmek yerine bir markayla eşleşir."}, {"label": "Tarayıcı doğrulaması ekleyin", "body": "Bir Playwright ya da tarayıcı MCP’si bağlayın; böylece Gemini gerçek bir tarayıcıda işler ve yalnızca derlemenin geçtiğini onaylamak yerine çıktısını farklı kırılma noktalarında denetler."}]}]}, {"id": "screenshot-workflow", "heading": "Ekran görüntüsünden arayüze iş akışı", "blocks": [{"kind": "p", "text": "Gemini CLI ile en yüksek getirili tasarım döngüsü, bir referans görselini çalışan, duyarlı bir arayüze dönüştürmek ve eşleşene dek yinelemektir — çıktıyı referansla karşılaştırmak için çok kipli modele dayanarak."}, {"kind": "ol", "items": ["Elinizdeki en net görsel referanslarla başlayın — ve tek bir kahraman görselle değil, birden çok durumu (masaüstü ve mobil, üzerine gelme, boş, yükleniyor) dahil edin.", "İstemde belirgin olun; belirsiz istemler güçlü bir modelle bile sıradan arayüz üretir.", "Tasarım sisteminizi ve kurallarınızı GEMINI.md içinde tutun ve Gemini’ye tokenların ve kanonik temel öğelerin nerede olduğunu söyleyin.", "Bir dev sunucusu çalıştırın ve Gemini’ye gerçek bir tarayıcıda işletip kırılma noktalarına yeniden boyutlandırarak sonucu kontrol ettirin.", "Gemini’ye uygulamasını yalnızca derlendiğini onaylamak yerine ekran görüntüleriyle karşılaştırtarak yineleyin."]}, {"kind": "p", "text": "Bir görseli isteme eklemek için @ ile referans verin, ardından somut kısıtlamalar verin:"}, {"kind": "code", "lang": "bash", "code": "gemini\n# in the prompt:\n> @reference-desktop.png @reference-mobile.png\n  Implement this design in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from GEMINI.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Render it in the browser and iterate until it matches the references\n  across breakpoints."}, {"kind": "p", "text": "İstemleri küçük ve odaklı tutun, iyi yinelemeleri commit edin ve kötü olanları geri alın (geri aldığınızda Gemini’ye söyleyerek); böylece her geçiş temiz bir temel üzerine kurulur."}]}, {"id": "extend", "heading": "GEMINI.md, MCP ve uzantılar", "blocks": [{"kind": "p", "text": "Üç genişletme noktası, Gemini CLI’yi sürekli tasarım çalışması için kullanışlı kılar ve üçü de açık bir tasarım iş akışına temiz biçimde oturur."}, {"kind": "steps", "items": [{"label": "GEMINI.md bağlamı", "body": "Proje kuralları depo kökündeki bir GEMINI.md içinde yaşar (genel ve ekip katmanlarıyla). Her çalıştırmada okunan, tasarım kurallarınız için kalıcı yuvadır."}, {"label": "MCP sunucuları", "body": "MCP sunucularını ~/.gemini/settings.json altında yapılandırın — tasarım bağlamını ve dış araçları, en çok da Figma MCP sunucusunu, yalnızca Gemini’de değil ajanlar arasında işe yarayacak şekilde taşımak için taşınabilir yol."}, {"label": "Uzantılar ve yerleşik araçlar", "body": "Gemini CLI uzantıları ve yerleşik Google Search, dosya, kabuk ve web-getirme araçları, terminalden çıkmadan referans toplamasını ve doğrulama döngüsünü çalıştırmasını sağlar."}]}, {"kind": "p", "text": "Bunlar taşınabilir, çoklu ajan yetenekleridir — tam olarak Open Design’ın her projede yeniden yaratmak yerine düzenlemek için kurulduğu türden şeyler."}]}, {"id": "vs", "heading": "Tasarım için Gemini CLI vs Codex vs Claude Code vs Cursor", "blocks": [{"kind": "p", "text": "Tasarım çalışması için tek bir kazanan yoktur — her ajanın farklı bir güçlü yanı vardır ve deneyimli ekipler onları üst üste yığar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En uygun olduğu iş"], "rows": [["Gemini CLI", "Güçlü çok kipli görüntü anlama ve 1M tokenlık bağlam; ücretsiz katmanlı açık kaynak", "Ekran görüntüsü ağırlıklı işler ve bütün bir tasarım sistemini bağlamda tutmak"], ["Codex", "Ön uç skill’iyle güçlü görsel cila; korumalı asenkron derlemeler", "Devredilen asenkron derlemeler ve taşınabilir AGENTS.md kuralları"], ["Claude Code", "Belirli tasarım kararları (hex, boşluk, tipografi) ve kod tabanı farkında UX", "Ön uç akıl yürütme ve büyük bağlamlı yeniden düzenlemeler"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel kur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle arayüz çalışması"]]}, {"kind": "p", "text": "Toplulukta sürekli tekrarlanan kanı, zevkin insanlardan geldiğidir: hepsi skill, referans ve kısıtlama olmadan sıradan bir estetiğe düşer. Çözülmesi gereken asıl sorun budur — ve bu model biçiminde değil, tasarım aracı biçimindedir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “yapay zeka döküntüsü” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Yapay zekayla üretilen tasarım hakkındaki en yaygın yakınma, sıradan görünmesidir — yumuşak gradyanlar, havada duran paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir yapay zeka yaptı diye bağıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında bozuk mobil yerleşimler ve arayüz metnine sızan talimatlar yer alır. Bunların hiçbiri yalnızca Gemini CLI’ye özgü değildir; herhangi bir ajan özenle seçilmiş bir tasarım bağlamı olmadan çalıştığında olan şeylerdir."}, {"kind": "steps", "items": [{"label": "Bir estetik skill ekleyin", "body": "Özenle seçilmiş bir tasarım skill’i, ajanı varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Gerçek bir tarayıcıda doğrulayın", "body": "Çok kipli modeli kullanarak farklı kırılma noktalarında işleyip kendini denetleyin; böylece yerleşimler mobilde sessizce bozulmaz."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım tokenları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki en büyük tek kaldıraçtır."}, {"label": "Kuralları GEMINI.md içine yazın", "body": "“Kahraman kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi stil kurallarını ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Dikkat edin: her önlem, ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgilidir. Bu bağlamı elle, her proje için sürdürmek, Open Design’ın ortadan kaldırdığı zahmettir."}]}, {"id": "open-design", "heading": "Open Design içinde Gemini CLI ile tasarım", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. Gemini CLI’yi birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir skill ve tasarım sistemi kütüphanesiyle, yapılandırılmış bir işleme hattıyla ve yerel bir masaüstü arayüzüyle sarmalar — böylece Gemini’yi iyi yapan tasarım bağlamı, her seferinde elle kurulmak yerine ilk çalıştırmadan itibaren oradadır. İkisi de açık kaynaklı ve yerel önceliklidir; bu da eşleşmeyi doğal kılar."}, {"kind": "ol", "items": ["Open Design’ı yükleyin ve ajanınız olarak Gemini CLI’yi seçin.", "Google hesabınız ya da Gemini API anahtarınızla (BYOK) kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden geçirilmez.", "Bir tasarım sistemi ve bir skill seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları üretin.", "Her çıktı ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi deponuzda yaşar."]}, {"kind": "p", "text": "Aynı Gemini CLI ajanı, aynı anahtar — artı çevresinde gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0’dır; bu yüzden çalışmanızla ya da kimlik bilgilerinizle ilgili hiçbir şey makinenizden çıkmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "Gemini CLI gerçekten tasarım işi yapabilir mi?", "text": "Evet — bağlamda bir estetik skill, bir tasarım sistemi ve gerçek referans görseller olduğunda Gemini CLI üretim kalitesinde, duyarlı bir arayüz üretir ve güçlü çok kipli modelleri çıktıyı referanslarla karşılaştırarak doğrular. Bu bağlam olmadan sıradan bir görünüme düşme eğilimindedir; Open Design’ın doldurduğu boşluk da budur."}, {"name": "Gemini CLI ile tasarım yapmak için ödeme yapmam gerekiyor mu?", "text": "Hayır — bir Google hesabıyla oturum açmak cömert bir ücretsiz katman sağlar; ayrıca bir Gemini API anahtarı getirebilir (BYOK) ya da Vertex AI kullanabilirsiniz. Open Design her iki durumda da kimlik bilgilerinizi asla aracı olarak geçirmez."}, {"name": "Gemini CLI’yi özellikle tasarım için iyi kılan nedir?", "text": "İki şey: modelleri güçlü biçimde çok kiplidir, bu yüzden referans ekran görüntülerini iyi okur; ve 1M tokenlık bağlamı, bütün bir tasarım sistemini ve referans kümesini aynı anda tutabilir. İkisi de yardımcı olur — ama zevk yine de sizin sağladığınız tasarım sisteminden, skill’den ve referanslardan gelir."}, {"name": "Ön uç tasarımı için Gemini CLI mi Claude Code mu?", "text": "İkisi de güçlüdür. Claude Code, belirli, kod tabanı farkında tasarım kararlarıyla bilinir; Gemini CLI’nin üstünlüğü ise çok kipli anlama, artı devasa bir bağlam ve ücretsiz bir katmandır. Birçok ekip ikisini de kullanır — Open Design, tasarım iş akışınızı değiştirmeden ajanları değiştirmenize olanak tanır."}, {"name": "Gemini CLI’yi Figma’ya nasıl bağlarım?", "text": "Figma MCP sunucusunu ~/.gemini/settings.json içindeki mcpServers altına ekleyin. Gemini bu sayede gerçek tasarım bağlamını — bileşenler, değişkenler, yerleşim verileri — çekebilir; böylece üretilen kod, kaynağı yaklaştırmak yerine ona uyar."}, {"name": "Open Design, Google ile bağlantılı mı?", "text": "Hayır. Gemini CLI bir Google ürünüdür; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız, açık kaynaklı bir projedir. Gemini, Google’ın ticari markasıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel öncelikli ve Apache-2.0’dır. Dosyalarınız, çıktılarınız ve DESIGN.md’niz kendi deponuzda kalır; Google kimlik bilgileriniz ise doğrudan ajanınız tarafından kullanılır, asla Open Design sunucularına yönlendirilmez."}], "ctaTitle": "Gemini CLI ile açık yoldan tasarlayın.", "ctaBody": "Kendi Google hesabınızı ya da Gemini API anahtarınızı getirin, her dosyayı yerelde tutun ve hâlihazırda kullandığınız ajanın çevresinde özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "Gemini CLI’yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub’da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'copilot': {
        ...en['copilot']!,
        title: "Tasarım için GitHub Copilot CLI — Open Design",
        description: "İnsanlar GitHub Copilot CLI'yi UI ve web tasarımı için nasıl kullanıyor — terminal yerlisi kodlama ajanı, özel talimat dosyaları, MCP desteği ve çoklu model seçimi — ve Open Design, Copilot CLI'yi yerel öncelikli, açık kaynaklı bir tasarım ajanına nasıl dönüştürüyor.",
        breadcrumb: "GitHub Copilot CLI",
        label: "Ajan · GitHub Copilot CLI",
        heading: "Tasarım için GitHub Copilot CLI.",
        lead: "GitHub Copilot CLI, GitHub'ın terminal yerlisi kodlama ajanıdır. Deponuz genelinde plan yapıp düzenleme uygular, Claude ve GPT gibi öncü modeller arasından seçim yapar ve depo talimatlarınızı okur — ki bu da ona referanslar, kurallar ve bir doğrulama döngüsü verdiğinizde onu gerçek bir tasarım aracına dönüştürür. Open Design onu açık kaynaklı bir tasarım iş akışına bağlar: kendi GitHub Copilot aboneliğiniz, kendi dosyalarınız, yerel öncelikli.",
        rich: {"heroCtaLead": "Open Design, GitHub Copilot CLI'yi yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — kendi GitHub Copilot aboneliğiniz, kendi dosyalarınız ve etrafında özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "Copilot CLI'yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["GitHub Copilot CLI, GitHub'ın terminal yerlisi kodlama ajanıdır — Copilot kodlama ajanına güç veren aynı ajansal koşum takımı, komut satırınıza getirilmiştir. Özellikle tasarım açısından onu ilginç kılan iki şey var: depo talimatlarınızı ve AGENTS.md dosyanızı okur, böylece tasarım kurallarınız her çalıştırmada ajanla birlikte hareket eder; ve görev başına Anthropic, OpenAI ve Google'ın öncü modelleri arasından seçim yapmanıza izin verir, böylece belirli bir UI hakkında en iyi muhakeme yapanı seçebilirsiniz. Doğru referanslar, kurallar ve bir doğrulama döngüsüyle eşleştirildiğinde gerçek, duyarlı UI üretir — ve zaten sahip olabileceğiniz Copilot aboneliği üzerinden çalışır. Bu, Copilot CLI'yi UI, ön uç ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya yönelik pratik, uçtan uca bir kılavuzdur.", "Copilot CLI'nin gerçekte ne olduğunu, depo talimatlarının ve model seçiminin tasarıma neden uyduğunu, sıfırdan nasıl kurulacağını, ekran görüntüsünden UI'ye döngüyü, özel talimatların ve MCP'nin onu nasıl genişlettiğini, Codex, Claude Code, Cursor ve Gemini CLI ile nasıl karşılaştırıldığını, yapay zeka çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak boşluğu nasıl kapattığını kapsar — aboneliğiniz ve kimlik bilgileriniz makinenizde kalır, üretimleriniz kendi deponuzda kalır."], "heroImage": {"src": "/agents/copilot-design/copilot-design-hero.webp", "alt": "GitHub Copilot CLI tasarım geri bildirim döngüsü: bir referans görüntüsünü okuyan bir terminal ajanı, UI'yi işleyen bir tarayıcı ve bir çalışma alanı, geri döngü yapan bir geri bildirim okuyla", "caption": "Temel döngü: Copilot CLI referanslarınızı terminalde okur, UI'yi gerçek bir tarayıcıda oluşturup doğrular ve onlara karşı yineler — tasarım kurallarınız depo talimatlarında."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-copilot", "label": "GitHub Copilot CLI gerçekte nedir"}, {"id": "why-design", "label": "Talimatlar + model seçimi tasarıma neden uyar"}, {"id": "setup", "label": "Tasarım için Copilot CLI'yi kurun (sıfırdan)"}, {"id": "screenshot-workflow", "label": "Ekran görüntüsünden UI'ye iş akışı"}, {"id": "extend", "label": "Özel talimatlar, MCP ve uzantılar"}, {"id": "vs", "label": "Copilot CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Tuzaklar ve “yapay zeka çorbası” görünümü"}, {"id": "open-design", "label": "Open Design'da Copilot CLI ile tasarlamak"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-copilot", "heading": "GitHub Copilot CLI gerçekte nedir", "blocks": [{"kind": "p", "text": "GitHub Copilot CLI, GitHub'ın terminal yerlisi kodlama ajanıdır. Deponuzu okur, dosyaları düzenler, kabuk komutları çalıştırır ve GitHub bağlamınızla — sorunlar, çekme istekleri ve depolar — doğrudan çalışır; mevcut GitHub hesabınızla kimliği doğrulanır. GitHub'ın Copilot kodlama ajanıyla aynı ajansal koşum takımıyla çalışır, bu yüzden yalnızca satırları tamamlamak yerine karmaşık görevleri planlar ve yineler. Eylül 2025'te açılan bir genel önizlemenin ardından Şubat 2026'da genel kullanıma ulaştı."}, {"kind": "p", "text": "Tasarım çalışmaları için iki özellik öne çıkar. Özel talimat dosyalarını okur — .github/copilot-instructions.md içindeki depo geneli kurallar ve AGENTS.md — böylece tasarım kurallarınız her çalıştırmada otomatik olarak dahil edilir. Ve birden fazla temel model sağlayıcısını destekler, böylece /model komutuyla görev başına modeli, belirli bir UI hakkında en iyi muhakeme yapan hangisiyse ona değiştirebilirsiniz."}, {"kind": "steps", "items": [{"label": "Talimat dosyaları", "body": "Copilot CLI, .github/copilot-instructions.md içindeki depo talimatlarını, .github/instructions altındaki yola özgü dosyaları ve AGENTS.md'yi okur — tasarım kurallarınızı, token'larınızı ve inceleme kontrol listelerinizi kodlamak için doğal yer."}, {"label": "Yerleşik araçlar + MCP", "body": "GitHub'ın MCP sunucusu yerleşik olarak gelir ve dosya ile kabuk araçlarını çalıştırır; ayrıca canlı bir Figma dosyası gibi harici bağlam için /mcp add ile (~/.copilot altında mcp-config.json'da saklanır) özel MCP sunucuları ekleyebilirsiniz."}, {"label": "Model seçimi", "body": "Anthropic, OpenAI ve Google'ın öncü modelleri arasından seçim yapmak için /model komutunu kullanın — görev başına değiştirerek, tümü mevcut Copilot aboneliğinizde."}]}, {"kind": "ul", "items": ["Sağlayıcı: GitHub", "Kimlik bilgisi: etkin bir GitHub Copilot aboneliği (Pro, Pro+, Business veya Enterprise)", "Kurulum: npm install -g @github/copilot, ardından copilot çalıştırın"]}]}, {"id": "why-design", "heading": "Depo talimatları ve model seçimi tasarıma neden uyar", "blocks": [{"kind": "p", "text": "Copilot CLI'nin tasarım avantajı iki özellikten gelir — ama her ajanda olduğu gibi, zevkin yine de sağlanması gerekir."}, {"kind": "steps", "items": [{"label": "Depoyla birlikte hareket eden kurallar", "body": "Copilot CLI .github/copilot-instructions.md ve AGENTS.md'yi otomatik okuduğundan, token'larınız, ilkelleriniz ve inceleme kurallarınız her çalıştırmada bağlamdadır — ajan varsayılan bir görünüm yerine bir markaya karşı çalışır."}, {"label": "Görev başına doğru modeli seçin", "body": "Anthropic, OpenAI ve Google genelinde model seçimi, belirli bir düzen hakkında en iyi muhakeme yapan modele uzanabileceğiniz, ardından sonraki görev için değiştirebileceğiniz anlamına gelir — iş akışınızı değiştirmeden."}, {"label": "MCP aracılığıyla gerçek spesifikasyonlar", "body": "Yerleşik GitHub MCP sunucusu artı bir Figma MCP sunucusu, ajanı token'larınıza, bileşenlerinize ve gerçek spesifikasyonlarınıza yönlendirir, böylece yaklaşık değer yerine kaynaktan inşa eder."}]}, {"kind": "image", "src": "/agents/copilot-design/copilot-design-taste-triangle.webp", "alt": "Tasarım sistemi, beceri ve referans görüntüsünün iyi tasarım çıktısında birleştiğini gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir beceri ve gerçek referans görüntüleri."}, {"kind": "p", "text": "Ders, her ajanın öğrettiğiyle aynıdır: Copilot CLI varsayılan olarak zevke sahip değildir. Ona kısıtlamalar verdiğinizde — bir tasarım sistemi, estetik bir beceri ve somut referanslar — iyi tasarım üretir. Open Design tam olarak bu girdileri paketler, bu yüzden ikisi birbirine uyar (aşağıda daha fazlası)."}]}, {"id": "setup", "heading": "Tasarım çalışmaları için Copilot CLI'yi sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden, UI oluşturup doğrulayabilen bir Copilot CLI'ye giden tam yol burada."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Copilot CLI (Node.js required)\nnpm install -g @github/copilot\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\ncopilot           # run /login and follow the prompts to sign in\n\n# 3. Choose a model for the task\n#    inside the session:\n/model            # pick a frontier model from Anthropic, OpenAI, or Google\n\n# 4. Add custom instructions and the Figma MCP server (optional)\n#    write .github/copilot-instructions.md or AGENTS.md\n/mcp add          # add the Figma MCP server for design handoff"}, {"kind": "image", "src": "/agents/copilot-design/copilot-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: kur, kimlik doğrula, model seç, talimatları yapılandır, doğrula", "caption": "Kurulum sırası: kur → kimlik doğrula → model seç → talimatları yaz → tarayıcı doğrulamasını etkinleştir."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı .github/copilot-instructions.md veya AGENTS.md içine koyun, böylece çıktı jenerik bir görünüme varsayılan olmak yerine bir markayla eşleşir."}, {"label": "Tarayıcı doğrulaması ekleyin", "body": "Bir Playwright veya tarayıcı MCP'si bağlayın, böylece Copilot gerçek bir tarayıcıda işler ve yalnızca derlemenin geçtiğini onaylamak yerine çıktısını kırılma noktaları genelinde kontrol eder."}]}]}, {"id": "screenshot-workflow", "heading": "Ekran görüntüsünden UI'ye iş akışı", "blocks": [{"kind": "p", "text": "Copilot CLI ile en yüksek kaldıraçlı tasarım döngüsü, bir referans görüntüyü çalışan, duyarlı UI'ye dönüştürmek ve eşleşene kadar yinelemektir — çıktıyı referansla karşılaştırmak için güçlü bir çok modlu modele dayanarak."}, {"kind": "ol", "items": ["Elinizdeki en net görsel referanslardan başlayın — ve yalnızca tek bir kahraman görüntü değil, birden fazla durum (masaüstü ve mobil, hover, boş, yükleniyor) ekleyin.", "İstemde belirgin olun; belirsiz istemler güçlü bir modelle bile jenerik UI üretir.", "Tasarım sisteminizi ve kurallarınızı .github/copilot-instructions.md veya AGENTS.md içinde tutun ve Copilot'a token'ların ve standart ilkellerin nerede olduğunu söyleyin.", "Bir geliştirme sunucusu çalıştırın ve Copilot'un sonucu kontrol etmek için kırılma noktalarına yeniden boyutlandırarak gerçek bir tarayıcıda işlemesini sağlayın.", "Copilot'un uygulamasını ekran görüntülerine geri karşılaştırmasını sağlayarak yineleyin — yalnızca derlendiğini onaylamak değil."]}, {"kind": "p", "text": "Copilot'u referans görüntülerinize yönlendirin ve somut kısıtlamalar verin; çalışmadan önce her dosya düzenlemesini veya komutu onayınız için önizler:"}, {"kind": "code", "lang": "bash", "code": "copilot\n# in the prompt:\n> Implement the design in reference-desktop.png and reference-mobile.png\n  in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens described in\n  .github/copilot-instructions.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Render it in the browser and iterate until it matches the references\n  across breakpoints."}, {"kind": "p", "text": "İstemleri küçük ve odaklı tutun, iyi yinelemeleri commit edin ve kötüleri geri alın (geri aldığınızda Copilot'a söyleyerek), böylece her geçiş temiz bir temel üzerine inşa edilir."}]}, {"id": "extend", "heading": "Özel talimatlar, MCP ve uzantılar", "blocks": [{"kind": "p", "text": "Üç uzantı noktası Copilot CLI'yi sürekli tasarım çalışmaları için pratik kılar ve üçü de açık bir tasarım iş akışına temiz bir şekilde eşlenir."}, {"kind": "steps", "items": [{"label": "Özel talimatlar", "body": "Depo kuralları .github/copilot-instructions.md içinde yaşar (.github/instructions altındaki yola özgü dosyalar ve AGENTS.md ile birlikte). Bunlar, her çalıştırmada otomatik olarak dahil edilen, tasarım kurallarınızın kalıcı yuvasıdır."}, {"label": "MCP sunucuları", "body": "Copilot CLI, GitHub'ın MCP sunucusuyla yerleşik gelir ve /mcp add ile (~/.copilot altında mcp-config.json'da saklanır) özel sunucular eklemenize izin verir — en alakalı olarak Figma MCP sunucusu olmak üzere, yalnızca Copilot'ta değil ajanlar genelinde çalışan, tasarım bağlamını getirmenin taşınabilir yolu."}, {"label": "Uzmanlaşmış ajanlar ve yerleşik araçlar", "body": "Copilot CLI'nin uzmanlaşmış modları — kod tabanı keşfi, derleme ve test çalıştırma, değişiklik incelemesi ve planlama için — artı dosya ve kabuk araçları, terminalden ayrılmadan referans toplamasına ve doğrulama döngüsünü çalıştırmasına izin verir."}]}, {"kind": "p", "text": "Bunlar taşınabilir, çok ajanlı yeteneklerdir — Open Design'ın proje başına yeniden oluşturmak yerine orkestre etmek için inşa edildiği türden tam olarak budur."}]}, {"id": "vs", "heading": "Tasarım için Copilot CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI", "blocks": [{"kind": "p", "text": "Tasarım çalışmaları için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler onları üst üste koyar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["Copilot CLI", "Copilot aboneliğinizde çoklu model seçimi (Anthropic, OpenAI, Google) ve derin GitHub entegrasyonu", "Görev başına en iyi modeli seçmek ve GitHub deponuza bağlı, talimat odaklı çalışma"], ["Codex", "Ön uç becerisiyle güçlü görsel cila; sandbox'lı eşzamansız derlemeler", "Devredilmiş eşzamansız derlemeler ve taşınabilir AGENTS.md kuralları"], ["Claude Code", "Belirli tasarım kararları (hex, boşluk, tipografi) ve kod tabanından haberdar UX", "Ön uç muhakemesi ve büyük bağlamlı yeniden düzenlemeler"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"], ["Gemini CLI", "Güçlü çok modlu görüntü anlama ve 1M token'lık bir bağlam; ücretsiz katmanlı açık kaynak", "Ekran görüntüsü ağırlıklı çalışma ve bütün bir tasarım sistemini bağlamda tutma"]]}, {"kind": "p", "text": "Tekrarlayan topluluk kanaati, zevkin insanlardan geldiğidir: hepsi beceriler, referanslar ve kısıtlamalar olmadan jenerik bir estetiğe varsayılan olur. Çözülmesi gereken gerçek sorun budur — ve bu, model biçimli değil, tasarım aracı biçimlidir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “yapay zeka çorbası” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Yapay zeka tarafından üretilen tasarım hakkında en yaygın şikayet, jenerik göründüğüdür — yumuşak gradyanlar, yüzen paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir yapay zekanın yaptığını haykıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında bozuk mobil düzenler ve talimatların UI metnine sızması yer alır. Bunların hiçbiri Copilot CLI'ye özgü değildir; herhangi bir ajan özenle seçilmiş bir tasarım bağlamı olmadan çalıştığında olan şeydir."}, {"kind": "steps", "items": [{"label": "Estetik bir beceri ekleyin", "body": "Özenle seçilmiş bir tasarım becerisi, ajanı varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Gerçek bir tarayıcıda doğrulayın", "body": "Bir tarayıcı MCP'siyle kırılma noktaları genelinde işleyin ve öz-denetim yapın, böylece düzenler mobilde sessizce bozulmaz."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki tek en büyük kaldıraçtır."}, {"label": "Kuralları özel talimatlarda kodlayın", "body": "“Kahraman kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu .github/copilot-instructions.md veya AGENTS.md içine koyun."}]}, {"kind": "p", "text": "Her hafifletmenin ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı angaryadır."}]}, {"id": "open-design", "heading": "Open Design içinde Copilot CLI ile tasarlamak", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. GitHub Copilot CLI'yi birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesine, yapılandırılmış bir işleme hattına ve yerel bir masaüstü UI'sine sarar — böylece Copilot'u iyi yapan tasarım bağlamı, her seferinde elle birleştirilmek yerine ilk çalıştırmadan itibaren oradadır. Open Design bağımsız, açık kaynaklı (Apache-2.0) ve yerel önceliklidir, bu yüzden eşleşme uyar: ajan işi yapar, dosyalarınız ve kimlik bilgileriniz sizin kalır."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak GitHub Copilot CLI'yi seçin.", "GitHub Copilot aboneliğinizle kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy yapılmaz.", "Bir tasarım sistemi ve bir beceri seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları oluşturun.", "Her üretim ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi deponuzda yaşar."]}, {"kind": "p", "text": "Aynı Copilot CLI ajanı, aynı abonelik — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Open Design yerel öncelikli ve Apache-2.0'dır, böylece çalışmanız veya kimlik bilgilerinizle ilgili hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "GitHub Copilot CLI gerçekten tasarım çalışması yapabilir mi?", "text": "Evet — bağlamda estetik bir beceri, bir tasarım sistemi ve gerçek referans görüntülerle, Copilot CLI üretim kalitesinde, duyarlı UI üretir ve çıktıyı referanslara karşı en iyi doğrulayan modeli seçebilirsiniz. Bu bağlam olmadan jenerik bir görünüme varsayılan olma eğilimindedir; bu da Open Design'ın doldurduğu boşluktur."}, {"name": "Copilot CLI ile tasarım yapmak için bir aboneliğe ihtiyacım var mı?", "text": "Evet — Copilot CLI etkin bir GitHub Copilot aboneliği (Pro, Pro+, Business veya Enterprise) üzerinde çalışır; kendi anahtarını getir değildir. GitHub hesabınızla kimlik doğrularsınız. Open Design kimlik bilgilerinizi asla proxy yapmaz — aboneliğiniz doğrudan ajanınız tarafından kullanılır."}, {"name": "Copilot CLI'yi özellikle tasarım için iyi yapan nedir?", "text": "İki şey: depo talimatlarını ve AGENTS.md'yi otomatik okur, böylece tasarım kurallarınız depoyla birlikte hareket eder; ve görev başına Anthropic, OpenAI ve Google'ın öncü modelleri arasında geçiş yapmanıza izin verir. Her ikisi de yardımcı olur — ama zevk yine de sağladığınız tasarım sisteminden, beceriden ve referanslardan gelir."}, {"name": "Ön uç tasarımı için Copilot CLI mi Claude Code mu?", "text": "Her ikisi de güçlüdür. Claude Code, belirli, kod tabanından haberdar tasarım kararlarıyla bilinir; Copilot CLI'nin avantajı, sağlayıcılar genelinde model seçimi ve zaten sahip olabileceğiniz bir abonelikte derin GitHub entegrasyonudur. Birçok ekip her ikisini de kullanır — Open Design, tasarım iş akışınızı değiştirmeden ajan değiştirmenize izin verir."}, {"name": "Copilot CLI'yi Figma'ya nasıl bağlarım?", "text": "/mcp add komutuyla Figma MCP sunucusunu ekleyin; ayarlar ~/.copilot altında mcp-config.json'da saklanır. Copilot daha sonra gerçek tasarım bağlamı çekebilir — bileşenler, değişkenler, düzen verileri — böylece üretilen kod yaklaşık değer yerine kaynağa eşleşir."}, {"name": "Open Design GitHub veya Microsoft ile bağlantılı mı?", "text": "Hayır. GitHub Copilot CLI, GitHub'ın bir ürünüdür; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynak projesidir. GitHub Copilot, GitHub, Inc. ve Microsoft'un ticari markasıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel öncelikli ve Apache-2.0'dır. Dosyalarınız, üretimleriniz ve DESIGN.md'niz kendi deponuzda kalır ve GitHub Copilot kimlik bilgileriniz doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "GitHub Copilot CLI ile açık yoldan tasarlayın.", "ctaBody": "GitHub Copilot aboneliğinizi getirin, her dosyayı yerel tutun ve zaten kullandığınız ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "Copilot CLI'yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'qwen': {
        ...en['qwen']!,
        title: "Tasarım için Qwen Code — Open Design",
        description: "İnsanlar Alibaba'nın açık kaynaklı Qwen Code CLI'sini UI ve web tasarımı için nasıl kullanıyor — Qwen3-Coder modelleri, büyük bağlam penceresi, QWEN.md ve MCP — ve Open Design, Qwen Code'u yerel öncelikli, açık kaynaklı bir tasarım ajanına nasıl dönüştürüyor.",
        breadcrumb: "Qwen Code",
        label: "Ajan · Qwen Code",
        heading: "Tasarım için Qwen Code.",
        lead: "Qwen Code, Alibaba'nın Gemini CLI'den uyarlanan ve Qwen3-Coder modelleri için ayarlanan açık kaynaklı terminal ajanıdır. Büyük bağlam penceresi bütün bir tasarım sistemini bir kerede tutar, ki bu da ona referanslar, kurallar ve bir doğrulama döngüsü verdiğinizde onu gerçek bir tasarım aracı yapar. Open Design onu açık kaynaklı bir tasarım iş akışına bağlar: kendi DashScope veya Qwen API anahtarınız, kendi dosyalarınız, yerel öncelikli.",
        rich: {"heroCtaLead": "Open Design, Qwen Code'u yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — kendi DashScope veya Qwen API anahtarınız, kendi dosyalarınız ve etrafında özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "Qwen Code'u Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Qwen Code, Alibaba'nın terminal için açık kaynaklı yapay zeka ajanıdır. Google'ın Gemini CLI'sinden uyarlanmıştır; Qwen3-Coder modellerinden en iyi şekilde yararlanmasını sağlayan ayrıştırıcı düzeyinde ve istem uyarlamalarına sahiptir. Özellikle tasarım açısından onu ilginç kılan iki şey var: güçlü bir ajansal kodlama modelidir, bu yüzden doğal dildeki bir görevden plan yapar, dosyaları düzenler ve derleme ile doğrulama döngüsünü çalıştırır; ve büyük bağlam penceresi bütün bir tasarım sistemini ve kod tabanını bir kerede tutabilir. Doğru referanslar, kurallar ve bir doğrulama döngüsüyle eşleştirildiğinde gerçek, duyarlı UI üretir — ve açık kaynaklı ve BYOK'tur, bu yüzden kendi anahtarınızı getirirsiniz. Bu, Qwen Code'u UI, ön uç ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya yönelik pratik, uçtan uca bir kılavuzdur.", "Qwen Code'un gerçekte ne olduğunu, güçlü bir kodlayıcı modeli artı büyük bir bağlamın tasarıma neden uyduğunu, sıfırdan nasıl kurulacağını, referanstan UI'ye döngüyü, QWEN.md ve MCP'nin onu nasıl genişlettiğini, Codex, Claude Code, Cursor ve Gemini CLI ile nasıl karşılaştırıldığını, yapay zeka çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak boşluğu nasıl kapattığını kapsar — doğal bir eşleşme, çünkü her ikisi de açık kaynaklı ve kendi makinenizde çalışıyor."], "heroImage": {"src": "/agents/qwen-design/qwen-design-hero.webp", "alt": "Qwen Code tasarım geri bildirim döngüsü: bir referans görüntüsünü okuyan bir terminal ajanı, UI'yi işleyen bir tarayıcı ve bir çalışma alanı, geri döngü yapan bir geri bildirim okuyla", "caption": "Temel döngü: Qwen Code referanslarınızı terminalde okur, UI'yi gerçek bir tarayıcıda oluşturup doğrular ve onlara karşı yineler — bütün bir tasarım sistemi bağlamda."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-qwen", "label": "Qwen Code gerçekte nedir"}, {"id": "why-design", "label": "Güçlü bir kodlayıcı modeli + büyük bağlam tasarıma neden uyar"}, {"id": "setup", "label": "Tasarım için Qwen Code'u kurun (sıfırdan)"}, {"id": "screenshot-workflow", "label": "Referanstan UI'ye iş akışı"}, {"id": "extend", "label": "QWEN.md, MCP ve uzantılar"}, {"id": "vs", "label": "Qwen Code vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Tuzaklar ve “yapay zeka çorbası” görünümü"}, {"id": "open-design", "label": "Open Design'da Qwen Code ile tasarlamak"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-qwen", "heading": "Qwen Code gerçekte nedir", "blocks": [{"kind": "p", "text": "Qwen Code, Alibaba'nın terminal için sunduğu açık kaynaklı (Apache-2.0) bir yapay zeka ajanıdır. Deponuzu okur, dosyaları düzenler, kabuk komutları çalıştırır ve web'de çalışır — yalnızca satırları tamamlamak yerine doğal dildeki görevlerden plan yapar ve işi doğrular. Google'ın Gemini CLI'sinden uyarlanmıştır; ajansal kodlama görevlerinde Qwen3-Coder modellerinin kilidini açmak için ayarlanmış ayrıştırıcı düzeyinde ve istem uyarlamalarına sahiptir."}, {"kind": "p", "text": "Tasarım çalışmaları için iki özellik öne çıkar. Yetenekli bir ajansal kodlayıcıdır, bu yüzden bir referansı ve net bir özeti alıp duyarlı UI'yi inşa edebilir, çalıştırabilir ve kendi kendini düzeltebilir. Ve Qwen3-Coder modelleri büyük bir bağlam penceresi taşır; bütün tasarım sisteminizi, bileşen kütüphanenizi ve referans setinizi özetleyerek elemek yerine bir kerede tutacak kadar büyüktür."}, {"kind": "steps", "items": [{"label": "Bağlam dosyaları", "body": "Qwen Code, kalıcı proje bağlamı için bir QWEN.md dosyasını okur — tasarım kurallarınızı, token'larınızı ve inceleme kontrol listelerinizi kodlamak için doğal yer. Kişisel ve proje ayarları üzerine katmanlanır."}, {"label": "Yerleşik araçlar + MCP", "body": "Dosya, kabuk ve web araçlarını kutudan çıktığı gibi getirir ve canlı bir Figma dosyası gibi harici bağlam eklemek için MCP sunucularını destekler (~/.qwen/settings.json içinde mcpServers altında yapılandırılır)."}, {"label": "Başlamak için BYOK", "body": "Kendi anahtarınızı getirirsiniz — bir DashScope (Alibaba Cloud Model Studio) API anahtarı veya herhangi bir OpenAI uyumlu uç nokta ya da ModelScope — ve settings.json içinde yapılandırırsınız."}]}, {"kind": "ul", "items": ["Sağlayıcı: Alibaba", "Kimlik bilgisi: DashScope / Qwen API anahtarı (BYOK) veya OpenAI uyumlu uç nokta / ModelScope", "Lisans: Apache-2.0, açık kaynak (Gemini CLI'den uyarlanmış)"]}]}, {"id": "why-design", "heading": "Güçlü bir kodlayıcı modeli ve büyük bir bağlam tasarıma neden uyar", "blocks": [{"kind": "p", "text": "Qwen Code'un tasarım avantajı iki özellikten gelir — ama her ajanda olduğu gibi, zevkin yine de sağlanması gerekir."}, {"kind": "steps", "items": [{"label": "Güçlü ajansal kodlama", "body": "Qwen3-Coder modelleri ajansal görevler için ayarlanmıştır, böylece ajan plan yapar, düzenler, derlemeyi çalıştırır ve kendi kendini düzeltir — net bir referansı ve özeti tek seferlik bir tahmin yerine duyarlı işaretlemeye dönüştürür."}, {"label": "Büyük bir bağlam penceresi", "body": "Qwen3-Coder'ın büyük bağlamı, bütün tasarım sisteminin, token'ların ve birçok referans durumunun bir kerede sığması anlamına gelir, böylece ajan tek seferlik stiller icat etmek yerine gerçek ilkellerinizi yeniden kullanır."}, {"label": "QWEN.md içindeki kurallar", "body": "Bir QWEN.md (artı Figma MCP sunucusu) ajanı token'larınıza, bileşenlerinize ve gerçek spesifikasyonlarınıza yönlendirir, böylece varsayılan bir görünüm yerine bir markaya karşı çalışır."}]}, {"kind": "image", "src": "/agents/qwen-design/qwen-design-taste-triangle.webp", "alt": "Tasarım sistemi, beceri ve referans görüntüsünün iyi tasarım çıktısında birleştiğini gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir beceri ve gerçek referans görüntüleri."}, {"kind": "p", "text": "Ders, her ajanın öğrettiğiyle aynıdır: Qwen Code varsayılan olarak zevke sahip değildir. Ona kısıtlamalar verdiğinizde — bir tasarım sistemi, estetik bir beceri ve somut referanslar — iyi tasarım üretir. Open Design tam olarak bu girdileri paketler, bu yüzden ikisi birbirine uyar (aşağıda daha fazlası)."}]}, {"id": "setup", "heading": "Tasarım çalışmaları için Qwen Code'u sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden, UI oluşturup doğrulayabilen bir Qwen Code'a giden tam yol burada."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Qwen Code (Node 22+)\nnpm install -g @qwen-code/qwen-code@latest\n# or: brew install qwen-code\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\nqwen              # run /auth, or set a key in ~/.qwen/settings.json\n\n# 3. Configure a DashScope (OpenAI-compatible) key in settings.json\n#    baseUrl: https://dashscope.aliyuncs.com/compatible-mode/v1\n#    model:   qwen3-coder-plus   (set DASHSCOPE_API_KEY)\n\n# 4. Add a QWEN.md and wire the Figma MCP server (optional)\n#    add MCP under \"mcpServers\" in ~/.qwen/settings.json"}, {"kind": "image", "src": "/agents/qwen-design/qwen-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: kur, kimlik doğrula, QWEN.md yapılandır, bir beceri ekle, doğrula", "caption": "Kurulum sırası: kur → kimlik doğrula → QWEN.md yapılandır → bir beceri ekle → tarayıcı doğrulamasını etkinleştir."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı QWEN.md içine koyun ve Qwen Code'u onlara yönlendirin, böylece çıktı jenerik bir görünüme varsayılan olmak yerine bir markayla eşleşir."}, {"label": "Tarayıcı doğrulaması ekleyin", "body": "Bir Playwright veya tarayıcı MCP'si bağlayın, böylece Qwen Code gerçek bir tarayıcıda işler ve yalnızca derlemenin geçtiğini onaylamak yerine çıktısını kırılma noktaları genelinde kontrol eder."}]}]}, {"id": "screenshot-workflow", "heading": "Referanstan UI'ye iş akışı", "blocks": [{"kind": "p", "text": "Qwen Code ile en yüksek kaldıraçlı tasarım döngüsü, bir referansı çalışan, duyarlı UI'ye dönüştürmek ve eşleşene kadar yinelemektir — ajanın çıktısını inşa etmesine, işlemesine ve referansla karşılaştırmasına dayanarak."}, {"kind": "ol", "items": ["Elinizdeki en net görsel referanslardan başlayın — ve yalnızca tek bir kahraman görüntü değil, birden fazla durumu (masaüstü ve mobil, hover, boş, yükleniyor) tanımlayın.", "İstemde belirgin olun; belirsiz istemler güçlü bir modelle bile jenerik UI üretir.", "Tasarım sisteminizi ve kurallarınızı QWEN.md içinde tutun ve Qwen Code'a token'ların ve standart ilkellerin nerede olduğunu söyleyin.", "Bir geliştirme sunucusu çalıştırın ve Qwen Code'un sonucu kontrol etmek için kırılma noktalarına yeniden boyutlandırarak gerçek bir tarayıcıda işlemesini sağlayın.", "Qwen Code'un uygulamasını referanslara geri karşılaştırmasını sağlayarak yineleyin — yalnızca derlendiğini onaylamak değil."]}, {"kind": "p", "text": "Bir dosyayı isteme eklemek için @ ile referans verin, ardından somut kısıtlamalar verin:"}, {"kind": "code", "lang": "bash", "code": "qwen\n# in the prompt:\n> @reference-desktop.png @reference-mobile.png\n  Implement this design in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from QWEN.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Render it in the browser and iterate until it matches the references\n  across breakpoints."}, {"kind": "p", "text": "İstemleri küçük ve odaklı tutun, iyi yinelemeleri commit edin ve kötüleri geri alın (geri aldığınızda Qwen Code'a söyleyerek), böylece her geçiş temiz bir temel üzerine inşa edilir."}]}, {"id": "extend", "heading": "QWEN.md, MCP ve uzantılar", "blocks": [{"kind": "p", "text": "Üç uzantı noktası Qwen Code'u sürekli tasarım çalışmaları için pratik kılar ve üçü de açık bir tasarım iş akışına temiz bir şekilde eşlenir."}, {"kind": "steps", "items": [{"label": "QWEN.md bağlamı", "body": "Proje kuralları depo kökünde bir QWEN.md içinde yaşar (genel ve proje katmanlarıyla). Her çalıştırmada okunan, tasarım kurallarınızın kalıcı yuvasıdır."}, {"label": "MCP sunucuları", "body": "~/.qwen/settings.json içinde mcpServers altında MCP sunucularını yapılandırın — en alakalı olarak Figma MCP sunucusu olmak üzere, yalnızca Qwen Code'da değil ajanlar genelinde çalışan, tasarım bağlamını ve harici araçları getirmenin taşınabilir yolu."}, {"label": "Beceriler ve yerleşik araçlar", "body": "Qwen Code becerileri ve yerleşik dosya, kabuk ve web araçları, terminalden ayrılmadan referans toplamasına ve doğrulama döngüsünü çalıştırmasına izin verir."}]}, {"kind": "p", "text": "Bunlar taşınabilir, çok ajanlı yeteneklerdir — Open Design'ın proje başına yeniden oluşturmak yerine orkestre etmek için inşa edildiği türden tam olarak budur."}]}, {"id": "vs", "heading": "Tasarım için Qwen Code vs Codex vs Claude Code vs Cursor vs Gemini CLI", "blocks": [{"kind": "p", "text": "Tasarım çalışmaları için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler onları üst üste koyar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["Qwen Code", "Büyük bir bağlamla açık Qwen3-Coder modellerinde güçlü ajansal kodlama; açık kaynaklı ve BYOK", "Bütün bir tasarım sistemini bağlamda tutan açık kaynaklı, anahtar esnek derlemeler"], ["Codex", "Ön uç becerisiyle güçlü görsel cila; sandbox'lı eşzamansız derlemeler", "Devredilmiş eşzamansız derlemeler ve taşınabilir AGENTS.md kuralları"], ["Claude Code", "Belirli tasarım kararları (hex, boşluk, tipografi) ve kod tabanından haberdar UX", "Ön uç muhakemesi ve büyük bağlamlı yeniden düzenlemeler"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"], ["Gemini CLI", "Güçlü çok modlu görüntü anlama ve 1M token'lık bir bağlam; Qwen Code'un uyarlandığı ajan", "Ekran görüntüsü ağırlıklı çalışma ve çok büyük bağlam"]]}, {"kind": "p", "text": "Tekrarlayan topluluk kanaati, zevkin insanlardan geldiğidir: hepsi beceriler, referanslar ve kısıtlamalar olmadan jenerik bir estetiğe varsayılan olur. Çözülmesi gereken gerçek sorun budur — ve bu, model biçimli değil, tasarım aracı biçimlidir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “yapay zeka çorbası” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Yapay zeka tarafından üretilen tasarım hakkında en yaygın şikayet, jenerik göründüğüdür — yumuşak gradyanlar, yüzen paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir yapay zekanın yaptığını haykıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında bozuk mobil düzenler ve talimatların UI metnine sızması yer alır. Bunların hiçbiri Qwen Code'a özgü değildir; herhangi bir ajan özenle seçilmiş bir tasarım bağlamı olmadan çalıştığında olan şeydir."}, {"kind": "steps", "items": [{"label": "Estetik bir beceri ekleyin", "body": "Özenle seçilmiş bir tasarım becerisi, ajanı varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Gerçek bir tarayıcıda doğrulayın", "body": "Ajanın kırılma noktaları genelinde işlemesini ve öz-denetim yapmasını sağlayın, böylece düzenler mobilde sessizce bozulmaz."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki tek en büyük kaldıraçtır."}, {"label": "Kuralları QWEN.md içinde kodlayın", "body": "“Kahraman kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Her hafifletmenin ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı angaryadır."}]}, {"id": "open-design", "heading": "Open Design içinde Qwen Code ile tasarlamak", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. Qwen Code'u birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesine, yapılandırılmış bir işleme hattına ve yerel bir masaüstü UI'sine sarar — böylece Qwen Code'u iyi yapan tasarım bağlamı, her seferinde elle birleştirilmek yerine ilk çalıştırmadan itibaren oradadır. Her ikisi de açık kaynaklı ve yerel önceliklidir, ki bu da eşleşmeyi doğal bir uyum kılar."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak Qwen Code'u seçin.", "DashScope veya Qwen API anahtarınızla (BYOK) kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy yapılmaz.", "Bir tasarım sistemi ve bir beceri seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları oluşturun.", "Her üretim ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi deponuzda yaşar."]}, {"kind": "p", "text": "Aynı Qwen Code ajanı, aynı anahtar — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0'dır, böylece çalışmanız veya kimlik bilgilerinizle ilgili hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "Qwen Code gerçekten tasarım çalışması yapabilir mi?", "text": "Evet — bağlamda estetik bir beceri, bir tasarım sistemi ve gerçek referans görüntülerle, Qwen Code üretim kalitesinde, duyarlı UI üretir ve ajansal döngüsü çıktıyı referanslara karşı inşa eder, işler ve doğrular. Bu bağlam olmadan jenerik bir görünüme varsayılan olma eğilimindedir; bu da Open Design'ın doldurduğu boşluktur."}, {"name": "Qwen Code ile tasarım yapmak için ödeme yapmam gerekir mi?", "text": "Qwen Code ücretsiz ve açık kaynaklıdır, ancak BYOK'tur — bir DashScope (Alibaba Cloud Model Studio) API anahtarı, OpenAI uyumlu bir uç nokta veya ModelScope getirirsiniz. Alibaba ayrıca sabit ücretli bir kodlama planı sunar. Open Design her iki durumda da kimlik bilgilerinizi asla proxy yapmaz."}, {"name": "Qwen Code'u özellikle tasarım için iyi yapan nedir?", "text": "İki şey: Qwen3-Coder modelleri ajansal kodlama için ayarlanmıştır, böylece ajan duyarlı UI'yi inşa eder ve kendi kendini düzeltir; ve büyük bağlamları bütün bir tasarım sistemini ve referans setini bir kerede tutabilir. Her ikisi de yardımcı olur — ama zevk yine de sağladığınız tasarım sisteminden, beceriden ve referanslardan gelir."}, {"name": "Qwen Code, Gemini CLI ile aynı mı?", "text": "Hayır. Qwen Code, Google'ın Gemini CLI'sinden uyarlanmıştır — aynı açık kaynak soyu — Qwen3-Coder modelleri için ayarlayan ayrıştırıcı düzeyinde ve istem uyarlamalarıyla. Open Design her ikisini de destekler, böylece tasarım iş akışınızı değiştirmeden ajan değiştirebilirsiniz."}, {"name": "Qwen Code'u Figma'ya nasıl bağlarım?", "text": "~/.qwen/settings.json içinde mcpServers altına Figma MCP sunucusunu ekleyin. Qwen Code daha sonra gerçek tasarım bağlamı çekebilir — bileşenler, değişkenler, düzen verileri — böylece üretilen kod yaklaşık değer yerine kaynağa eşleşir."}, {"name": "Open Design Alibaba veya Qwen ile bağlantılı mı?", "text": "Hayır. Qwen Code, Alibaba'nın bir ürünüdür; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynak projesidir. Qwen, Alibaba'nın ticari markasıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel öncelikli ve Apache-2.0'dır. Dosyalarınız, üretimleriniz ve DESIGN.md'niz kendi deponuzda kalır ve DashScope veya Qwen kimlik bilgileriniz doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "Qwen Code ile açık yoldan tasarlayın.", "ctaBody": "Kendi DashScope veya Qwen API anahtarınızı getirin, her dosyayı yerel tutun ve zaten kullandığınız ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "Qwen Code'u Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'grok': {
        ...en['grok']!,
        title: "Tasarım için Grok CLI — Open Design",
        description: "İnsanlar xAI'nin Grok CLI'sini (Grok Build) UI ve web tasarımı için nasıl kullanıyor — plan modu, AGENTS.md ve MCP, görüntü farkında Grok modelleri ve büyük bağlam — ve Open Design, Grok CLI'yi yerel öncelikli, açık kaynaklı bir tasarım ajanına nasıl dönüştürüyor.",
        breadcrumb: "Grok CLI",
        label: "Ajan · Grok CLI",
        heading: "Tasarım için Grok CLI.",
        lead: "Grok CLI, xAI'nin terminal kodlama ajanıdır. Dosyalarınıza dokunmadan önce çok adımlı çalışmayı planlar, görüntüleri kodla birlikte okur ve oluştur-ve-doğrula döngüsünü deponuzda çalıştırır — ki bu da ona referanslar, kurallar ve bir doğrulama adımı verdiğinizde onu gerçek bir tasarım aracı yapar. Open Design onu açık kaynaklı bir tasarım iş akışına bağlar: kendi SuperGrok girişiniz veya xAI API anahtarınız, kendi dosyalarınız, yerel öncelikli.",
        rich: {"heroCtaLead": "Open Design, Grok CLI'yi yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — kendi SuperGrok girişiniz veya xAI API anahtarınız, kendi dosyalarınız ve etrafında özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "Grok CLI'yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Grok CLI — xAI'nin terminal kodlama ajanı, Grok Build olarak sunulur — terminalinizde yaşayan ajansal bir araçtır. Özellikle tasarım açısından onu ilginç kılan iki şey var: harekete geçmeden önce riskli çalışmayı planlar, böylece herhangi bir dosya değişmeden önce önerilen bir yaklaşımı inceleyebilirsiniz; ve Grok modelleri görüntü girdisi kabul eder, böylece yazdığı kodun yanında bir referans ekran görüntüsü hakkında muhakeme yapabilir. Doğru referanslar, kurallar ve bir doğrulama döngüsüyle eşleştirildiğinde gerçek, duyarlı UI üretir — doğrudan SuperGrok veya X Premium+ hesabınız üzerinden kimliği doğrulanır, API anahtarı hokkabazlığı gerekmez. Bu, Grok CLI'yi UI, ön uç ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya yönelik pratik, uçtan uca bir kılavuzdur.", "Grok CLI'nin gerçekte ne olduğunu, plan modunun ve görüntü farkında modellerin tasarıma neden uyduğunu, sıfırdan nasıl kurulacağını, ekran görüntüsünden UI'ye döngüyü, AGENTS.md ve MCP'nin onu nasıl genişlettiğini, Codex, Claude Code, Cursor ve Gemini CLI ile nasıl karşılaştırıldığını, yapay zeka çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak boşluğu nasıl kapattığını kapsar — kimlik bilgileriniz ve üretimleriniz makinenizden asla ayrılmaz."], "heroImage": {"src": "/agents/grok-design/grok-design-hero.webp", "alt": "Grok CLI tasarım geri bildirim döngüsü: bir referans görüntüsünden plan yapan bir terminal ajanı, UI'yi işleyen bir tarayıcı ve bir çalışma alanı, geri döngü yapan bir geri bildirim okuyla", "caption": "Temel döngü: Grok CLI referanslarınızdan terminalde plan yapar, UI'yi gerçek bir tarayıcıda oluşturup doğrular ve onlara karşı yineler — kurallarınız AGENTS.md'de."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-grok", "label": "Grok CLI gerçekte nedir"}, {"id": "why-design", "label": "Plan modu + görüntü girdisi tasarıma neden uyar"}, {"id": "setup", "label": "Tasarım için Grok CLI'yi kurun (sıfırdan)"}, {"id": "screenshot-workflow", "label": "Ekran görüntüsünden UI'ye iş akışı"}, {"id": "extend", "label": "AGENTS.md, MCP ve alt ajanlar"}, {"id": "vs", "label": "Grok CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Tuzaklar ve “yapay zeka çorbası” görünümü"}, {"id": "open-design", "label": "Open Design'da Grok CLI ile tasarlamak"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-grok", "heading": "Grok CLI gerçekte nedir", "blocks": [{"kind": "p", "text": "Grok CLI, xAI'nin Grok Build adıyla sunulan terminal kodlama ajanıdır. Deponuzu okur, dosyaları düzenler, kabuk komutları çalıştırır ve yalnızca satırları tamamlamak yerine doğal dildeki görevlerden çok adımlı mühendislik çalışmasını planlar. xAI'nin Grok modelleri etrafında inşa edilmiştir — xAI API'sinde grok-build model ailesi olarak sunulur — ve xAI hesabınız üzerinden kimliği doğrulanır, böylece ajan ve modeller aynı sağlayıcıdan gelir."}, {"kind": "p", "text": "Tasarım çalışmaları için iki özellik öne çıkar. Herhangi bir değişiklik inmeden önce onaylayabileceğiniz, yorum yapabileceğiniz veya yeniden yazabileceğiniz yapılandırılmış bir yaklaşım taslağı oluşturan bir plan moduna sahiptir — UI üzerinde yinelerken kullanışlı bir kapı. Ve Grok modelleri görüntü girdisi kabul eder, böylece ona bir referans ekran görüntüsü verebilirsiniz ve düzyazı bir açıklamadan tahmin etmek yerine gerçek düzen hakkında muhakeme yapar."}, {"kind": "steps", "items": [{"label": "Bağlam dosyaları", "body": "Grok CLI, kalıcı proje bağlamı için bir AGENTS.md dosyasını okur — tasarım kurallarınızı, token'larınızı ve inceleme kontrol listelerinizi kodlamak için doğal yer. Codex ve diğer ajanların kullandığı aynı açık AGENTS.md kuralını izler."}, {"label": "Araçlar, MCP + alt ajanlar", "body": "Dosyaları düzenler, kabuk komutları çalıştırır ve canlı bir Figma dosyası gibi harici bağlam eklemek için MCP sunucularını destekler; daha büyük görevler için aynı anda araştıran, inşa eden ve inceleyen paralel alt ajanlara devredebilir."}, {"label": "Hesabınızla oturum açın", "body": "Bir SuperGrok veya X Premium+ aboneliğiyle tarayıcınız üzerinden oturum açarak kimlik doğrularsınız; ayrıca başsız ve CI kullanımı için bir xAI API anahtarı getirebilirsiniz."}]}, {"kind": "ul", "items": ["Sağlayıcı: xAI", "Kimlik bilgisi: xAI SuperGrok OAuth (`grok login`) veya başsız kullanım için bir xAI API anahtarı (BYOK)", "Modeller: xAI Grok modelleri (xAI API'sindeki grok-build ailesi), görüntü girdisiyle"]}]}, {"id": "why-design", "heading": "Plan modu ve görüntü farkında modeller tasarıma neden uyar", "blocks": [{"kind": "p", "text": "Grok CLI'nin tasarım avantajı iki özellikten gelir — ama her ajanda olduğu gibi, zevkin yine de sağlanması gerekir."}, {"kind": "steps", "items": [{"label": "Görüntü farkında muhakeme", "body": "Grok modelleri görüntü girdisi kabul ettiğinden, ajan referans ekran görüntülerini okur — düzyazı bir açıklamadan tahmin etmek yerine işlenmiş çıktısını bir görüntüyle geri karşılaştırır."}, {"label": "Değişiklikler inmeden önce plan modu", "body": "Plan modu, dosyalar değişmeden önce onayladığınız yapılandırılmış bir yaklaşım taslağı oluşturur, böylece tasarım niyeti diff'ten sonra keşfedilmek yerine önceden incelenir."}, {"label": "AGENTS.md içindeki kurallar", "body": "Bir AGENTS.md (artı Figma MCP sunucusu) ajanı token'larınıza, bileşenlerinize ve gerçek spesifikasyonlarınıza yönlendirir, böylece varsayılan bir görünüm yerine bir markaya karşı çalışır."}]}, {"kind": "image", "src": "/agents/grok-design/grok-design-taste-triangle.webp", "alt": "Tasarım sistemi, beceri ve referans görüntüsünün iyi tasarım çıktısında birleştiğini gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir beceri ve gerçek referans görüntüleri."}, {"kind": "p", "text": "Ders, her ajanın öğrettiğiyle aynıdır: Grok CLI varsayılan olarak zevke sahip değildir. Ona kısıtlamalar verdiğinizde — bir tasarım sistemi, estetik bir beceri ve somut referanslar — iyi tasarım üretir. Open Design tam olarak bu girdileri paketler, bu yüzden ikisi birbirine uyar (aşağıda daha fazlası)."}]}, {"id": "setup", "heading": "Tasarım çalışmaları için Grok CLI'yi sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden, UI oluşturup doğrulayabilen bir Grok CLI'ye giden tam yol burada."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Grok CLI (Grok Build) on macOS/Linux\ncurl -fsSL https://x.ai/cli/install.sh | bash\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\ngrok login   # opens your browser; sign in with SuperGrok / X Premium+\n#   or, for headless / CI use, set an xAI API key:\n#   export XAI_API_KEY=xai-...\n\n# 3. Add project context\n#    create an AGENTS.md at the repo root with your design conventions\n\n# 4. Wire the Figma MCP server (optional, for design handoff)\n#    add it to your MCP server configuration"}, {"kind": "image", "src": "/agents/grok-design/grok-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: kur, kimlik doğrula, AGENTS.md yapılandır, bir beceri ekle, doğrula", "caption": "Kurulum sırası: kur → kimlik doğrula → AGENTS.md yapılandır → bir beceri ekle → tarayıcı doğrulamasını etkinleştir."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı AGENTS.md içine koyun ve Grok'u onlara yönlendirin, böylece çıktı jenerik bir görünüme varsayılan olmak yerine bir markayla eşleşir."}, {"label": "Tarayıcı doğrulaması ekleyin", "body": "Bir Playwright veya tarayıcı MCP'si bağlayın, böylece Grok gerçek bir tarayıcıda işler ve yalnızca derlemenin geçtiğini onaylamak yerine çıktısını kırılma noktaları genelinde kontrol eder."}]}]}, {"id": "screenshot-workflow", "heading": "Ekran görüntüsünden UI'ye iş akışı", "blocks": [{"kind": "p", "text": "Grok CLI ile en yüksek kaldıraçlı tasarım döngüsü, bir referans görüntüyü çalışan, duyarlı UI'ye dönüştürmek ve eşleşene kadar yinelemektir — yaklaşım üzerinde anlaşmak için plan moduna ve çıktıyı referansla karşılaştırmak için görüntü farkında modele dayanarak."}, {"kind": "ol", "items": ["Elinizdeki en net görsel referanslardan başlayın — ve yalnızca tek bir kahraman görüntü değil, birden fazla durum (masaüstü ve mobil, hover, boş, yükleniyor) ekleyin.", "İstemde belirgin olun; belirsiz istemler güçlü bir modelle bile jenerik UI üretir.", "Tasarım sisteminizi ve kurallarınızı AGENTS.md içinde tutun ve Grok'a token'ların ve standart ilkellerin nerede olduğunu söyleyin.", "Yaklaşımı incelemek için plan modunu kullanın, ardından bir geliştirme sunucusu çalıştırın ve Grok'un sonucu kontrol etmek için kırılma noktalarına yeniden boyutlandırarak gerçek bir tarayıcıda işlemesini sağlayın.", "Grok'un uygulamasını ekran görüntülerine geri karşılaştırmasını sağlayarak yineleyin — yalnızca derlendiğini onaylamak değil."]}, {"kind": "p", "text": "Referans görüntülerinizi ekleyin ve somut kısıtlamalar verin:"}, {"kind": "code", "lang": "bash", "code": "grok\n# in the prompt (attach reference-desktop.png and reference-mobile.png):\n> Implement this design in React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from AGENTS.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Show me the plan first, then render it in the browser and iterate\n  until it matches the references across breakpoints."}, {"kind": "p", "text": "İstemleri küçük ve odaklı tutun, iyi yinelemeleri commit edin ve kötüleri geri alın (geri aldığınızda Grok'a söyleyerek), böylece her geçiş temiz bir temel üzerine inşa edilir."}]}, {"id": "extend", "heading": "AGENTS.md, MCP ve alt ajanlar", "blocks": [{"kind": "p", "text": "Üç uzantı noktası Grok CLI'yi sürekli tasarım çalışmaları için pratik kılar ve üçü de açık bir tasarım iş akışına temiz bir şekilde eşlenir."}, {"kind": "steps", "items": [{"label": "AGENTS.md bağlamı", "body": "Proje kuralları depo kökünde bir AGENTS.md içinde yaşar. Her çalıştırmada okunan, tasarım kurallarınızın kalıcı yuvasıdır — ve diğer ajanların anladığı aynı açık biçimdir, böylece kurallar sizinle birlikte hareket eder."}, {"label": "MCP sunucuları", "body": "Tasarım bağlamını ve harici araçları getirmek için MCP sunucularını yapılandırın, en alakalı olarak Figma MCP sunucusu — gerçek spesifikasyonları koda beslemenin, yalnızca Grok'ta değil ajanlar genelinde çalışan taşınabilir yolu."}, {"label": "Alt ajanlar ve yerleşik araçlar", "body": "Grok CLI, aynı anda araştırmak, inşa etmek ve incelemek için paralel alt ajanlar oluşturabilir ve dosya, kabuk ve arama araçları, terminalden ayrılmadan referans toplamasına ve doğrulama döngüsünü çalıştırmasına izin verir."}]}, {"kind": "p", "text": "Bunlar taşınabilir, çok ajanlı yeteneklerdir — Open Design'ın proje başına yeniden oluşturmak yerine orkestre etmek için inşa edildiği türden tam olarak budur."}]}, {"id": "vs", "heading": "Tasarım için Grok CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI", "blocks": [{"kind": "p", "text": "Tasarım çalışmaları için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler onları üst üste koyar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["Grok CLI", "Değişiklikler inmeden önce plan modu incelemesi, görüntü farkında Grok modelleri ve paralel alt ajanlar; SuperGrok hesabınızla oturum açar", "Döngüde xAI modelleriyle incelenmiş, plan öncelikli UI derlemeleri"], ["Codex", "Ön uç becerisiyle güçlü görsel cila; sandbox'lı eşzamansız derlemeler", "Devredilmiş eşzamansız derlemeler ve taşınabilir AGENTS.md kuralları"], ["Claude Code", "Belirli tasarım kararları (hex, boşluk, tipografi) ve kod tabanından haberdar UX", "Ön uç muhakemesi ve büyük bağlamlı yeniden düzenlemeler"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"], ["Gemini CLI", "Güçlü çok modlu görüntü anlama ve çok büyük bir bağlam; ücretsiz katmanlı açık kaynak", "Ekran görüntüsü ağırlıklı çalışma ve bütün bir tasarım sistemini bağlamda tutma"]]}, {"kind": "p", "text": "Tekrarlayan topluluk kanaati, zevkin insanlardan geldiğidir: hepsi beceriler, referanslar ve kısıtlamalar olmadan jenerik bir estetiğe varsayılan olur. Çözülmesi gereken gerçek sorun budur — ve bu, model biçimli değil, tasarım aracı biçimlidir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “yapay zeka çorbası” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Yapay zeka tarafından üretilen tasarım hakkında en yaygın şikayet, jenerik göründüğüdür — yumuşak gradyanlar, yüzen paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir yapay zekanın yaptığını haykıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında bozuk mobil düzenler ve talimatların UI metnine sızması yer alır. Bunların hiçbiri Grok CLI'ye özgü değildir; herhangi bir ajan özenle seçilmiş bir tasarım bağlamı olmadan çalıştığında olan şeydir."}, {"kind": "steps", "items": [{"label": "Estetik bir beceri ekleyin", "body": "Özenle seçilmiş bir tasarım becerisi, ajanı varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Gerçek bir tarayıcıda doğrulayın", "body": "Kırılma noktaları genelinde işleyin ve öz-denetim yapın, böylece düzenler mobilde sessizce bozulmaz."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki tek en büyük kaldıraçtır."}, {"label": "Kuralları AGENTS.md içinde kodlayın", "body": "“Kahraman kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Her hafifletmenin ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı angaryadır."}]}, {"id": "open-design", "heading": "Open Design içinde Grok CLI ile tasarlamak", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. Grok CLI'yi birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesine, yapılandırılmış bir işleme hattına ve yerel bir masaüstü UI'sine sarar — böylece Grok'u iyi yapan tasarım bağlamı, her seferinde elle birleştirilmek yerine ilk çalıştırmadan itibaren oradadır. Open Design bağımsız ve Apache-2.0'dır ve kendi makinenizde çalışır, ki bu da eşleşmeyi doğal bir uyum kılar."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak Grok CLI'yi seçin.", "SuperGrok hesabınızla veya bir xAI API anahtarıyla (BYOK) kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy yapılmaz.", "Bir tasarım sistemi ve bir beceri seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları oluşturun.", "Her üretim ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi deponuzda yaşar."]}, {"kind": "p", "text": "Aynı Grok CLI ajanı, aynı kimlik bilgileri — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0'dır, böylece çalışmanız veya kimlik bilgilerinizle ilgili hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "Grok CLI gerçekten tasarım çalışması yapabilir mi?", "text": "Evet — bağlamda estetik bir beceri, bir tasarım sistemi ve gerçek referans görüntülerle, Grok CLI üretim kalitesinde, duyarlı UI üretir ve görüntü farkında Grok modelleri çıktıyı referanslara karşı doğrulamaya yardımcı olur. Bu bağlam olmadan jenerik bir görünüme varsayılan olma eğilimindedir; bu da Open Design'ın doldurduğu boşluktur."}, {"name": "Grok CLI'nin kimliğini nasıl doğrularım?", "text": "Bir SuperGrok veya X Premium+ aboneliğiyle tarayıcınız üzerinden oturum açarsınız (`grok login`), böylece yönetilecek bir API anahtarı yoktur. Başsız veya CI kullanımı için bunun yerine bir xAI API anahtarı getirebilirsiniz. Open Design her iki durumda da kimlik bilgilerinizi asla proxy yapmaz."}, {"name": "Grok CLI'yi özellikle tasarım için iyi yapan nedir?", "text": "İki şey: plan modu, herhangi bir değişiklik inmeden önce yaklaşımı incelemenize izin verir ve Grok modelleri görüntü girdisi kabul eder, böylece referans ekran görüntülerini iyi okur. Her ikisi de yardımcı olur — ama zevk yine de sağladığınız tasarım sisteminden, beceriden ve referanslardan gelir."}, {"name": "Ön uç tasarımı için Grok CLI mi Claude Code mu?", "text": "Her ikisi de güçlüdür. Claude Code, belirli, kod tabanından haberdar tasarım kararlarıyla bilinir; Grok CLI'nin avantajı, plan modu incelemesi ve görüntü farkında xAI modelleridir. Birçok ekip her ikisini de kullanır — Open Design, tasarım iş akışınızı değiştirmeden ajan değiştirmenize izin verir."}, {"name": "Grok CLI'yi Figma'ya nasıl bağlarım?", "text": "Figma MCP sunucusunu MCP yapılandırmanıza ekleyin. Grok daha sonra gerçek tasarım bağlamı çekebilir — bileşenler, değişkenler, düzen verileri — böylece üretilen kod yaklaşık değer yerine kaynağa eşleşir."}, {"name": "Open Design xAI ile bağlantılı mı?", "text": "Hayır. Grok CLI, xAI'nin bir ürünüdür; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynak projesidir. Grok, xAI'nin ticari markasıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel öncelikli ve Apache-2.0'dır. Dosyalarınız, üretimleriniz ve DESIGN.md'niz kendi deponuzda kalır ve xAI kimlik bilgileriniz doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "Grok CLI ile açık yoldan tasarlayın.", "ctaBody": "Kendi SuperGrok hesabınızı veya xAI API anahtarınızı getirin, her dosyayı yerel tutun ve zaten kullandığınız ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "Grok CLI'yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'kimi': {
        ...en['kimi']!,
        title: "Tasarım için Kimi CLI — Open Design",
        description: "İnsanlar Moonshot AI'nin Kimi CLI'sini UI ve web tasarımı için nasıl kullanıyor — Kimi K2 ajansal modelleri, büyük bağlam, AGENTS.md ve MCP — ve Open Design, Kimi CLI'yi yerel öncelikli, açık kaynaklı bir tasarım ajanına nasıl dönüştürüyor.",
        breadcrumb: "Kimi CLI",
        label: "Ajan · Kimi CLI",
        heading: "Tasarım için Kimi CLI.",
        lead: "Kimi CLI, Moonshot AI'nin Kimi K2 model serisiyle çalışan açık kaynaklı terminal ajanıdır. Güçlü ajansal kodlaması ve büyük bağlam penceresi, bütün bir tasarım sistemini tutmasına ve referanslara karşı yinelemesine izin verir — ona kurallar ve bir doğrulama döngüsü verdiğinizde gerçek bir tasarım aracı olur. Open Design onu açık kaynaklı bir tasarım iş akışına bağlar: kendi Moonshot API anahtarınız, kendi dosyalarınız, yerel öncelikli.",
        rich: {"heroCtaLead": "Open Design, Kimi CLI'yi yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — kendi Moonshot API anahtarınız, kendi dosyalarınız ve etrafında özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "Kimi CLI'yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["Kimi CLI, Moonshot AI'nin terminal için açık kaynaklı yapay zeka ajanıdır. Özellikle tasarım açısından onu ilginç kılan iki şey var: Kimi K2 serisiyle çalışır — ajansal kodlama ve araç kullanımı için titizlikle optimize edilmiş, trilyon parametreli bir uzman karışımı modeli; ve bu model büyük bir bağlam penceresi taşır (son K2 sürümlerinde 256k token), bütün bir tasarım sistemini ve kod tabanını bir kerede tutacak kadar büyük. Doğru referanslar, kurallar ve bir doğrulama döngüsüyle eşleştirildiğinde gerçek, duyarlı UI üretir — ve bir OAuth girişiyle veya kendi Moonshot API anahtarınızla başlayabilirsiniz. Bu, Kimi CLI'yi UI, ön uç ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya yönelik pratik, uçtan uca bir kılavuzdur.", "Kimi CLI'nin gerçekte ne olduğunu, ajansal Kimi K2 modellerinin ve büyük bağlamının tasarıma neden uyduğunu, sıfırdan nasıl kurulacağını, referanstan UI'ye döngüyü, AGENTS.md, MCP ve alt ajanların onu nasıl genişlettiğini, Codex, Claude Code, Cursor ve Gemini CLI ile nasıl karşılaştırıldığını, yapay zeka çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak boşluğu nasıl kapattığını kapsar — doğal bir eşleşme, çünkü her ikisi de açık kaynaklı ve kendi makinenizde çalışıyor."], "heroImage": {"src": "/agents/kimi-design/kimi-design-hero.webp", "alt": "Kimi CLI tasarım geri bildirim döngüsü: bir referans görüntüsünü okuyan bir terminal ajanı, UI'yi işleyen bir tarayıcı ve bir çalışma alanı, geri döngü yapan bir geri bildirim okuyla", "caption": "Temel döngü: Kimi CLI referanslarınızı terminalde okur, UI'yi gerçek bir tarayıcıda oluşturup doğrular ve onlara karşı yineler — bütün bir tasarım sistemi bağlamda."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-kimi", "label": "Kimi CLI gerçekte nedir"}, {"id": "why-design", "label": "Ajansal K2 + büyük bağlam tasarıma neden uyar"}, {"id": "setup", "label": "Tasarım için Kimi CLI'yi kurun (sıfırdan)"}, {"id": "screenshot-workflow", "label": "Referanstan UI'ye iş akışı"}, {"id": "extend", "label": "AGENTS.md, MCP ve alt ajanlar"}, {"id": "vs", "label": "Kimi CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Tuzaklar ve “yapay zeka çorbası” görünümü"}, {"id": "open-design", "label": "Open Design'da Kimi CLI ile tasarlamak"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-kimi", "heading": "Kimi CLI gerçekte nedir", "blocks": [{"kind": "p", "text": "Kimi CLI, Moonshot AI'nin terminal için sunduğu açık kaynaklı (Apache-2.0) bir yapay zeka ajanıdır. Deponuzu okur, dosyaları düzenler, kabuk komutları çalıştırır, dosyaları arar, web sayfaları getirir ve aldığı geri bildirimden bir sonraki adımını seçer — yalnızca satırları tamamlamak yerine doğal dildeki görevlerden plan yapar ve işi doğrular. uv ile kurulan bir Python aracıdır ve perde arkasında Kimi K2 model ailesini sürer."}, {"kind": "p", "text": "Tasarım çalışmaları için iki özellik öne çıkar. Kimi K2 modelleri açıkça ajansal, uzun ufuklu kodlama ve araç kullanımı için ayarlanmıştır, böylece ajan çok adımlı bir derlemeyi çalışan bir sonuca taşıyabilir. Ve bağlam penceresi son K2 sürümlerinde 256k token'a ulaşır; bütün tasarım sisteminizi, bileşen kütüphanenizi ve referans setinizi özetleyerek elemek yerine bir kerede tutacak kadar büyük."}, {"kind": "steps", "items": [{"label": "Bağlam dosyaları", "body": "Kimi CLI, kalıcı proje bağlamı için bir AGENTS.md dosyasını okur — tasarım kurallarınızı, token'larınızı ve inceleme kontrol listelerinizi kodlamak için doğal yer. Sahip olmayan bir proje için bir tane iskele kurmak üzere /init çalıştırın."}, {"label": "MCP, ACP + alt ajanlar", "body": "MCP sunucularını /mcp-config ile sohbet ederek yönetir, Zed ve JetBrains'e Agent Client Protocol (kimi acp) üzerinden bir oturum sunar ve izole bağlamlarda yerleşik coder, explore ve plan alt ajanlarını gönderebilir."}, {"label": "Giriş veya BYOK", "body": "İlk başlatmada, /login OAuth (Kimi Code) ile yetkilendirmenize veya kendi Moonshot API anahtarınızı girmenize izin verir; Kimi'nin platformu ayrıca OpenAI ve Anthropic uyumlu uç noktalar sunar."}]}, {"kind": "ul", "items": ["Sağlayıcı: Moonshot AI", "Kimlik bilgisi: Moonshot API anahtarı (BYOK) veya Kimi Code üzerinden OAuth girişi", "Lisans: Apache-2.0, açık kaynak"]}]}, {"id": "why-design", "heading": "Ajansal K2 modelleri ve büyük bir bağlam tasarıma neden uyar", "blocks": [{"kind": "p", "text": "Kimi CLI'nin tasarım avantajı iki model özelliğinden gelir — ama her ajanda olduğu gibi, zevkin yine de sağlanması gerekir."}, {"kind": "steps", "items": [{"label": "Ajansal, uzun ufuklu kodlama", "body": "Kimi K2 modelleri araç kullanımı ve çok adımlı çalışma için optimize edilmiştir, böylece ajan bir referansı ve bir özeti alıp ilk taslakta durmak yerine UI'yi gerçekten inşa edebilir, çalıştırabilir ve iyileştirebilir."}, {"label": "Büyük bir bağlam penceresi", "body": "Son K2 sürümlerinde 256k token'a kadar, bütün tasarım sisteminin, token'ların ve birçok referans durumunun bir kerede sığması anlamına gelir, böylece ajan tek seferlik stiller icat etmek yerine gerçek ilkellerinizi yeniden kullanır."}, {"label": "AGENTS.md içindeki kurallar", "body": "Bir AGENTS.md (artı Figma gibi bir MCP sunucusu) ajanı token'larınıza, bileşenlerinize ve gerçek spesifikasyonlarınıza yönlendirir, böylece varsayılan bir görünüm yerine bir markaya karşı çalışır."}]}, {"kind": "image", "src": "/agents/kimi-design/kimi-design-taste-triangle.webp", "alt": "Tasarım sistemi, beceri ve referans görüntüsünün iyi tasarım çıktısında birleştiğini gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir beceri ve gerçek referans görüntüleri."}, {"kind": "p", "text": "Ders, her ajanın öğrettiğiyle aynıdır: Kimi CLI varsayılan olarak zevke sahip değildir. Ona kısıtlamalar verdiğinizde — bir tasarım sistemi, estetik bir beceri ve somut referanslar — iyi tasarım üretir. Open Design tam olarak bu girdileri paketler, bu yüzden ikisi birbirine uyar (aşağıda daha fazlası)."}]}, {"id": "setup", "heading": "Tasarım çalışmaları için Kimi CLI'yi sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden, UI oluşturup doğrulayabilen bir Kimi CLI'ye giden tam yol burada."}, {"kind": "code", "lang": "bash", "code": "# 1. Install Kimi CLI (uses uv; Python 3.12–3.14, 3.13 recommended)\ncurl -LsSf https://code.kimi.com/install.sh | bash\n# or, if you already have uv:\nuv tool install --python 3.13 kimi-cli\n\n# 2. Start it in your project and authenticate on first run\ncd your-project\nkimi              # then run /login: OAuth via Kimi Code, or paste a Moonshot API key\n\n# 3. Generate project context\n/init             # scaffolds an AGENTS.md for this project\n\n# 4. Wire an MCP server (optional, e.g. Figma for design handoff)\n/mcp-config       # add, edit, and authenticate MCP servers conversationally"}, {"kind": "image", "src": "/agents/kimi-design/kimi-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: kur, kimlik doğrula, AGENTS.md yapılandır, bir beceri ekle, doğrula", "caption": "Kurulum sırası: kur → kimlik doğrula → AGENTS.md yapılandır → bir beceri ekle → tarayıcı doğrulamasını etkinleştir."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı AGENTS.md içine koyun ve Kimi'yi onlara yönlendirin, böylece çıktı jenerik bir görünüme varsayılan olmak yerine bir markayla eşleşir."}, {"label": "Tarayıcı doğrulaması ekleyin", "body": "Bir Playwright veya tarayıcı MCP'si bağlayın, böylece Kimi gerçek bir tarayıcıda işler ve yalnızca derlemenin geçtiğini onaylamak yerine çıktısını kırılma noktaları genelinde kontrol eder."}]}]}, {"id": "screenshot-workflow", "heading": "Referanstan UI'ye iş akışı", "blocks": [{"kind": "p", "text": "Kimi CLI ile en yüksek kaldıraçlı tasarım döngüsü, referans malzemesini çalışan, duyarlı UI'ye dönüştürmek ve eşleşene kadar yinelemektir — ajana referanslarınızı besleyip işlenmiş çıktısını gerçek bir tarayıcıda onlara geri karşılaştırmasını sağlayarak."}, {"kind": "ol", "items": ["Elinizdeki en net referanslardan başlayın — ve yalnızca tek bir kahraman görüntü değil, birden fazla durum (masaüstü ve mobil, hover, boş, yükleniyor) ekleyin.", "İstemde belirgin olun; belirsiz istemler güçlü bir ajanla bile jenerik UI üretir.", "Tasarım sisteminizi ve kurallarınızı AGENTS.md içinde tutun ve Kimi'ye token'ların ve standart ilkellerin nerede olduğunu söyleyin.", "Bir geliştirme sunucusu çalıştırın ve Kimi'nin sonucu kontrol etmek için kırılma noktalarına yeniden boyutlandırarak gerçek bir tarayıcıda işlemesini sağlayın.", "Kimi'nin uygulamasını referanslara geri karşılaştırmasını sağlayarak yineleyin — yalnızca derlendiğini onaylamak değil."]}, {"kind": "p", "text": "Kimi'yi referanslarınıza ve geliştirme sunucusuna yönlendirin, ardından somut kısıtlamalar verin:"}, {"kind": "code", "lang": "bash", "code": "kimi\n# in the prompt:\n> Implement the design in ./references (reference-desktop.png,\n  reference-mobile.png) using React + Vite + Tailwind + TypeScript.\n  Reuse my existing design-system components and tokens from AGENTS.md.\n  Match spacing, layout, and hierarchy; make it responsive.\n  Run the dev server, render it in the browser, and iterate until it\n  matches the references across breakpoints."}, {"kind": "p", "text": "İstemleri küçük ve odaklı tutun, iyi yinelemeleri commit edin ve kötüleri geri alın (geri aldığınızda Kimi'ye söyleyerek), böylece her geçiş temiz bir temel üzerine inşa edilir. Kimi CLI ayrıca bir akışı kelimelerle tanımlamak zor olduğunda kısa bir ekran kaydı veya demo klibi de alabilir."}]}, {"id": "extend", "heading": "AGENTS.md, MCP ve alt ajanlar", "blocks": [{"kind": "p", "text": "Üç uzantı noktası Kimi CLI'yi sürekli tasarım çalışmaları için pratik kılar ve üçü de açık bir tasarım iş akışına temiz bir şekilde eşlenir."}, {"kind": "steps", "items": [{"label": "AGENTS.md bağlamı", "body": "Proje kuralları depo kökünde bir AGENTS.md içinde yaşar. Her çalıştırmada okunan, tasarım kurallarınızın kalıcı yuvasıdır — ve diğer ajanların kullandığı aynı taşınabilir biçimdir."}, {"label": "MCP sunucuları", "body": "MCP sunucularını /mcp-config ile sohbet ederek ekleyin — en alakalı olarak Figma MCP sunucusu olmak üzere, yalnızca Kimi'de değil ajanlar genelinde çalışan, tasarım bağlamını ve harici araçları getirmenin taşınabilir yolu."}, {"label": "Alt ajanlar ve eklenti pazaryeri", "body": "İzole bağlamlarda yerleşik coder, explore ve plan alt ajanlarını gönderin ve referans toplamak ile doğrulama döngüsünü çalıştırmak için pazaryerinden veya herhangi bir GitHub deposundan beceriler, MCP sunucuları ve veri kaynakları yükleyin."}]}, {"kind": "p", "text": "Bunlar taşınabilir, çok ajanlı yeteneklerdir — Open Design'ın proje başına yeniden oluşturmak yerine orkestre etmek için inşa edildiği türden tam olarak budur."}]}, {"id": "vs", "heading": "Tasarım için Kimi CLI vs Codex vs Claude Code vs Cursor vs Gemini CLI", "blocks": [{"kind": "p", "text": "Tasarım çalışmaları için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler onları üst üste koyar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["Kimi CLI", "Uzun ufuklu kodlama ve araç kullanımı için ayarlanmış ajansal Kimi K2 modelleri, büyük bir bağlamla; açık kaynaklı ve BYOK", "Çok adımlı derlemeler ve bütün bir tasarım sistemini bağlamda uygun fiyatla tutma"], ["Codex", "Ön uç becerisiyle güçlü görsel cila; sandbox'lı eşzamansız derlemeler", "Devredilmiş eşzamansız derlemeler ve taşınabilir AGENTS.md kuralları"], ["Claude Code", "Belirli tasarım kararları (hex, boşluk, tipografi) ve kod tabanından haberdar UX", "Ön uç muhakemesi ve büyük bağlamlı yeniden düzenlemeler"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"], ["Gemini CLI", "Güçlü çok modlu görüntü anlama ve 1M token'lık bir bağlam; ücretsiz katman", "Ekran görüntüsü ağırlıklı çalışma ve çok büyük bağlam"]]}, {"kind": "p", "text": "Tekrarlayan topluluk kanaati, zevkin insanlardan geldiğidir: hepsi beceriler, referanslar ve kısıtlamalar olmadan jenerik bir estetiğe varsayılan olur. Çözülmesi gereken gerçek sorun budur — ve bu, model biçimli değil, tasarım aracı biçimlidir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “yapay zeka çorbası” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Yapay zeka tarafından üretilen tasarım hakkında en yaygın şikayet, jenerik göründüğüdür — yumuşak gradyanlar, yüzen paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir yapay zekanın yaptığını haykıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında bozuk mobil düzenler ve talimatların UI metnine sızması yer alır. Bunların hiçbiri Kimi CLI'ye özgü değildir; herhangi bir ajan özenle seçilmiş bir tasarım bağlamı olmadan çalıştığında olan şeydir."}, {"kind": "steps", "items": [{"label": "Estetik bir beceri ekleyin", "body": "Özenle seçilmiş bir tasarım becerisi, ajanı varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Gerçek bir tarayıcıda doğrulayın", "body": "Kimi'nin kırılma noktaları genelinde işlemesini ve öz-denetim yapmasını sağlayın, böylece düzenler mobilde sessizce bozulmaz."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve referans ekran görüntüleri, çıktı kalitesi üzerindeki tek en büyük kaldıraçtır."}, {"label": "Kuralları AGENTS.md içinde kodlayın", "body": "“Kahraman kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Her hafifletmenin ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı angaryadır."}]}, {"id": "open-design", "heading": "Open Design içinde Kimi CLI ile tasarlamak", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. Kimi CLI'yi birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesine, yapılandırılmış bir işleme hattına ve yerel bir masaüstü UI'sine sarar — böylece Kimi'yi iyi yapan tasarım bağlamı, her seferinde elle birleştirilmek yerine ilk çalıştırmadan itibaren oradadır. Her ikisi de açık kaynaklı ve yerel önceliklidir, ki bu da eşleşmeyi doğal bir uyum kılar."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak Kimi CLI'yi seçin.", "Moonshot API anahtarınızla (BYOK) kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy yapılmaz.", "Bir tasarım sistemi ve bir beceri seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları oluşturun.", "Her üretim ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi deponuzda yaşar."]}, {"kind": "p", "text": "Aynı Kimi CLI ajanı, aynı anahtar — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0'dır, böylece çalışmanız veya kimlik bilgilerinizle ilgili hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "Kimi CLI gerçekten tasarım çalışması yapabilir mi?", "text": "Evet — bağlamda estetik bir beceri, bir tasarım sistemi ve gerçek referans görüntülerle, Kimi CLI üretim kalitesinde, duyarlı UI üretir ve ajansal Kimi K2 modelleri çıktıyı referanslara karşı işleyebilir ve doğrulayabilir. Bu bağlam olmadan jenerik bir görünüme varsayılan olma eğilimindedir; bu da Open Design'ın doldurduğu boşluktur."}, {"name": "Kimi CLI ile tasarım yapmak için ödeme yapmam gerekir mi?", "text": "Kendi kimlik bilgilerinizi getirirsiniz: Kimi Code OAuth girişi ile yetkilendirin veya bir Moonshot API anahtarı (BYOK) yapıştırın, Moonshot'un platformu tarafından faturalandırılır. Open Design her iki durumda da kimlik bilgilerinizi asla proxy yapmaz."}, {"name": "Kimi CLI'yi özellikle tasarım için iyi yapan nedir?", "text": "İki şey: Kimi K2 modelleri ajansal, uzun ufuklu kodlama ve araç kullanımı için ayarlanmıştır, böylece ajan çalışan bir sonuca kadar inşa edebilir ve iyileştirebilir; ve bağlam penceresi 256k token'a kadar ulaşır, bütün bir tasarım sistemini ve referans setini bir kerede tutacak kadar. Her ikisi de yardımcı olur — ama zevk yine de sağladığınız tasarım sisteminden, beceriden ve referanslardan gelir."}, {"name": "Ön uç tasarımı için Kimi CLI mi Claude Code mu?", "text": "Her ikisi de güçlüdür. Claude Code, belirli, kod tabanından haberdar tasarım kararlarıyla bilinir; Kimi CLI'nin avantajı, ajansal Kimi K2 modelleri ve BYOK ekonomisiyle büyük bir bağlamdır. Birçok ekip her ikisini de kullanır — Open Design, tasarım iş akışınızı değiştirmeden ajan değiştirmenize izin verir."}, {"name": "Kimi CLI'yi Figma'ya nasıl bağlarım?", "text": "Figma MCP sunucusunu eklemek ve kimliğini doğrulamak için Kimi CLI içinde /mcp-config çalıştırın. Kimi daha sonra gerçek tasarım bağlamı çekebilir — bileşenler, değişkenler, düzen verileri — böylece üretilen kod yaklaşık değer yerine kaynağa eşleşir."}, {"name": "Open Design Moonshot AI ile bağlantılı mı?", "text": "Hayır. Kimi CLI, Moonshot AI'nin bir ürünüdür; Open Design, onu birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynak projesidir. Kimi, Moonshot AI'nin ticari markasıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel öncelikli ve Apache-2.0'dır. Dosyalarınız, üretimleriniz ve DESIGN.md'niz kendi deponuzda kalır ve Moonshot kimlik bilgileriniz doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "Kimi CLI ile açık yoldan tasarlayın.", "ctaBody": "Kendi Moonshot API anahtarınızı getirin, her dosyayı yerel tutun ve zaten kullandığınız ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "Kimi CLI'yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
      'deepseek': {
        ...en['deepseek']!,
        title: "Tasarım için DeepSeek TUI — Open Design",
        description: "İnsanlar DeepSeek destekli bir terminal kodlama ajanını UI ve web tasarımı için nasıl kullanıyor — güçlü kodlama modelleri, 1M token'lık bağlam, maliyet verimliliği, bağlam dosyaları ve MCP — ve Open Design, DeepSeek TUI'yi yerel öncelikli, açık kaynaklı bir tasarım ajanına nasıl dönüştürüyor.",
        breadcrumb: "DeepSeek TUI",
        label: "Ajan · DeepSeek TUI",
        heading: "Tasarım için DeepSeek TUI.",
        lead: "DeepSeek TUI, DeepSeek'in modelleri tarafından sürülen bir terminal kodlama ajanıdır. Güçlü, maliyet açısından verimli kodlama modelleri ve 1M token'lık bağlamı, bütün bir tasarım sistemini ve kod tabanını bir kerede tutabilir, ki bu da ona referanslar, kurallar ve bir doğrulama döngüsü verdiğinizde onu gerçek bir tasarım aracı yapar. Open Design onu açık kaynaklı bir tasarım iş akışına bağlar: kendi DeepSeek API anahtarınız, kendi dosyalarınız, yerel öncelikli.",
        rich: {"heroCtaLead": "Open Design, DeepSeek TUI'yi yerel öncelikli, açık kaynaklı bir tasarım ajanına dönüştürür — kendi DeepSeek API anahtarınız, kendi dosyalarınız ve etrafında özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesi.", "heroCtaActions": [{"label": "DeepSeek TUI'yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "intro": ["DeepSeek TUI, DeepSeek'in modelleri tarafından desteklenen terminal tabanlı bir yapay zeka kodlama ajanıdır. Özellikle tasarım açısından onu ilginç kılan iki şey var: kodlama modelleri güçlü ve alışılmadık şekilde maliyet açısından verimlidir, böylece bir sayacı izlemeden agresif bir şekilde yineleyebilirsiniz; ve bağlam penceresi 1M token'a ulaşır, bütün bir tasarım sistemini ve kod tabanını özetleyerek elemek yerine bir kerede tutacak kadar büyük. Doğru referanslar, kurallar ve bir doğrulama döngüsüyle eşleştirildiğinde gerçek, duyarlı UI üretir. Bu, DeepSeek destekli bir terminal ajanını UI, ön uç ve tasarım sistemi çalışmaları için kullanmaya ve onu Open Design ile yapılandırılmış bir tasarım iş akışına bağlamaya yönelik pratik, uçtan uca bir kılavuzdur.", "DeepSeek TUI'nin gerçekte ne olduğunu, güçlü kodlama modellerinin, devasa bir bağlamın ve düşük maliyetin tasarıma neden uyduğunu, sıfırdan nasıl kurulacağını, referanstan UI'ye döngüyü, bağlam dosyalarının ve MCP'nin onu nasıl genişlettiğini, Codex, Claude Code, Cursor ve Gemini CLI ile nasıl karşılaştırıldığını, yapay zeka çıktısını jenerik gösteren tuzakları ve Open Design'ın açık, yerel öncelikli bir tasarım katmanı olarak boşluğu nasıl kapattığını kapsar — doğal bir eşleşme, çünkü her ikisi de açık ve kendi makinenizde çalışıyor."], "heroImage": {"src": "/agents/deepseek-design/deepseek-design-hero.webp", "alt": "DeepSeek TUI tasarım geri bildirim döngüsü: referansları ve kuralları okuyan bir terminal ajanı, UI'yi işleyen bir tarayıcı ve bir çalışma alanı, geri döngü yapan bir geri bildirim okuyla", "caption": "Temel döngü: DeepSeek TUI referanslarınızı ve kurallarınızı terminalde okur, UI'yi gerçek bir tarayıcıda oluşturup doğrular ve onlara karşı yineler — bütün bir tasarım sistemi bağlamda."}, "tocLabel": "Bu sayfada", "toc": [{"id": "what-is-deepseek", "label": "DeepSeek TUI gerçekte nedir"}, {"id": "why-design", "label": "Güçlü kodlama modelleri + devasa bağlam tasarıma neden uyar"}, {"id": "setup", "label": "Tasarım için DeepSeek TUI'yi kurun (sıfırdan)"}, {"id": "screenshot-workflow", "label": "Referanstan UI'ye iş akışı"}, {"id": "extend", "label": "Bağlam dosyaları, MCP ve araçlar"}, {"id": "vs", "label": "DeepSeek TUI vs Codex vs Claude Code vs Cursor vs Gemini CLI"}, {"id": "pitfalls", "label": "Tuzaklar ve “yapay zeka çorbası” görünümü"}, {"id": "open-design", "label": "Open Design'da DeepSeek TUI ile tasarlamak"}, {"id": "faq", "label": "SSS"}], "sections": [{"id": "what-is-deepseek", "heading": "DeepSeek TUI gerçekte nedir", "blocks": [{"kind": "p", "text": "Bir DeepSeek TUI, DeepSeek'in modellerini çalıştıran, klavye odaklı bir terminal yapay zeka ajanıdır. Deponuzu okur, dosyaları düzenler, kabuk komutları çalıştırır, git'i yönetir ve web'de arama yapabilir — yalnızca satırları tamamlamak yerine doğal dildeki görevlerden plan yapar ve işi doğrular. DeepSeek'in kendisi model sağlayıcısıdır: OpenAI uyumlu bir API (ayrıca Anthropic biçimli bir uç nokta da sunar), böylece çok çeşitli topluluk terminal ajanları bir temel URL ve anahtar ayarlayarak DeepSeek'e yönlendirilebilir. Birkaç açık kaynaklı TUI, DeepSeek'i birinci sınıf bir sağlayıcı olarak getirir."}, {"kind": "p", "text": "Tasarım çalışmaları için üç özellik öne çıkar. DeepSeek'in kodlama modelleri güçlüdür, böylece ajan net bir açıklamadan düzen, yapı ve bileşen hiyerarşisi hakkında muhakeme yapar. Bağlam penceresi 1M token'a ulaşır, bütün tasarım sisteminizi ve bileşen kütüphanenizi bir kerede tutacak kadar büyük. Ve fiyatlandırması token başına çok düşüktür, üzerine ön ek bağlam önbelleğe alma ile — böylece bir tasarım üzerinde yinelemek az maliyetlidir."}, {"kind": "steps", "items": [{"label": "Bağlam dosyaları", "body": "Terminal ajanları, kalıcı kurallar için bir proje bağlam dosyası okur (bir AGENTS.md tarzı dosya veya ajanın kendi kuralı) — tasarım kurallarınızı, token'larınızı ve inceleme kontrol listelerinizi kodlamak için doğal yer."}, {"label": "Araçlar + MCP", "body": "Çoğu DeepSeek TUI, dosya, kabuk, git ve web araçlarını getirir ve canlı bir Figma dosyası gibi harici bağlam eklemek için MCP sunucularını destekler — DeepSeek'in API'si bu ajanların dayandığı araç çağırmayı destekler."}, {"label": "Kendi anahtarınızı getirin", "body": "DeepSeek platformundan bir DeepSeek API anahtarıyla kimlik doğrularsınız. API OpenAI uyumlu olduğundan, bir ajanı DeepSeek'e yönlendirmek genellikle iki satırdır: temel URL ve anahtar."}]}, {"kind": "ul", "items": ["Sağlayıcı: DeepSeek (model ve API sağlayıcısı)", "Kimlik bilgisi: DeepSeek platformundan DeepSeek API anahtarı (BYOK)", "Modeller: deepseek-v4-flash ve deepseek-v4-pro (yalnızca metin; yerel görüntü girdisi yok)"]}]}, {"id": "why-design", "heading": "Güçlü kodlama modelleri ve devasa bir bağlam tasarıma neden uyar", "blocks": [{"kind": "p", "text": "DeepSeek TUI'nin tasarım avantajı modelden ve ekonomisinden gelir — ama her ajanda olduğu gibi, zevkin yine de sağlanması gerekir."}, {"kind": "steps", "items": [{"label": "Güçlü, maliyet açısından verimli kodlama", "body": "DeepSeek'in kodlama modelleri yetenekli ve ucuzdur, böylece ajan düzen ve yapı hakkında iyi muhakeme yapar ve maliyet kısıtlama olmadan birçok kez yineleyebilirsiniz."}, {"label": "1M token'lık bir bağlam penceresi", "body": "Büyük bir bağlam, bütün tasarım sisteminin, token'ların ve birçok referans durumunun bir kerede sığması anlamına gelir, böylece ajan tek seferlik stiller icat etmek yerine gerçek ilkellerinizi yeniden kullanır — ve bağlam önbelleğe alma, tekrarlanan istemleri ucuz tutar."}, {"label": "Bir bağlam dosyasındaki kurallar", "body": "Bir proje bağlam dosyası (artı Figma MCP sunucusu) ajanı token'larınıza, bileşenlerinize ve gerçek spesifikasyonlarınıza yönlendirir, böylece varsayılan bir görünüm yerine bir markaya karşı çalışır."}]}, {"kind": "image", "src": "/agents/deepseek-design/deepseek-design-taste-triangle.webp", "alt": "Tasarım sistemi, beceri ve referansın iyi tasarım çıktısında birleştiğini gösteren diyagram", "caption": "Zevk, sağladığınız üç girdiden gelir: bir tasarım sistemi, bir beceri ve gerçek referanslar."}, {"kind": "p", "text": "Ders, her ajanın öğrettiğiyle aynıdır: DeepSeek TUI varsayılan olarak zevke sahip değildir. Ona kısıtlamalar verdiğinizde — bir tasarım sistemi, estetik bir beceri ve somut referanslar — iyi tasarım üretir. Open Design tam olarak bu girdileri paketler, bu yüzden ikisi birbirine uyar (aşağıda daha fazlası)."}]}, {"id": "setup", "heading": "Tasarım çalışmaları için DeepSeek TUI'yi sıfırdan kurun", "blocks": [{"kind": "p", "text": "Temiz bir makineden, UI oluşturup doğrulayabilen bir DeepSeek TUI'ye giden tam yol burada. Tam kurulum ve komut adları seçtiğiniz terminal ajanına göre değişir, bu yüzden aşağıdaki adımlar hepsinde geçerli olan düzeyde kalır."}, {"kind": "code", "lang": "bash", "code": "# 1. Get a DeepSeek API key from the DeepSeek platform\n#    https://platform.deepseek.com\nexport DEEPSEEK_API_KEY=sk-...\n\n# 2. Install a DeepSeek-capable terminal agent (follow its README),\n#    then point it at DeepSeek. The API is OpenAI-compatible:\n#      base URL: https://api.deepseek.com\n#      model:    deepseek-v4-flash (or deepseek-v4-pro)\n#    (an Anthropic-format endpoint also exists at /anthropic)\n\n# 3. Start it in your project and generate project context\ncd your-project\n#   create/scaffold a project context file with your design rules\n\n# 4. Wire the Figma MCP server (optional, for design handoff)\n#    add it to the agent's MCP server configuration"}, {"kind": "image", "src": "/agents/deepseek-design/deepseek-design-setup-flow.webp", "alt": "Beş adımlı kurulum akışı: anahtar al, ajan kur, bağlam dosyası yapılandır, bir beceri ekle, doğrula", "caption": "Kurulum sırası: bir anahtar al → ajanı DeepSeek'e yönlendir → bir bağlam dosyası yapılandır → bir beceri ekle → tarayıcı doğrulamasını etkinleştir."}, {"kind": "steps", "items": [{"label": "Tasarım kurallarınızı kodlayın", "body": "Token'larınızı, ilkellerinizi ve kurallarınızı ajanın bağlam dosyasına koyun ve onu onlara yönlendirin, böylece çıktı jenerik bir görünüme varsayılan olmak yerine bir markayla eşleşir."}, {"label": "Tarayıcı doğrulaması ekleyin", "body": "Bir Playwright veya tarayıcı MCP'si bağlayın, böylece ajan gerçek bir tarayıcıda işler ve yalnızca derlemenin geçtiğini onaylamak yerine çıktısını kırılma noktaları genelinde kontrol eder."}]}]}, {"id": "screenshot-workflow", "heading": "Referanstan UI'ye iş akışı", "blocks": [{"kind": "p", "text": "DeepSeek'in modelleri yalnızca metindir — görüntüleri yerel olarak okumazlar — bu yüzden en yüksek kaldıraçlı tasarım döngüsü, net referansları ve tanımlanmış düzenleri çalışan, duyarlı UI'ye dönüştürmek, ardından modelden bir ekran görüntüsüne bakmasını istemek yerine sonucu gerçek bir tarayıcıda doğrulamaktır."}, {"kind": "ol", "items": ["Elinizdeki en net referanslardan başlayın — ve yalnızca tek bir kahraman görüntü değil, birden fazla durumu (masaüstü ve mobil, hover, boş, yükleniyor) tanımlayın.", "İstemde belirgin olun; belirsiz istemler güçlü bir modelle bile jenerik UI üretir. Boşluğu, hiyerarşiyi ve yeniden kullanılacak bileşenleri ayrıntılı belirtin.", "Tasarım sisteminizi ve kurallarınızı bağlam dosyasında tutun ve ajana token'ların ve standart ilkellerin nerede olduğunu söyleyin.", "Bir geliştirme sunucusu çalıştırın ve ajanın sonucu kontrol etmek için kırılma noktalarına yeniden boyutlandırarak gerçek bir tarayıcıda işlemesini sağlayın — doğrulamanın gerçekleştiği yer burasıdır, çünkü model görüntünün kendisini göremez.", "Ajanın işlenmiş DOM'u ve hesaplanmış stilleri, tanımladığınız spesifikasyonla geri karşılaştırmasını sağlayarak yineleyin — yalnızca derlendiğini onaylamak değil."]}, {"kind": "p", "text": "Hedefi tam olarak tanımlayın ve somut kısıtlamalar verin:"}, {"kind": "code", "lang": "bash", "code": "# in the agent's prompt:\n> Implement this design in React + Vite + Tailwind + TypeScript.\n  Layout: two-column dashboard, 240px sidebar, 24px gutters,\n  card grid at 3/2/1 columns for desktop/tablet/mobile.\n  Reuse my existing design-system components and tokens from the\n  context file. Match spacing, layout, and hierarchy; make it responsive.\n  Run the dev server, render it in the browser, and iterate against the\n  spec across breakpoints until it matches."}, {"kind": "p", "text": "İstemleri küçük ve odaklı tutun, iyi yinelemeleri commit edin ve kötüleri geri alın (geri aldığınızda ajana söyleyerek), böylece her geçiş temiz bir temel üzerine inşa edilir."}]}, {"id": "extend", "heading": "Bağlam dosyaları, MCP ve araçlar", "blocks": [{"kind": "p", "text": "Üç uzantı noktası bir DeepSeek TUI'yi sürekli tasarım çalışmaları için pratik kılar ve üçü de açık bir tasarım iş akışına temiz bir şekilde eşlenir."}, {"kind": "steps", "items": [{"label": "Proje bağlam dosyası", "body": "Proje kuralları depo kökünde bir bağlam dosyasında yaşar (genel ve ekip katmanlarıyla). Her çalıştırmada okunan, tasarım kurallarınızın kalıcı yuvasıdır."}, {"label": "MCP sunucuları", "body": "Ajanda MCP sunucularını yapılandırın — en alakalı olarak Figma MCP sunucusu olmak üzere, yalnızca birinde değil ajanlar genelinde çalışan, tasarım bağlamını ve harici araçları getirmenin taşınabilir yolu. DeepSeek'in API'si bu sunucuların dayandığı araç çağırmayı destekler."}, {"label": "Yerleşik araçlar", "body": "DeepSeek TUI'leri, dosya, kabuk, git ve web araçlarını getirir, böylece ajan terminalden ayrılmadan referans toplayabilir ve doğrulama döngüsünü çalıştırabilir."}]}, {"kind": "p", "text": "Bunlar taşınabilir, çok ajanlı yeteneklerdir — Open Design'ın proje başına yeniden oluşturmak yerine orkestre etmek için inşa edildiği türden tam olarak budur."}]}, {"id": "vs", "heading": "Tasarım için DeepSeek TUI vs Codex vs Claude Code vs Cursor vs Gemini CLI", "blocks": [{"kind": "p", "text": "Tasarım çalışmaları için tek bir kazanan yoktur — her ajanın farklı bir gücü vardır ve deneyimli ekipler onları üst üste koyar. Adil bir özet:"}, {"kind": "table", "columns": ["Ajan", "Tasarım gücü", "En iyi olduğu alan"], "rows": [["DeepSeek TUI", "Açık ağırlıklı ve 1M token'lık bir bağlama sahip güçlü, çok maliyet verimli kodlama modelleri; yalnızca metin (yerel görü yok)", "Bütçeyle yüksek hacimli yineleme ve bütün bir tasarım sistemini bağlamda tutma"], ["Codex", "Ön uç becerisiyle güçlü görsel cila; sandbox'lı eşzamansız derlemeler", "Devredilmiş eşzamansız derlemeler ve taşınabilir AGENTS.md kuralları"], ["Claude Code", "Belirli tasarım kararları (hex, boşluk, tipografi) ve kod tabanından haberdar UX", "Ön uç muhakemesi ve büyük bağlamlı yeniden düzenlemeler"], ["Cursor", "Canlı önizleme ve satır içi düzenlemelerle görsel oluştur-ve-gör döngüsü", "Bir IDE içinde sıkı yinele-ve-izle UI çalışması"], ["Gemini CLI", "Yerel çok modlu görüntü anlama ve 1M token'lık bir bağlam; ücretsiz katmanlı açık kaynak", "Ajanın referansları doğrudan okuduğu ekran görüntüsü ağırlıklı çalışma"]]}, {"kind": "p", "text": "Tekrarlayan topluluk kanaati, zevkin insanlardan geldiğidir: hepsi beceriler, referanslar ve kısıtlamalar olmadan jenerik bir estetiğe varsayılan olur. Çözülmesi gereken gerçek sorun budur — ve bu, model biçimli değil, tasarım aracı biçimlidir."}]}, {"id": "pitfalls", "heading": "Tuzaklar ve “yapay zeka çorbası” görünümünden nasıl kaçınılır", "blocks": [{"kind": "p", "text": "Yapay zeka tarafından üretilen tasarım hakkında en yaygın şikayet, jenerik göründüğüdür — yumuşak gradyanlar, yüzen paneller, aşırı büyük yuvarlatılmış köşeler, dramatik gölgeler, “bunu bir yapay zekanın yaptığını haykıran” bir Inter-ve-mor havası. Bildirilen diğer sorunlar arasında bozuk mobil düzenler ve talimatların UI metnine sızması yer alır. Bunların hiçbiri DeepSeek TUI'ye özgü değildir; herhangi bir ajan özenle seçilmiş bir tasarım bağlamı olmadan çalıştığında olan şeydir. DeepSeek yalnızca metin olduğundan, sonucu modelin “görmesine” güvenmek yerine gerçek bir tarayıcıda doğrulamak özellikle önemlidir."}, {"kind": "steps", "items": [{"label": "Estetik bir beceri ekleyin", "body": "Özenle seçilmiş bir tasarım becerisi, ajanı varsayılan görünüm yerine gerçek bir yöne bağlanmaya zorlar."}, {"label": "Gerçek bir tarayıcıda doğrulayın", "body": "Bir tarayıcı aracıyla kırılma noktaları genelinde işleyin ve öz-denetim yapın — burada esastır, çünkü model bir ekran görüntüsünü kendisi okuyamaz — böylece düzenler mobilde sessizce bozulmaz."}, {"label": "Token ve referans sağlayın", "body": "Gerçek tasarım token'ları ve somut, tanımlanmış referanslar, çıktı kalitesi üzerindeki tek en büyük kaldıraçtır."}, {"label": "Kuralları bağlam dosyasında kodlayın", "body": "“Kahraman kartı yok, en fazla iki yazı tipi, marka öncelikli hiyerarşi” gibi kuralları, ajanın her çalıştırmada okuduğu yere koyun."}]}, {"kind": "p", "text": "Her hafifletmenin ajana özenle seçilmiş bir tasarım bağlamı vermekle ilgili olduğuna dikkat edin. Bu bağlamı proje başına elle sürdürmek, Open Design'ın ortadan kaldırdığı angaryadır."}]}, {"id": "open-design", "heading": "Open Design içinde DeepSeek TUI ile tasarlamak", "blocks": [{"kind": "p", "text": "Open Design, yukarıdaki iş akışının sürekli istediği açık kaynaklı tasarım katmanıdır. DeepSeek ajanını birinci taraf bir adaptör olarak ele alır ve onu özenle seçilmiş bir beceri ve tasarım sistemi kütüphanesine, yapılandırılmış bir işleme hattına ve yerel bir masaüstü UI'sine sarar — böylece DeepSeek'i iyi yapan tasarım bağlamı, her seferinde elle birleştirilmek yerine ilk çalıştırmadan itibaren oradadır. Her ikisi de açık ve yerel önceliklidir, ki bu da eşleşmeyi doğal bir uyum kılar."}, {"kind": "ol", "items": ["Open Design'ı kurun ve ajanınız olarak DeepSeek TUI'yi seçin.", "Kendi DeepSeek API anahtarınızla (BYOK) kimlik doğrulayın — kimlik bilgileri makinenizde kalır ve asla bizim üzerimizden proxy yapılmaz.", "Bir tasarım sistemi ve bir beceri seçin, ardından tutarlı bir zevkle sunumlar, prototipler ve açılış sayfaları oluşturun.", "Her üretim ve DESIGN.md dosyası, barındırılan bir bulutta değil, kendi deponuzda yaşar."]}, {"kind": "p", "text": "Aynı DeepSeek ajanı, aynı anahtar — artı etrafında gerçek, taşınabilir, açık kaynaklı bir tasarım iş akışı. Yerel öncelikli ve Apache-2.0'dır, böylece çalışmanız veya kimlik bilgilerinizle ilgili hiçbir şey makinenizden ayrılmaz."}]}], "faqTitle": "Sıkça sorulan sorular", "faq": [{"name": "DeepSeek TUI gerçekten tasarım çalışması yapabilir mi?", "text": "Evet — bağlamda estetik bir beceri, bir tasarım sistemi ve somut referanslarla, DeepSeek destekli bir terminal ajanı üretim kalitesinde, duyarlı UI üretir ve çıktıyı gerçek bir tarayıcıda doğrularsınız. DeepSeek'in modelleri yalnızca metindir, bu yüzden doğrulama döngüsü yerel görüntü okumanın yerini alır. Bu bağlam olmadan jenerik bir görünüme varsayılan olma eğilimindedir; bu da Open Design'ın doldurduğu boşluktur."}, {"name": "DeepSeek TUI ile tasarım yapmak ne kadara mal olur?", "text": "Az — DeepSeek'in API'si token başına en ucuzlar arasındadır ve ön ek bağlam önbelleğe alma, tekrarlanan istemlerin maliyetini daha da düşürür, böylece agresif bir şekilde yineleyebilirsiniz. Kendi DeepSeek API anahtarınızı getirirsiniz (BYOK); Open Design kimlik bilgilerinizi asla proxy yapmaz."}, {"name": "DeepSeek'i özellikle tasarım için iyi yapan nedir?", "text": "Güçlü, maliyet açısından verimli kodlama modelleri, açık ağırlıklar ve bütün bir tasarım sistemini ve referans setini bir kerede tutan 1M token'lık bir bağlam. DeepSeek yalnızca metindir — görüntüleri yerel olarak okumaz — bu yüzden zevk yine de bir tarayıcıda doğrulanmış olarak sağladığınız tasarım sisteminden, beceriden ve tanımlanmış referanslardan gelir."}, {"name": "Ön uç tasarımı için DeepSeek TUI mi Claude Code mu?", "text": "Her ikisi de güçlüdür. Claude Code, belirli, kod tabanından haberdar tasarım kararlarıyla bilinir; DeepSeek TUI'nin avantajı, açık ağırlıklar, çok düşük maliyet ve yüksek hacimli yineleme için devasa bir bağlamdır. Birçok ekip her ikisini de kullanır — Open Design, tasarım iş akışınızı değiştirmeden ajan değiştirmenize izin verir."}, {"name": "DeepSeek TUI'yi Figma'ya nasıl bağlarım?", "text": "Terminal ajanınızın MCP yapılandırmasına Figma MCP sunucusunu ekleyin. Ajan daha sonra gerçek tasarım bağlamı çekebilir — bileşenler, değişkenler, düzen verileri — böylece üretilen kod yaklaşık değer yerine kaynağa eşleşir. DeepSeek'in API'si MCP'nin dayandığı araç çağırmayı destekler."}, {"name": "Open Design DeepSeek ile bağlantılı mı?", "text": "Hayır. DeepSeek, model ve API sağlayıcısıdır; Open Design, DeepSeek destekli terminal ajanlarını birinci taraf bir adaptör olarak destekleyen bağımsız bir açık kaynak projesidir. DeepSeek, DeepSeek'in ticari markasıdır."}, {"name": "Dosyalarım ve kimlik bilgilerim güvende mi?", "text": "Evet — Open Design yerel öncelikli ve Apache-2.0'dır. Dosyalarınız, üretimleriniz ve DESIGN.md'niz kendi deponuzda kalır ve DeepSeek API anahtarınız doğrudan ajanınız tarafından kullanılır, asla Open Design sunucuları üzerinden yönlendirilmez."}], "ctaTitle": "DeepSeek TUI ile açık yoldan tasarlayın.", "ctaBody": "Kendi DeepSeek API anahtarınızı getirin, her dosyayı yerel tutun ve zaten kullandığınız ajanın etrafında özenle seçilmiş bir tasarım kütüphanesi edinin.", "ctaActions": [{"label": "DeepSeek TUI'yi Open Design içinde kullanın", "href": "/quickstart/", "variant": "primary"}, {"label": "GitHub'da yıldız verin", "href": "https://github.com/nexu-io/open-design", "variant": "ghost", "external": true}, {"label": "Masaüstü uygulamasını indirin", "href": "https://github.com/nexu-io/open-design/releases", "variant": "ghost", "external": true}], "hubLinkLabel": "Desteklenen tüm ajanları görün"},
      },
    },
  };
}
